_LABEL_STROKE_FONTS = {
    'SMOOTH': (FONT_SMOOTH, FONT_META_SMOOTH, False),
    'MONO':   (FONT_MONO, FONT_META_MONO, True),
    'COND':   (FONT_COND, FONT_META_COND, False),
    'NARROW': (FONT_NARROW, FONT_META_NARROW, False),
    'CAPS':   (FONT_CAPS, FONT_META_CAPS, False),
    'SCRIPT': (FONT_SCRIPT, FONT_META_SCRIPT, False),
    'HAND':   (FONT_HAND, FONT_META_HAND, False),
    'PLATE':  (FONT_PLATE, FONT_META_PLATE, False),
    # R286 (Befund 4b): PIXEL retired (R80 field log .63: unreadable + the
    # MCU-Shutdown risk) - removed from the printable fonts. A saved PIXEL
    # selection falls back to SMOOTH (the normalization above).
}
_LABEL_FONT_CACHE = {}
# R286: hard cap on the font-glyph cache (see the store site below). Bounded
# cache = bounded long-lived watcher RAM; the cache is only a render speed-up.
_LABEL_FONT_CACHE_MAX = 100


def _label_glyphs(font):
    """font name -> {'height', 'baseline', 'cap_top', 'x_top', 'desc_bot',
    'cap_units', 'x_units', ' ': (adv, []), char: (adv, strokes)}.

    R73: the stroke fonts are BASELINE-ALIGNED (uy = 'baseline' on the baseline,
    cap tops near uy = 'cap_top', x-height tops at 'x_top', descenders down to
    'desc_bot'). 'cap_units'/'x_units' are the printed heights of a cap / a
    lowercase letter. _glyph_class() says whether a character renders FULL
    (cap height) or SMALL (x-height, like lowercase, @, >).
    """
    if font in _LABEL_FONT_CACHE:
        return _LABEL_FONT_CACHE[font]
    glyphs = {' ': (7.0 if font == 'MONO' else 3.0, [])}
    if font in _LABEL_STROKE_FONTS:
        data, meta, is_mono = _LABEL_STROKE_FONTS[font]
        glyphs['height'] = 10.0
        if is_mono:
            for ch, s in data.items():
                glyphs[ch] = (7.0, _parse_stroke_str(s))
            glyphs[' '] = (7.0, [])
        else:
            for ch, (adv, s) in data.items():
                glyphs[ch] = (float(adv), _parse_stroke_str(s))
    else:
        # unknown name (or a saved PIXEL selection) -> SMOOTH
        glyphs['height'] = 10.0
        for ch, (adv, s) in FONT_SMOOTH.items():
            glyphs[ch] = (float(adv), _parse_stroke_str(s))
    # ---- R73 runtime vertical metrics (from the real skeleton geometry) ----
    # the baseline sits at uy = cap units in every stroke font's box
    base = _LABEL_STROKE_FONTS.get(
        font, _LABEL_STROKE_FONTS['SMOOTH'])[1]['cap']
    tops = {}
    for ch, v in glyphs.items():
        if ch in (' ', 'height') or not v[1]:
            continue
        ys = [p[1] for st in v[1] for p in st]
        tops[ch] = (min(ys), max(ys))
    # cap line from the PLAIN A-Z only (umlaut dots sit above it and would
    # pull the line up); median so round overshoot (O, G) cannot skew it
    caps = [c for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' if c in tops]
    xs_ = [c for c in 'xonmuvwz' if c in tops]
    dess = [c for c in 'gjpqy\u00df,;' if c in tops]
    cap_sorted = sorted(tops[c][0] for c in caps)
    cap_top = cap_sorted[len(cap_sorted) // 2] if cap_sorted else base - 5.0
    x_top = sorted(tops[c][0] for c in xs_)[len(xs_) // 2] if xs_ else cap_top
    desc_bot = max((tops[c][1] for c in dess), default=base + 1.7)
    glyphs['baseline'] = base
    glyphs['cap_top'] = cap_top
    glyphs['x_top'] = x_top
    glyphs['desc_bot'] = desc_bot
    glyphs['cap_units'] = max(1.0, base - cap_top)
    glyphs['x_units'] = max(0.5, base - x_top)
    glyphs['height'] = desc_bot
    # R183 (.131b field round): COLLISION GUARD. SCRIPT and HAND carry
    # swash overhangs - ink reaching up to 1.7 units PAST the advance box
    # ('j' 3.5 ink on 1.8 advance), the next letter starts at its own left
    # bearing (~0.1) and the two INKS PRINT ON TOP OF EACH OTHER ('fj',
    # 'ji' -> mud). The advance now always covers the ink + 0.15 units of
    # air: script letters still VISUALLY touch, they just never collide.
    # Text gets slightly wider - the auto-fit answers with slightly
    # smaller caps, which is the honest trade.
    for _cg183 in list(glyphs.keys()):
        _cv183 = glyphs[_cg183]
        if not isinstance(_cv183, tuple) or not _cv183[1]:
            continue
        _xs183 = [p[0] for _s183 in _cv183[1] for p in _s183]
        # the advance must cover the ink END (its rightmost point), not
        # just its width - the ink often starts right of x=0
        _need183 = max(_xs183) + 0.15
        if _need183 > _cv183[0]:
            glyphs[_cg183] = (_need183, _cv183[1])
    # R286: bound the font-glyph cache - each distinct label font (and its
    # rendered glyph set) would otherwise accumulate in the long-lived
    # watcher daemon forever. Cap it; the cache is a pure speed-up, losing
    # it only costs a re-render on the next use of that font.
    if len(_LABEL_FONT_CACHE) >= _LABEL_FONT_CACHE_MAX:
        _LABEL_FONT_CACHE.clear()
    _LABEL_FONT_CACHE[font] = glyphs
    return glyphs


def _glyph_class(ch, font):
    """FULL (cap height) or SMALL (x-height) for one character (R73).

    User rule (R73 field log): lowercase letters - and correspondingly small
    signs like @ > < - print at 66% of the cap height, uppercase letters and
    digits at the full cap height. Plain geometric class, font-independent.
    """
    if 'A' <= ch <= 'Z' or ch in '\u00c4\u00d6\u00dc' or '0' <= ch <= '9':
        return 'FULL'
    return 'SMALL'    # lowercase (incl. umlauts/sz), punctuation, @ > < degree


def _label_text(text, font):
    """text -> (width_units, height_units, strokes [(x,y)..] with x offsets)"""
    glyphs = _label_glyphs(font)
    x = 0.0
    strokes = []
    for ch in text:
        adv, sts = glyphs.get(ch, glyphs.get(ch.upper(), (4.0, [])))
        for st in sts:
            strokes.append([(x + px, py) for (px, py) in st])
        x += adv
    return x, glyphs['height'], strokes


def _shape_hatch(contour, spacing, angle_deg, keep=None, min_len=0.35):
    """R119: scanline hatch INSIDE a convex contour (ellipse / rounded rect),
    optionally minus a circular keep-out (the label hole). Same boustrophedon
    neighbor rule as _hatch/_ring_hatch (R77: neighbors stay adjacent, the
    pen never zigzags across the shape)."""
    ang = math.radians(angle_deg)
    dx, dy = math.cos(ang), math.sin(ang)
    nx, ny = -dy, dx
    xs = [q[0] for q in contour]
    ys = [q[1] for q in contour]
    mx, my = (min(xs) + max(xs)) / 2.0, (min(ys) + max(ys)) / 2.0
    tmax = max(abs((qx - mx) * nx + (qy - my) * ny) for qx, qy in contour) + spacing
    segs = []
    row = 0
    t = -tmax
    while t <= tmax:
        ox, oy = mx + nx * t, my + ny * t
        ov = _convex_intervals(contour, ox, oy, dx, dy)
        if ov is None:
            t += spacing
            continue
        gaps = []
        if keep:
            vx, vy = keep[0] - ox, keep[1] - oy
            along = vx * dx + vy * dy
            perp = abs(-vx * dy + vy * dx)
            if perp < keep[2]:
                half = math.sqrt(keep[2] * keep[2] - perp * perp)
                gaps.append((along - half, along + half))
        gaps.sort()
        spans = []
        cur = ov[0]
        for g0, g1 in gaps:
            if g1 <= cur or g0 >= ov[1]:
                continue
            if g0 > cur:
                spans.append((cur, g0))
            cur = max(cur, g1)
        if cur < ov[1]:
            spans.append((cur, ov[1]))
        for s0, s1 in spans:
            if s1 - s0 < min_len:
                continue
            pp = (ox + dx * s0, oy + dy * s0)
            qq = (ox + dx * s1, oy + dy * s1)
            segs.append((qq, pp) if row % 2 else (pp, qq))
        if spans:
            row += 1
        t += spacing
    return segs


def _label_outline(w, h, shape, corner, inset):
    """R119: label wall contour CENTERED on (0,0), the path centerline
    `inset` mm inside the label edge. OVAL = ellipse, ROUND = rounded rect
    (corner shrinks with the inset), RECT = None (the classic rect loops
    stay - byte-identical output for the default path)."""
    if shape == 'OVAL':
        a, b = w / 2.0 - inset, h / 2.0 - inset
        if a < 0.3 or b < 0.3:
            return None
        return _el_pts(a, b)
    if shape == 'ROUND':
        c = max(0.0, corner - inset)
        ww, hh = w - 2.0 * inset, h - 2.0 * inset
        if ww < 0.6 or hh < 0.6:
            return None
        return _rr_pts(ww, hh, c)
    return None


def _stroke_offsets(pts, half, step):
    """R72: stroke skeleton -> parallel offset paths covering [-half, +half]
    SOLIDLY (line spacing = step = one extrusion width). The outermost paths
    are the two walls, the paths between them are the fill - the field log
    (.55) showed single-line characters are too fragile on a label.
    Mitered vertex offsets; the miter scale is capped so sharp skeleton
    corners cannot spike. Returns a list of point lists (print order:
    +half .. -half, serpentine-ready)."""
    # drop consecutive duplicate points (thinned skeletons contain them) -
    # a vertex without any adjacent segment would have no normal at all
    ded = [pts[0]]
    for q in pts[1:]:
        if math.hypot(q[0] - ded[-1][0], q[1] - ded[-1][1]) > 1e-6:
            ded.append(q)
    pts = ded
    segs = []
    for i in range(len(pts) - 1):
        dx, dy = pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]
        d = math.hypot(dx, dy)
        if d > 1e-6:
            segs.append((i, dx / d, dy / d))
    if not segs:
        return []
    nrm = []
    for j in range(len(pts)):
        n1 = n2 = None
        for (i, ux, uy) in segs:
            if i == j - 1:
                n1 = (-uy, ux)
            elif i == j:
                n2 = (-uy, ux)
        if n1 is None:
            n1 = n2
        if n2 is None:
            n2 = n1
        dot = n1[0] * n2[0] + n1[1] * n2[1]
        bx, by = n1[0] + n2[0], n1[1] + n2[1]
        bl = math.hypot(bx, by)
        if bl < 1e-6:
            nx, ny = n1
            m = 1.0
        else:
            m = 1.0 / max(0.62, math.sqrt(max(0.0, (1.0 + dot) / 2.0)))
            nx, ny = bx / bl * m, by / bl * m
        nrm.append((nx, ny))
    # line CENTERS reach +/-(half - step/2) so the covered width (each line is
    # 'step' wide) is exactly 2*half - symmetric, never one line wider.
    edge = half - step / 2.0
    if edge <= 0.05:
        return [list(pts)]          # stroke ~ one extrusion line: center line only
    n = int(math.ceil(2.0 * edge / step - 1e-9)) + 1
    if n < 2:
        n = 2
    edge2 = (n - 1) * step / 2.0
    if edge2 > edge + 1e-9:
        n -= 1
        edge2 = (n - 1) * step / 2.0
        # prefer one MORE line when the resulting width overshoots only a
        # little (<= 0.35*step): the stroke then matches the requested width
        if n >= 2 and (2.0 * (edge2 + step / 2.0) + step) - 2.0 * half <= 0.35 * step:
            n += 1
            edge2 = (n - 1) * step / 2.0
    return [[(x + nx * (edge2 - k * step), y + ny * (edge2 - k * step))
             for (x, y), (nx, ny) in zip(pts, nrm)] for k in range(n)]

def _label_box_shape(box, w, h, shape, corner, hole_side, band):
    """R119: shrink the text box for OVAL / ROUND labels so no letter ever
    leaves the base outline. OVAL: the largest centered rectangle with the
    box's own aspect that fits the ellipse (the hole side keeps its band -
    max() against the inscribed edge). ROUND: half the corner overshoot
    beyond the margin intrudes at the box corners."""
    if shape == 'OVAL':
        bw, bh = box[2] - box[0], box[3] - box[1]
        if bw <= 0.5 or bh <= 0.5:
            return box
        s = 1.0 / math.sqrt((bw / w) ** 2 + (bh / h) ** 2)
        if s >= 1.0:
            return box
        cx, cy = w / 2.0, h / 2.0
        ib = (cx - s * bw / 2.0, cy - s * bh / 2.0,
              cx + s * bw / 2.0, cy + s * bh / 2.0)
        if hole_side == 1:
            return (max(ib[0], band), ib[1], ib[2], ib[3])
        if hole_side == 2:
            return (ib[0], ib[1], min(ib[2], w - band), ib[3])
        if hole_side == 3:
            return (ib[0], ib[1], ib[2], min(ib[3], h - band))
        if hole_side == 4:
            return (ib[0], max(ib[1], band), ib[2], ib[3])
        return ib
    if shape == 'ROUND':
        c = float(corner or 0.0)
        m0 = box[0]
        sh = max(0.0, c - m0) * 0.5
        if sh <= 0.01:
            return box
        return (box[0] + sh, box[1] + sh, box[2] - sh, box[3] - sh)
    return box


def _label_layout(w, h, hole_side, hole_d, shape='RECT', corner=0.0,
                  margin_extra=0.0, hole_edge=2.0):
    """R73: hole + text box.

    The hole now sits CLOSE TO THE EDGE (2mm rim - key rings clip through
    easily; the old golden-ratio band parked it up to 11mm from the edge).
    The text box is the label inset on the THREE sides without the hole -
    the text centers between exactly those sides, away from the hole.
    Local label coords: x 0..w left->right, y 0..h, y=h = 'top' of the label.
    """
    # R80: proportional margins (~7% - user spec: 5-10% air to the border
    # AND to the hole), at least 1.5mm
    # R119: margin_extra = the raised BORDER zone (gap + walls + clearance)
    # - the text must never grow into it
    m = max(1.5, 0.07 * min(w, h), float(margin_extra or 0.0))
    # R120: hole_edge = rim between label edge and hole edge. Default 2mm;
    # with a raised border it moves INSIDE the border ring (the border must
    # never break for the hole - user spec)
    edge = max(2.0, float(hole_edge or 2.0))
    if hole_side in (1, 2) and hole_d > 0:      # left / right
        d = max(2.5, min(float(hole_d), h - 2 * edge - 2.0, 16.0))
        cx = edge + d / 2.0 if hole_side == 1 else w - edge - d / 2.0
        cy = h / 2.0
        band = edge + d + max(2.0, 0.07 * min(w, h))   # hole zone + clearance
        if hole_side == 1:
            box = (band, m, w - m, h - m)
        else:
            box = (m, m, w - band, h - m)
        box = _label_box_shape(box, w, h, shape, corner, hole_side, band)
        return (cx, cy, d / 2.0), box, d
    if hole_side in (3, 4) and hole_d > 0:      # top / bottom
        d = max(2.5, min(float(hole_d), w - 2 * edge - 2.0, 16.0))
        cy = h - edge - d / 2.0 if hole_side == 3 else edge + d / 2.0
        cx = w / 2.0
        band = edge + d + max(2.0, 0.07 * min(w, h))
        if hole_side == 3:
            box = (m, m, w - m, h - band)
        else:
            box = (m, band, w - m, h - m)
        box = _label_box_shape(box, w, h, shape, corner, hole_side, 0.0)
        return (cx, cy, d / 2.0), box, d
    box = _label_box_shape((m, m, w - m, h - m), w, h, shape, corner, 0, 0.0)
    return None, box, 0.0


def _label_metrics(lines, font, spacing=0.0):
    """R80: parse label lines once - glyph items, natural width (units),
    ascender overshoot, descender. Shared by the fit math (make_labels,
    auto-grow) and the path builder (_label_text_lines)."""
    g = _label_glyphs(font)
    if not lines:
        raise ValueError('empty label text')
    parsed = []
    for text in lines:
        items = []
        w_units = 0.0
        drawable = False
        for ch in text:
            v = g.get(ch) or g.get(ch.upper())
            if ch == ' ':
                items.append((ch, g[' '][0], None))
                w_units += g[' '][0]
                continue
            if not v or not v[1]:
                items.append((ch, 3.0, None))
                w_units += 3.0
                continue
            items.append((ch, v[0], v))
            w_units += v[0]
            drawable = True
        if not drawable:
            raise ValueError('label line "%s" has no drawable text '
                             '(only spaces/unknown signs)' % text[:16])
        asc_u = 0.0
        has_desc = False
        for ch, _adv, v in items:
            if v is None:
                continue
            if ch in 'gjpqy\u00df,;':
                has_desc = True
            ys = [p[1] for st in v[1] for p in st]
            top = min(ys)
            if top < g['cap_top']:
                asc_u = max(asc_u, g['cap_top'] - top)
        parsed.append({'text': text, 'items': items, 'w_units': w_units,
                       'asc_u': asc_u, 'desc_u': (g['desc_bot'] - g['baseline']) if has_desc else 0.0})
    return g, parsed


def _label_autocap(g, parsed, bw, bh, spacing=0.0, stroke_w=0.0, fill=0.94):
    """R80: the largest uniform cap height at which the WHOLE text block fits
    the usable box (all lines share ONE scale, ~94% fill - user spec: use the
    label, do not waste a quarter of the width like the old 75% rule)."""
    n = len(parsed)
    gap0 = max(1.0, 0.55 * stroke_w + 0.4)
    cu = g['cap_units']
    max_w = max(p['w_units'] for p in parsed)
    max_chars = max(len(p['text']) for p in parsed)
    band_units = sum(cu + p['asc_u'] + p['desc_u'] for p in parsed)
    cap_w = (bw * fill - spacing * (max_chars - 1)) * cu / max(max_w, 0.01)
    cap_h = (bh * fill - gap0 * (n - 1)) * cu / max(band_units, 0.01)
    return max(0.1, min(cap_w, cap_h))


def _label_need_size(g, parsed, cap, spacing=0.0, stroke_w=0.0, fill=0.94):
    """R80: usable (bw, bh) needed so the block prints at exactly `cap` mm
    caps - the inverse of _label_autocap, drives the label AUTO-GROW."""
    n = len(parsed)
    gap0 = max(1.0, 0.55 * stroke_w + 0.4)
    s = cap / g['cap_units']
    max_w = max(p['w_units'] for p in parsed)
    max_chars = max(len(p['text']) for p in parsed)
    bw = (max_w * s + spacing * (max_chars - 1)) / fill
    bh = (sum((g['cap_units'] + p['asc_u'] + p['desc_u']) * s for p in parsed)
          + gap0 * (n - 1)) / fill
    return bw, bh


def _label_grow_fit(all_lines, font, w, h, font_size, spacing, stroke_w,
                    hole_side, hole_d, floor_cap=2.8, shape='RECT',
                    corner=0.0, margin_extra=0.0, hole_edge=2.0):
    """R83: the AUTO-FIT + AUTO-GROW pass, shared by make_labels and
    label_preview (the LCD 'Fit' item shows the SAME numbers the generator
    will print). Caps raised for big signs: width up to 240mm, height to
    220mm (the bed fit check still rejects impossible plates)."""
    mcache = [_label_metrics(ls, font, spacing) for ls in all_lines]
    w_cap = min(w * 1.75 + 10.0, 240.0)
    h_cap = min(h * 1.75 + 8.0, 220.0)
    w0, h0 = w, h
    for _it79 in range(4):
        grew = False
        _c79, box79, _d79 = _label_layout(w, h, hole_side, hole_d,
                                           shape, corner,
                                           margin_extra, hole_edge)
        bw79 = box79[2] - box79[0]
        bh79 = box79[3] - box79[1]
        for g79, parsed79 in mcache:
            auto79 = _label_autocap(g79, parsed79, bw79, bh79, spacing, stroke_w)
            if font_size and float(font_size) > 0:
                want79 = float(font_size)
            elif auto79 >= floor_cap:
                continue
            else:
                want79 = floor_cap
            nbw79, nbh79 = _label_need_size(g79, parsed79, want79, spacing, stroke_w)
            if nbw79 > bw79 + 0.5 or nbh79 > bh79 + 0.5:
                wn79 = min(w + max(nbw79 - bw79, 0.0), w_cap)
                hn79 = min(h + max(nbh79 - bh79, 0.0), h_cap)
                if wn79 > w + 0.05 or hn79 > h + 0.05:
                    w, h = round(wn79, 1), round(hn79, 1)
                    grew = True
        if not grew:
            break
    grown79 = (w > w0 + 0.05) or (h > h0 + 0.05)
    return w, h, grown79, mcache


def _label_text_lines(lines, font, box, w, h, font_size=0.0, spacing=0.0,
                      min_gap=1.0, stroke_w=0.0):
    """R80 label typography v3 (user spec, field log .63):

    - up to 3 lines per label, ONE UNIFORM scale: letters never stretch
    - font_size > 0: TARGET cap height - make_labels GROWS the label so it
      fits (within limits); 0 = AUTO: as large as the label allows (94% fill)
    - NO more 'does not fit' errors: the label adapts, the text stays.
      Only a degenerate <1.6mm font (unreadable with any nozzle) still refuses.
    - lines stack centered (only FILLED lines count), gap keeps the stroke
      clear, block centered between the three sides without the hole
    Returns (paths [(x, y) mm label-local, y UP], metrics dict).
    """
    g, parsed = _label_metrics(lines, font, spacing)
    bw = box[2] - box[0]
    bh = box[3] - box[1]
    spacing = max(0.0, min(float(spacing or 0.0), 0.25 * bw))
    # ---- ONE uniform scale -----------------------------------------------------
    auto = _label_autocap(g, parsed, bw, bh, spacing, stroke_w)
    cap_mm = float(font_size) if (font_size and float(font_size) > 0) else auto
    # a target the (grown) label cannot hold falls back to auto - safety net,
    # make_labels normally grows the label so the target fits
    need_w, need_h = _label_need_size(g, parsed, cap_mm, spacing, stroke_w)
    if need_w > bw + 0.5 or need_h > bh + 0.5:
        cap_mm = min(cap_mm, auto)
    if cap_mm < 1.6:
        longest = max(parsed, key=lambda p: p['w_units'])
        raise ValueError('text "%s" is too long even for a grown label '
                         '(%.1fmm caps) - shorten it or allow a bigger label'
                         % (longest['text'][:16], cap_mm))
    s = cap_mm / g['cap_units']
    # ---- vertical layout: bands + gaps, block centered --------------------------
    bands = [(g['cap_units'] + p['asc_u'] + p['desc_u']) * s for p in parsed]
    n = len(parsed)
    gap0 = max(min_gap, 0.55 * stroke_w + 0.4)
    tot0 = sum(bands) + gap0 * (n - 1)
    free = bh - tot0
    gap = gap0 + (min(free * 0.5 / max(n - 1, 1), max(0.0, 1.0 * cap_mm - gap0)) if n > 1 else 0.0)
    tot = sum(bands) + gap * (n - 1)
    y_top = box[1] + (bh - tot) / 2.0 + tot      # top of the block (walk down)
    paths = []
    small_cap = 0.66 * cap_mm
    cur_top = y_top
    for p in parsed:
        asc_mm = p['asc_u'] * s
        desc_mm = p['desc_u'] * s
        baseline = cur_top - asc_mm - cap_mm
        line_w = p['w_units'] * s + spacing * (len(p['text']) - 1)
        x_cur = box[0] + (bw - line_w) / 2.0
        for ch, adv, v in p['items']:
            if v is None:
                x_cur += adv * s + spacing
                continue
            _a, sts = v
            ys = [p2[1] for st in sts for p2 in st]
            top = min(ys)
            sy_g = s
            if ch in '@<>\u00b0' and top < g['baseline']:
                extent = g['baseline'] - top
                if extent > 0.05:
                    sy_g = min(s, (small_cap / cap_mm) * s * g['cap_units'] / extent)
            for st in sts:
                pts = [(x_cur + px * s,
                        baseline + (g['baseline'] - py) * sy_g) for (px, py) in st]
                if len(pts) >= 2:
                    paths.append(pts)
            x_cur += adv * s + spacing
        cur_top -= (g['cap_units'] + p['asc_u'] + p['desc_u']) * s + gap
    return paths, {'cap_h': cap_mm, 's': s, 'lines': n,
                   'line_w': max(p['w_units'] * s + spacing * (len(p['text']) - 1)
                                 for p in parsed)}


def _decimate(pts, tol=0.10):
    """R73: drop micro segments + merge near-collinear vertices. The .56 label
    jobs froze the printer ('MCU overload') - dense stroke geometry at high
    feed rates is gone: fewer, longer moves at slower feeds instead."""
    if len(pts) < 3:
        return pts
    out = [pts[0]]
    for p in pts[1:]:
        if math.hypot(p[0] - out[-1][0], p[1] - out[-1][1]) >= tol:
            out.append(p)
    if len(out) > 2:
        res = [out[0]]
        for i in range(1, len(out) - 1):
            a, b, c = res[-1], out[i], out[i + 1]
            abx, aby = b[0] - a[0], b[1] - a[1]
            bcx, bcy = c[0] - b[0], c[1] - b[1]
            lab = math.hypot(abx, aby)
            lbc = math.hypot(bcx, bcy)
            if lab < 1e-9 or lbc < 1e-9:
                continue
            # distance of b from the straight line a->c
            acx, acy = c[0] - a[0], c[1] - a[1]
            lac = math.hypot(acx, acy)
            if lac < 1e-9:
                continue
            dist = abs(abx * acy - aby * acx) / lac
            if dist < tol:
                continue                        # collinear -> drop b
            res.append(b)
        res.append(out[-1])
        out = res
    return out


class _Pen:
    """tiny gcode writer with travel/retract/z-hop state (M83 relative E)"""

    def __init__(self, lines, retracts=True, jump_d=2.5):
        self.L = lines
        self.x = None
        self.y = None
        self.z = None
        self.ret = True
        self.retracts = retracts
        # R186: live ink-bounds tracking (min/max X/Y over extrudes) - the
        # figures round reads it to grow part cells to their TRUE ink
        # extent before the brim is placed (see make_figures)
        self._bx0 = self._by0 = 1e9
        self._bx1 = self._by1 = -1e9
        self._track = True
        # R95 (field log .74, rule dd): open holes [(cx, cy, r), ...] and
        # open slots [poly, ...] - a travel crossing one drags strings across
        # the opening no matter how SHORT it is, so crossings retract even
        # below jump_d
        self.holes = []
        self.hole_polys = []
        # R77: retract/hop only for jumps LONGER than jump_d. 2.5mm fired
        # between neighboring hatch lines (field log: retract storm = the
        # label base tore apart, the filament was 'pulled away'). Print
        # files use 6mm - only real feature jumps (label->label, ->tower)
        # retract, neighboring infill lines just travel flat.
        self.jump_d = float(jump_d)
        # R216 GOLDEN RULE (.136n field wish): no travel may ever CROSS
        # freshly printed plastic. A spatial hash of the CURRENT layer's
        # extrusion segments; a travel that intersects one transversally
        # (parallel neighbor lines never intersect - the deliberate
        # pressure-keeping connect moves stay flat) retracts + Z-hops,
        # no matter how short it is. Same class as the R95 hole rule,
        # now for ink instead of openings.
        self._ink_cell = 2.0        # mm grid
        self._ink_grid = {}
        self._ink_z = None

    def _ink_register(self, ax, ay, bx, by):
        cs = self._ink_cell
        for cx in range(int(min(ax, bx) // cs), int(max(ax, bx) // cs) + 1):
            for cy in range(int(min(ay, by) // cs), int(max(ay, by) // cs) + 1):
                self._ink_grid.setdefault((cx, cy), []).append(
                    (ax, ay, bx, by))

    def _ink_crossing(self, x, y):
        """does the travel (pen -> x,y) CROSS this layer's ink?"""
        if self.x is None or not self._ink_grid or self.z is None:
            return False
        cs = self._ink_cell
        tvx, tvy = x - self.x, y - self.y
        tl = math.hypot(tvx, tvy)
        if tl < 0.25:
            return False
        tvx, tvy = tvx / tl, tvy / tl
        step = cs * 0.5
        seen = set()
        p = (self.x, self.y)
        q = (x, y)
        i = 0
        while i * step <= tl:
            px = self.x + tvx * step * i
            py = self.y + tvy * step * i
            for cx in range(int((px - cs) // cs), int((px + cs) // cs) + 1):
                for cy in range(int((py - cs) // cs), int((py + cs) // cs) + 1):
                    if (cx, cy) in seen:
                        continue
                    seen.add((cx, cy))
                    for (ax, ay, bx, by) in self._ink_grid.get((cx, cy), ()):
                        if _segs_cross(p, q, (ax, ay), (bx, by)):
                            return True
            i += 1
        return False

    def breset(self):
        self._bx0 = self._by0 = 1e9
        self._bx1 = self._by1 = -1e9

    def bget(self):
        """R186: (x0, y0, x1, y1) ink extent since the last breset, or
        None when nothing extruded."""
        if self._bx0 > self._bx1 or self._by0 > self._by1:
            return None
        return (self._bx0, self._by0, self._bx1, self._by1)

    def set_z(self, z, feed=1200):
        self.L.append('G0 Z%.3f F%d' % (z, feed))
        if self._ink_z is None or abs(z - self._ink_z) > 0.02:
            self._ink_grid = {}          # R216: new layer, new ink
            self._ink_z = z
        self.z = z

    def _hole_cross(self, x, y):
        # R95: does the travel (pen -> x,y) cross an OPEN hole or slot?
        if self.x is None:
            return False
        p, q = (self.x, self.y), (x, y)
        if self.holes and any(_seg_hits_circle(p, q, cx, cy, r)
                              for (cx, cy, r) in self.holes):
            return True
        if self.hole_polys and any(_seg_hits_poly(p, q, poly)
                                   for poly in self.hole_polys):
            return True
        return False

    def travel(self, x, y, feed=4500, hop=True, force_d=None):
        # R73: travel capped at 75mm/s (the .56 label jobs overloaded the MCU
        # with 150mm/s travels) and Z-hops only above 2.5mm
        # R83: force_d lowers the retract threshold for THIS move (text
        # bundles retract from 1.2mm gaps - field log .65: no-retract travels
        # between letters drew ghost lines and the letters grew together)
        # R95: hole crossings retract at ANY length (rule dd)
        if self.x is None:
            self.L.append('G0 X%.3f Y%.3f F%d' % (x, y, feed))
        else:
            d = math.hypot(x - self.x, y - self.y)
            # R96: the hole check only counts REAL moves - a zero-length hop
            # (layer seam straight into the band start) crosses nothing.
            # R216 GOLDEN RULE: an INK crossing (travel across freshly
            # printed plastic) retracts + hops at ANY length - the field
            # log showed threads straight across labels and band tops.
            _hit216 = (d > 0.02 and (self._hole_cross(x, y)
                                     or self._ink_crossing(x, y)))
            if (_hit216
                    or d > (self.jump_d if force_d is None else force_d)):
                # hop even on the first layers when we cross ink - flat
                # first-layer crossings dragged the worst strings
                hopz = (hop and self.z is not None
                        and (self.z > 0.35 or _hit216))
                if self.retracts:
                    self.L.append('G10')
                if hopz:
                    self.L.append('G0 Z%.3f F1200' % (self.z + 0.4))
                self.L.append('G0 X%.3f Y%.3f F%d' % (x, y, feed))
                if hopz:
                    self.L.append('G0 Z%.3f F1200' % self.z)
                if self.retracts:
                    self.L.append('G11')
                self.ret = False
            elif d > 0.02:
                self.L.append('G0 X%.3f Y%.3f F%d' % (x, y, feed))
        self.x, self.y = x, y

    def extrude(self, x, y, e, feed):
        if e <= 0:
            return
        self.L.append('G1 X%.3f Y%.3f E%.5f F%d' % (x, y, e, feed))
        if (self._ink_z is not None and self.x is not None
                and self.y is not None
                and abs((self.z or 0) - self._ink_z) <= 0.02):
            self._ink_register(self.x, self.y, x, y)   # R216 golden rule
        if self._track:
            if x < self._bx0:
                self._bx0 = x
            if y < self._by0:
                self._by0 = y
            if x > self._bx1:
                self._bx1 = x
            if y > self._by1:
                self._by1 = y
        self.x, self.y = x, y

    def push(self, e, feed):
        self.L.append('G1 E%.3f F%d' % (e, feed))


def _circle(cx, cy, r, seg=28):
    pts = []
    for i in range(seg):
        a = 2.0 * math.pi * i / seg
        pts.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return pts


def _rect_loop(x0, y0, x1, y1):
    return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]


def _brim_gap(wid):
    """R184 (.131c field round): the BRIM AIR GAP rule, one place for every
    generator. A brim is a REMOVAL part - it must grip the bed but never
    weld to the object. The old loops started at wid*0.35 from the object
    contour; the wall ink reaches right to (or past) that line, so frames,
    cable ties, litho FLAT plates, label rings, purge towers, stamp handles
    and resonance plates all printed their brims FUSED to the part (the
    user had to fight them off even at 92% flow). Every brim's innermost
    loop now runs wid + 0.35mm outside the reference contour: a real air
    gap of ~0.35mm between the wall ink and the brim ink. It grips the
    BED, not the part. The RANGE brim stays welded ON PURPOSE - it must
    anchor small cut sections against warping (documented there)."""
    return wid + 0.35


def _layout_gap(brim, wid):
    """R186: cell-to-cell gap on a multi-part plate. Without a brim the
    classic BRICK_GAP stands. With a brim the OUTERMOST loop reaches
    _brim_gap(wid) + (brim-1)*wid + wid/2 of ink past the cell box - the
    gap must reserve that reach plus the 0.35mm R184 air gap to the
    NEIGHBOR's ink (brim ink touching brim ink is fine, both loops are
    sacrificial). At nozzle 1.0 with brim=2 that is 3.45mm > BRICK_GAP -
    the old fixed gap let the head's round brim weld onto the neighbor
    arm's grip."""
    if not brim:
        return BRICK_GAP
    # +0.40 (not +0.35): a round brim's 28-segment polygon chords sag up to
    # ~0.05mm inside the ideal circle - the reserve must still guarantee
    # the full 0.35mm air gap to the neighbor's ink
    return max(BRICK_GAP, _brim_gap(wid) + (brim - 1) * wid + wid / 2.0 + 0.40)


def _emit_loop(pen, pts, e_per_mm, feed, close=True):
    # R74: start the loop at the vertex CLOSEST to the pen - the fixed start
    # added a travel across the feature after every previous feature
    if close and pen.x is not None and len(pts) > 2:
        k = min(range(len(pts)),
                key=lambda i: (pts[i][0] - pen.x) ** 2 + (pts[i][1] - pen.y) ** 2)
        if k:
            pts = pts[k:] + pts[:k]
    # R133 (field log .93, 'Timer too close'): merge vertices closer than
    # 0.1mm - tiny circle chords on scaled-down parts produced 3000+
    # moves/s bursts. Rect loops never hit this (axis-aligned, >= line
    # width), so default outputs stay byte-identical.
    if len(pts) > 2:
        mg = [pts[0]]
        for (x, y) in pts[1:]:
            if math.hypot(x - mg[-1][0], y - mg[-1][1]) >= 0.1:
                mg.append((x, y))
        if len(mg) > 2 or not close:
            pts = mg
    pen.travel(pts[0][0], pts[0][1])
    px, py = pts[0]
    for (x, y) in pts[1:]:
        pen.extrude(x, y, math.hypot(x - px, y - py) * e_per_mm, feed)
        px, py = x, y
    if close:
        pen.extrude(pts[0][0], pts[0][1], math.hypot(pts[0][0] - px, pts[0][1] - py) * e_per_mm, feed)


def _segs_clear_of(segs, keepouts):
    """R231: split hatch segments into runs that keep their clearance from
    every keep-out polyline - the label's inlaid top layer prints AROUND
    the text bands and the border ring, the color-B fills own those
    regions. keepouts = [(pts, clear_mm), ...]; sampling every 0.6mm (a
    visual boundary, not exact geometry - the B fills overlap any sliver).
    Returns a segment list like the input."""
    if not keepouts:
        return list(segs)
    bbs = []
    for pts, clear in keepouts:
        if len(pts) < 2:
            continue
        for a, b in zip(pts[:-1], pts[1:]):
            bbs.append((min(a[0], b[0]) - clear, min(a[1], b[1]) - clear,
                        max(a[0], b[0]) + clear, max(a[1], b[1]) + clear,
                        a, b, clear))
    if not bbs:
        return list(segs)
    out = []
    for (p, q) in segs:
        dx, dy = q[0] - p[0], q[1] - p[1]
        d = math.hypot(dx, dy)
        if d < 0.05:
            continue
        n = max(2, int(d / 0.6) + 1)
        run_start = None
        prev_pt = None
        for i in range(n):
            t = i / (n - 1.0)
            x, y = p[0] + dx * t, p[1] + dy * t
            ok = True
            for (bx0, by0, bx1, by1, a, b, clear) in bbs:
                if bx0 <= x <= bx1 and by0 <= y <= by1:
                    ex, ey = b[0] - a[0], b[1] - a[1]
                    dd = ex * ex + ey * ey
                    if dd < 1e-9:
                        if math.hypot(x - a[0], y - a[1]) < clear:
                            ok = False
                            break
                    else:
                        tt = max(0.0, min(1.0, ((x - a[0]) * ex
                                                + (y - a[1]) * ey) / dd))
                        if math.hypot(x - (a[0] + ex * tt),
                                      y - (a[1] + ey * tt)) < clear:
                            ok = False
                            break
                if not ok:
                    break
            if ok:
                if run_start is None:
                    run_start = (x, y)
                prev_pt = (x, y)
            elif run_start is not None and prev_pt is not None:
                if math.hypot(prev_pt[0] - run_start[0],
                              prev_pt[1] - run_start[1]) >= 0.3:
                    out.append((run_start, prev_pt))
                run_start = None
        if run_start is not None and prev_pt is not None:
            out.append((run_start, prev_pt))
    return out


def _hatch(x0, y0, x1, y1, circ_keep, spacing, angle_deg, min_len=0.35):
    """scanline hatch over rect minus keep-out circle -> [(p,q),..] boustrophedon

    R77 FIX (field log .60: label bases tore apart, 'filament pulled away'):
    the scanlines used to be emitted CENTER-OUT in +-alternating order
    (i=0 center, then -1/+1, -2/+2 ...) - consecutive segments sat up to
    2*i*spacing apart, so the pen travelled across the whole label between
    NEIGHBORING infill lines (with a G10 retract each, once the distance
    passed the jump threshold - a retract storm that starved the nozzle).
    Now the lines are sorted into a real SWEEP from one side to the other:
    neighbors are adjacent by construction, no retracts inside the fill."""
    ang = math.radians(angle_deg)
    dx, dy = math.cos(ang), math.sin(ang)
    nx, ny = -dy, dx
    mx, my = (x0 + x1) / 2.0, (y0 + y1) / 2.0
    corners = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
    tmax = max(abs((px - mx) * nx + (py - my) * ny) for px, py in corners) + spacing
    scan = []                                  # [(offset t, intervals), ...]
    i = 0
    while i * spacing <= tmax:
        for t in ((i * spacing,) if i == 0 else (-i * spacing, i * spacing)):
            ox, oy = mx + nx * t, my + ny * t
            s0, s1 = -1e9, 1e9
            ok = True
            for axis in (0, 1):
                d = (dx, dy)[axis]
                o = (ox, oy)[axis]
                lo, hi = (x0, x1) if axis == 0 else (y0, y1)
                if abs(d) < 1e-12:
                    if o < lo - 0.01 or o > hi + 0.01:
                        ok = False
                        break
                else:
                    a = (lo - o) / d
                    b = (hi - o) / d
                    if a > b:
                        a, b = b, a
                    s0 = max(s0, a)
                    s1 = min(s1, b)
            if not ok or s1 - s0 < min_len:
                continue
            intervals = [(s0, s1)]
            if circ_keep:
                ckx, cky, ck = circ_keep
                fx, fy = ox - ckx, oy - cky
                qb = 2.0 * (fx * dx + fy * dy)
                qc = fx * fx + fy * fy - ck * ck
                disc = qb * qb / 4.0 - qc
                if disc >= 0.0:
                    sq = math.sqrt(disc)
                    ta = -qb / 2.0 - sq
                    tb = -qb / 2.0 + sq
                    new = []
                    for (a, b) in intervals:
                        if tb <= a or ta >= b:
                            new.append((a, b))
                        else:
                            if a < ta:
                                new.append((a, min(b, ta)))
                            if b > tb:
                                new.append((max(a, tb), b))
                    intervals = new
            if intervals:
                scan.append((t, intervals))
        i += 1
    scan.sort(key=lambda ti: ti[0])            # R77: sweep, not center-out zigzag
    segs = []
    idx = 0
    for _t, intervals in scan:
        for (a, b) in intervals:
            if b - a < min_len:
                continue
            ox, oy = mx + nx * _t, my + ny * _t
            p = (ox + dx * (a + 0.15), oy + dy * (a + 0.15))
            q = (ox + dx * (b - 0.15), oy + dy * (b - 0.15))
            segs.append((p, q) if idx % 2 == 0 else (q, p))
            idx += 1
    return segs


def _emit_hatch(pen, segs, e_per_mm, feed):
    # R74: start from the END that is closer to the pen. R77 FIX (field log
    # .60: label bases tore apart, 'filament pulled away'): reversing only the
    # LIST breaks the boustrophedon chain - the segments alternate direction,
    # so end(seg[k]) is near start(seg[k+1]) but FAR from start(seg[k-1]).
    # The broken chain made EVERY hatch line a full-width travel with a
    # G10 retract before it (a retract storm that starved the nozzle).
    # Reversing each segment's direction TOO keeps the chain intact:
    # ... end(s2)->start(s1'), end(s1')->start(s0') ...
    if segs and pen.x is not None:
        d0 = (segs[0][0][0] - pen.x) ** 2 + (segs[0][0][1] - pen.y) ** 2
        d1 = (segs[-1][0][0] - pen.x) ** 2 + (segs[-1][0][1] - pen.y) ** 2
        if d1 < d0:
            segs = [(q, p) for (p, q) in reversed(segs)]
    for (p, q) in segs:
        pen.travel(p[0], p[1], hop=False)
        pen.extrude(q[0], q[1], math.hypot(q[0] - p[0], q[1] - p[1]) * e_per_mm, feed)


def _poly_offset(pts, off):
    """R97: offset a simple polygon OUTWARD by off (miter at the vertices) -
    brim rings around frame contours (rounded rects, ovals, triangles)."""
    n = len(pts)
    area = 0.0
    for i in range(n):
        x0, y0 = pts[i]
        x1, y1 = pts[(i + 1) % n]
        area += x0 * y1 - x1 * y0
    sgn = 1.0 if area >= 0.0 else -1.0          # CCW -> outward normal
    out = []
    for i in range(n):
        ax, ay = pts[i - 1]
        bx, by = pts[i]
        cx, cy = pts[(i + 1) % n]
        dx1, dy1 = bx - ax, by - ay
        dx2, dy2 = cx - bx, cy - by
        l1 = math.hypot(dx1, dy1) or 1.0
        l2 = math.hypot(dx2, dy2) or 1.0
        nx = (dy1 / l1 + dy2 / l2) * sgn
        ny = -(dx1 / l1 + dx2 / l2) * sgn
        nl = math.hypot(nx, ny) or 1.0
        out.append((bx + nx / nl * off, by + ny / nl * off))
    return out


def _emit_serp(pen, segs, e_per_mm, feed, max_conn=3.0):
    """R97: first-layer fill as ONE CONTINUOUS zigzag (field log .74: the
    singly printed hatch lines curled up at their starts and ends - filament
    lifted off the bed, the first layer frayed at the borders and grew
    holes). Adjacent hatch lines connect with an EXTRUDED move along the
    border; only crossings of open holes (registered keep-outs, rule dd) or
    long gaps stay travels - and those retract."""
    if segs and pen.x is not None:
        d0 = (segs[0][0][0] - pen.x) ** 2 + (segs[0][0][1] - pen.y) ** 2
        d1 = (segs[-1][0][0] - pen.x) ** 2 + (segs[-1][0][1] - pen.y) ** 2
        if d1 < d0:
            segs = [(q, p) for (p, q) in reversed(segs)]
    for (p, q) in segs:
        # R117.1: sliver segments (<0.15mm, a hatch line clipped to a
        # polygon corner) print as 400+/s micro-moves at fill speed and
        # deposit less than a quarter of a bead width - skip them
        if math.hypot(q[0] - p[0], q[1] - p[1]) < 0.15:
            continue
        if pen.x is None:
            pen.travel(p[0], p[1], hop=False)
        else:
            d = math.hypot(p[0] - pen.x, p[1] - pen.y)
            # R117.1: degenerate links (<0.15mm, line ends nearly touch)
            # print as a plain hop - a 0.1mm bead at fill speed is a
            # 400+/s micro-move (MCU flood guard), the hop is invisible
            if 0.15 <= d <= max_conn and not pen._hole_cross(p[0], p[1]):
                pen.extrude(p[0], p[1], d * e_per_mm, feed)   # connector bead
            else:
                pen.travel(p[0], p[1], hop=False)
        pen.extrude(q[0], q[1], math.hypot(q[0] - p[0], q[1] - p[1]) * e_per_mm, feed)


def _emit_fill(pen, segs, e_per_mm, feed, spacing):
    """R117 (.88 field log): surface/solid/infill fills print as ONE
    CONTINUOUS zigzag (the R97 first-layer tech, now for EVERY fill): single
    scanlines frayed at their ends, did not fuse with the walls and printed
    stop-and-go. Adjacent lines link with an EXTRUDED connector along the
    border (fuses with the wall); hole crossings and long gaps stay travels.
    max_conn = spacing*2.5 capped at 5mm: solid fills chain completely,
    sparse fills only link where the connector is short."""
    _emit_serp(pen, segs, e_per_mm, feed, min(5.0, spacing * 2.5))


def _serp_g(g, segs, e_per_mm, feed, spacing):
    """R117: the _GenE (make_range) twin of _emit_fill - connects the hatch
    lines with extruded links; long gaps and hole crossings keep the
    builder's retracting travel."""
    if segs and g.px is not None:
        d0 = (segs[0][0][0] - g.px) ** 2 + (segs[0][0][1] - g.py) ** 2
        d1 = (segs[-1][0][0] - g.px) ** 2 + (segs[-1][0][1] - g.py) ** 2
        if d1 < d0:
            segs = [(q, p) for (p, q) in reversed(segs)]
    for (p, q) in segs:
        # R117.1: sliver segments - see _emit_serp
        if math.hypot(q[0] - p[0], q[1] - p[1]) < 0.15:
            continue
        if g.px is None:
            g.move(p[0], p[1], 4800)
        else:
            d = math.hypot(p[0] - g.px, p[1] - g.py)
            _ok117 = not (g.hole is not None and
                          _seg_hits_circle((g.px, g.py), p,
                                           g.hole[0], g.hole[1], g.hole[2]))
            if 0.15 <= d <= min(5.0, spacing * 2.5) and _ok117:
                g.line(g.px, g.py, p[0], p[1], e_per_mm, feed)
            else:
                g.move(p[0], p[1], 4800)
        g.line(p[0], p[1], q[0], q[1], e_per_mm, feed)


def _bed_limits(cfg_path):
    """R92/R104.2: the REAL printable bed, not the stepper range.

    This machine's position_max values are deliberately lifted (micro probe +
    bed mesh rides beyond the plate), so they must NEVER size generator
    placements. Source chain:
      1. [gcode_macro _R2_CONFIG] in printer.cfg (KAMP-style settings macro -
         the ONLY valid way to ship custom values: Klipper REFUSES unknown
         sections with 'not a valid config section' - the raw [r2_postproc]
         section of R92..R81 halted the printer on the first real use,
         field log .81): variable_bed_min_x / variable_bed_max_x /
         variable_bed_min_y / variable_bed_max_y
         (also read by the LCD macros - ONE truth)
      2. Ender-3 default: x 0..220, y -3..217 (confirmed by the user, R92)
    A one-line hint is printed when the macro is missing, and a LOUD warning
    when a legacy [r2_postproc] section is present (it halts Klipper!).
    """
    dflt = (0.0, -3.0, 220.0, 217.0)
    secs = {}

    def _parse(path):
        try:
            with open(path, errors='replace') as f:
                cur = None
                for l in f:
                    ls = l.strip()
                    if ls.startswith('[') and ls.endswith(']'):
                        cur = ls[1:-1].strip().lower()
                        secs.setdefault(cur, {})
                    elif cur and ':' in ls and not ls.startswith(('#', ';')):
                        k, v = ls.split(':', 1)
                        v = v.split('#')[0].split(';')[0].strip()
                        if k.strip() and v:
                            secs[cur][k.strip().lower()] = v
        except OSError:
            pass

    _parse(cfg_path)
    # R108: the dedicated hardware profile (same folder) is the NEW home of
    # [gcode_macro _R2_CONFIG] - its values WIN over a legacy block inside
    # printer.cfg (which is only commented out there anyway after migration)
    import os as _os
    _hw = _os.path.join(_os.path.dirname(_os.path.abspath(cfg_path)),
                        'r2_hardware.cfg')
    if _os.path.abspath(cfg_path) != _os.path.abspath(_hw):
        _parse(_hw)

    if 'r2_postproc' in secs:
        print('[bed] [!] [r2_postproc] in printer.cfg HALTS KLIPPER (unknown '
              'config section) - remove it / let setup.sh migrate it to '
              '[gcode_macro _R2_CONFIG] (values still read here as a '
              'courtesy)', flush=True)
    r2 = secs.get('gcode_macro _r2_config', {})
    if r2:
        keys = ('variable_bed_min_x', 'variable_bed_max_x',
                'variable_bed_min_y', 'variable_bed_max_y')
    else:
        r2 = secs.get('r2_postproc', {})
        keys = ('bed_min_x', 'bed_max_x', 'bed_min_y', 'bed_max_y')
    if r2 and all(k in r2 for k in keys):
        try:
            x0, x1 = float(r2[keys[0]]), float(r2[keys[1]])
            y0, y1 = float(r2[keys[2]]), float(r2[keys[3]])
        except (TypeError, ValueError):
            x0 = x1 = y0 = y1 = 0.0
        if x1 > x0 and y1 > y0:
            return (x0, y0, x1, y1)
        print('[bed] _R2_CONFIG bed values are not sane - using the '
              'Ender-3 default 220x220', flush=True)
    else:
        print('[bed] no [gcode_macro _R2_CONFIG] in printer.cfg - using the '
              'Ender-3 default 220x220 (add variable_bed_min_x/... to '
              'configure)', flush=True)
    return dflt



_NOZZLE_CACHE = {}


def _nozzle_diameter(cfg_path):
    """R90.1c(field): the REAL nozzle diameter from printer.cfg [extruder]
    (nozzle_diameter:) - ONE truth for every generator (line widths, E per mm,
    hatch spacing all derive from it). Fallback 0.6 (the machine default).
    Returns (diameter, from_cfg)."""
    try:
        _ck = (cfg_path, os.path.getmtime(cfg_path))
    except OSError:
        _ck = (cfg_path, -1)
    if _ck in _NOZZLE_CACHE:
        return _NOZZLE_CACHE[_ck]
    val, ok = 0.6, False
    try:
        with open(cfg_path, errors='replace') as f:
            cur = None
            for l in f:
                ls = l.strip()
                if ls.startswith('[') and ls.endswith(']'):
                    cur = ls[1:-1].strip().lower()
                elif cur == 'extruder' and ':' in ls and not ls.startswith(('#', ';')):
                    k, v = ls.split(':', 1)
                    if k.strip().lower() == 'nozzle_diameter':
                        try:
                            val = max(0.1, min(float(v.split('#')[0].split(';')[0]), 2.0))
                            ok = True
                        except ValueError:
                            pass
                        break
    except OSError:
        pass
    _NOZZLE_CACHE[_ck] = (val, ok)
    return val, ok


def _gen_nozzle(directory):
    """R90.1c(field): nozzle diameter for the watcher's generator calls -
    reads printer.cfg [extruder] nozzle_diameter next to the gcodes folder.
    One console line when it deviates from the 0.6 machine default (line
    widths / E-per-mm / hatch spacing all derive from it)."""
    val, ok = _nozzle_diameter(os.path.join(
        os.path.dirname(os.path.abspath(directory).rstrip('/')),
        'config', 'printer.cfg'))
    if ok and abs(val - 0.6) > 0.01:
        print(f'[gen] nozzle {val}mm from printer.cfg - line widths adapt',
              flush=True)
    return val

def _safe_label_name(t):
    return (re.sub(r'[^A-Za-z0-9_.-]+', '', t)[:16] or 'label')


def label_preview(texts, w=60.0, h=30.0, font='SMOOTH', base_layers=4,
                   text_layers=2, layer_h=0.2, first_h=0.28, hole_side=0,
                   hole_d=5.0, gap=12.0, color2=True, stroke=0.0, font_size=0.0,
                   spacing=0.0, bed=None, bed_margin=6.0, nozzle=0.6,
                   mode='grow', shape='RECT', corner=0.0, border_walls=0,
                   border_gap=0.0, walls=0):
    """R83: project the label outcome WITHOUT writing a file. The LCD 'Fit'
    item bumps label_fit_nonce and this answers with the same numbers the
    generator will print: final label size (incl. growth), cap height,
    effective stroke, characters per line, the minimum label size a fixed
    font size needs, and whether the purge tower still fits the bed.
    R99 (field log .75): mode='fixed' = the label stays W/H and the FONT
    scales (the LCD W/H limits unlock); 'grow' = the label grows until the
    text fits (W/H are minimums)."""
    font = str(font or 'SMOOTH').upper()
    if font == 'PIXEL':
        font = 'SMOOTH'
    all_lines = []
    for t in texts:
        ls = [x.strip() for x in t.split('~') if x.strip()]
        # R286 (Befund: kyrillische / nicht-unterstuetzte Zeichen im Label):
        # Zeichen ausserhalb LABEL_CHARSET werden SICHER zu '?' ersetzt, damit
        # sie nicht ungestuerd in die Render-Geometrie gelangen (ein kyrill-
        #isches 'T' U+0422 sah wie ein lateinisches 'T' aus und landete im
        # G-Code). Konsistent mit der Datei-Lese-Sanitisierung (L9286).
        _lc_allowed = set(LABEL_CHARSET)
        ls = [''.join(ch if ch in _lc_allowed else '?' for ch in x) for x in ls]
        if not ls:
            raise ValueError('label "%s" has no text' % t[:16])
        if len(ls) > 5:
            raise ValueError('label "%s" has %d lines - at most 5 per label'
                             % (t[:16], len(ls)))
        all_lines.append(ls)
    w = float(w)
    h = float(h)
    spacing = max(0.0, min(float(spacing or 0.0), 10.0))
    twid = max(0.4, nozzle * 1.02)
    # R224 (.136v): the SAME wall knob the generator uses - the preview
    # used to project the retired mm-stroke default, so the LCD 'Fit'
    # numbers never reflected 'Text: N walls' (preview != print)
    try:
        _walls224p = max(0, min(int(walls or 0), 4))
    except (TypeError, ValueError):
        _walls224p = 0
    stroke_w = float(stroke or 0.0)
    if _walls224p > 0:
        stroke_w = _walls224p * twid
    if stroke_w <= 0:
        stroke_w = 3.0 * twid
    stroke_w = max(twid, min(stroke_w, 4.0))
    if bed is None:
        bed = (0.0, -3.0, 244.0, 238.0)
    bx0, by0, bx1, by1 = bed
    ux0, uy0 = bx0 + bed_margin, by0 + bed_margin
    ux1, uy1 = bx1 - bed_margin, by1 - bed_margin
    uw, uh = ux1 - ux0, uy1 - uy0

    fixed99 = str(mode).strip().lower() in ('fixed', 'fix', '1')
    if fixed99:
        w2, h2, grown = w, h, False
        mcache = [_label_metrics(ls, font, spacing) for ls in all_lines]
    else:
        # R119: the SAME shape/border margins the generator uses - the Fit
        # numbers must match what prints
        _wid119 = max(0.4, nozzle * 1.08)
        _bm119 = ((border_gap + border_walls * _wid119 + 1.2)
                  if border_walls > 0 else 0.0)
        w2, h2, grown, mcache = _label_grow_fit(
            all_lines, font, w, h, font_size, spacing, stroke_w, hole_side,
            hole_d, shape=shape, corner=corner, margin_extra=_bm119)
    _c, box, _d = _label_layout(w2, h2, hole_side, hole_d, shape, corner,
                                (border_gap + border_walls
                                 * max(0.4, nozzle * 1.08) + 1.2)
                                if border_walls > 0 else 0.0)
    bw, bh = box[2] - box[0], box[3] - box[1]
    g, parsed = mcache[0]
    cap_auto = _label_autocap(g, parsed, bw, bh, spacing, stroke_w)
    cap = min(float(font_size), cap_auto) if font_size and float(font_size) > 0 else cap_auto
    cap = max(0.1, cap)
    stroke_eff = round(min(stroke_w, max(twid, 0.34 * cap)), 2)   # R224: 0.34 (was cap/5)

    # characters per line at the projected cap (font-average advance)
    longest = max(parsed, key=lambda p2: p2['w_units'])
    avg_adv = max(0.01, longest['w_units'] / max(1, len(longest['text'])))
    sc = cap / g['cap_units']
    per_char = avg_adv * sc + spacing
    chars_fit = max(1, int((bw * 0.94 + spacing) / max(per_char, 0.01)))

    # minimum label size for a FIXED font size (width first, then height -
    # the same strategy the generator grows). R99: only in grow mode - in
    # fixed mode the font scales into the label, there is no minimum
    min_w = min_h = None
    if font_size and float(font_size) > 0 and not fixed99:
        nbw, nbh = _label_need_size(g, parsed, float(font_size), spacing, stroke_w)
        min_w, min_h = w2, h2
        for cand in [c * 0.5 for c in range(24, 481)]:        # 12..240mm
            _c2, b2, _d2 = _label_layout(cand, h, hole_side, hole_d)
            if b2[2] - b2[0] >= nbw - 0.5:
                min_w = cand
                break
        _c3, b3, _d3 = _label_layout(min_w, h, hole_side, hole_d)
        if b3[3] - b3[1] < nbh - 0.5:
            for cand in [c * 0.5 for c in range(int(h * 2), 441)]:   # h..220mm
                _c4, b4, _d4 = _label_layout(min_w, cand, hole_side, hole_d)
                if b4[3] - b4[1] >= nbh - 0.5:
                    min_h = cand
                    break

    # grid + tower fit on the bed (same math as make_labels)
    n = len(texts)
    cols = rows = None
    for c in range(n, 0, -1):
        r = -(-n // c)
        if c * w2 + (c - 1) * gap <= uw and r * h2 + (r - 1) * gap <= uh:
            cols, rows = c, r
            break
    tower_fits = False
    if cols is not None:
        gw = cols * w2 + (cols - 1) * gap
        gh = rows * h2 + (rows - 1) * gap
        gx0 = ux0 + (uw - gw) / 2.0
        gy0 = uy0 + (uh - gh) / 2.0
        if color2:
            tg, tw = 15.0, 12.0
            for (tx, ty) in [(gx0 + gw + tg, gy0), (gx0, gy0 + gh + tg),
                             (gx0, gy0 - tw - tg), (gx0 - tw - tg, gy0)]:
                if tx >= ux0 and ty >= uy0 and tx + tw <= ux1 and ty + tw <= uy1:
                    tower_fits = True
                    break
    warns = []
    if stroke_eff < stroke_w - 0.01:
        warns.append('stroke %.2fmm capped to %.2fmm (0.34*cap - thicker '
                     'would merge the letters)' % (stroke_w, stroke_eff))
    if color2 and cols is not None and not tower_fits:
        warns.append('no room for the purge tower at 15mm clearance - the '
                     'filament change purges at the park position instead')
    if cols is None:
        warns.append('the plate does not fit the bed at %.0fx%.0fmm - smaller '
                     'labels or a smaller gap' % (w2, h2))
    return {'w': round(w2, 1), 'h': round(h2, 1), 'grown': grown,
            'cap_mm': round(cap, 1), 'cap_capped': (font_size and float(font_size) > 0
                                                    and cap < float(font_size) - 0.05),
            'target_mm': round(float(font_size or 0), 1),
            'stroke_eff': stroke_eff, 'walls': (_walls224p or 3),
            'chars_fit': chars_fit,
            'lines': max(len(ls) for ls in all_lines), 'count': n,
            'min_w': round(min_w, 1) if min_w else None,
            'min_h': round(min_h, 1) if min_h else None,
            'tower_fits': tower_fits, 'fits_bed': cols is not None,
            'warns': warns}


class _StampFit168:
    """R168: stamp mount geometry - ONE truth for the base socket and the
    handle spigot (litho FLAT + labels share it).

    Mount = SNAP, not a thread (user allowed an alternative; the field
    rules decided): a 3D-printed thread at ~9mm needs near-perfect fit on
    an unknown printer, while a hollow-tipped spigot with a groove that
    snaps past a lip ring in the socket holds firmly, needs no rotation,
    and every surface is vertical or 45 deg (house air rule). The socket
    ceiling is a DECLARED BRIDGE (R95 bridge-first spokes), the only
    exception the aircheck honors anyway.

    Seating: the spigot tip rests on the socket ceiling, the lip sits in
    the groove. All radii below are SURFACE radii - the emitted loops run
    at surface +/- wid/2 (material side) so the printed surface hits the
    math. The fit report (fit[]) goes into BOTH files as
    '; R168-STAMP FIT:' comments so tools/r168_stampcheck.py can re-measure
    the printed geometry from the g-code and verify the promise.
    """

    R_P = 4.5          # spigot radius (fixed - the knob scales, this not)
    SNAP = 0.20        # lip interference vs the spigot cylinder (mm/side)
    LIP_BAND = 0.8     # axial width of the lip ring (mm)
    GROOVE_M = 0.10    # axial margin of the groove around the lip (mm/side)
    BORE = 2.90        # hollow spigot bore radius (compliant snap zone)
    GRIP_R = 9.0       # knob radius
    GRIP_H = 21.0      # knob cylinder height (above the cone)

    def __init__(self, tol=0.25, layer_h=0.12):
        self.tol = max(0.10, min(float(tol or 0.25), 0.50))
        self.lh = max(0.08, min(float(layer_h or 0.12), 0.2))
        R, s = self.R_P, self.SNAP
        self.r_e = R + self.tol            # socket entry
        self.r_lip = R - s                 # lip (narrowest socket point)
        self.r_gr = R - 0.55               # groove floor (spigot)
        self.r_ch = R + self.tol + 0.05    # chamber above the lip
        # R168b (found by the stampcheck seating sweep): the ceiling is
        # FLAT at the chamber radius - a 45deg ceiling chamfer caught the
        # spigot tip BEFORE the lip reached the groove (the handle would
        # have sat cocked on the chamfer edge). The flat ceiling is a
        # declared bridge (R168 lines), the tip lands clean on it.
        self.r_ce = self.r_ch
        # socket depths (45 deg ramps: dz = dr). The ceiling depth is a
        # FIXED TARGET (3.3mm - a firm seat, the user's ~3mm ask): the
        # chamber fills d3..d5, the ceiling is flat on top of it
        self.d1 = self.r_e - self.r_lip
        self.d2 = self.d1 + self.LIP_BAND
        self.d3 = self.d2 + (self.r_ch - self.r_lip)
        self.d5 = 3.30                   # flat ceiling (declared bridge)
        self.d4 = self.d5                # chamber runs up to the ceiling
        # spigot heights (from the tip): groove covers the seated lip
        self.zg0 = (self.d5 - self.d2) - self.GROOVE_M - (R - self.r_gr)
        self.zg1 = (self.d5 - self.d1) + self.GROOVE_M
        self.z_ramp_up = self.zg1 + (R - self.r_gr)
        self.z_cone = self.z_ramp_up + 1.0 + 1.5  # cylinder stub -> cone
        self.total_grip = self.z_cone + (self.GRIP_R - R) + self.GRIP_H + 1.2
        self.fit = [
            'spigot r=%.2f socket entry r=%.2f (clearance %.2fmm/side)'
            % (R, self.r_e, self.tol),
            'lip r=%.2f at depth %.2f..%.2f, snap interference %.2fmm/side'
            % (self.r_lip, self.d1, self.d2, s),
            'groove r=%.2f at spigot z %.2f..%.2f (lip clearance %.2fmm, '
            'axial play +-%.2fmm)'
            % (self.r_gr, self.zg0, self.zg1, self.r_lip - self.r_gr,
               self.GROOVE_M),
            'seated: tip on the ceiling at depth %.2f, lip locked in the '
            'groove (alignment by construction, verified by '
            'tools/r168_stampcheck.py)' % self.d5,
            'ceiling = FLAT at the chamber r=%.2f, a DECLARED BRIDGE '
            '(the tip lands clean - a 45deg chamfer here caught the tip '
            'before the lip reached the groove, found by the seating '
            'sweep)' % self.r_ch,
        ]

    # ---- socket hole surface radius at depth d (None = above ceiling) -----
    def sock_r(self, d):
        if d <= 0.0:
            return self.r_e
        if d < self.d1:                       # 45 deg entry ramp
            return self.r_e - d
        if d < self.d2:                       # lip band
            return self.r_lip
        if d < self.d3:                       # 45 deg ramp up to the chamber
            return self.r_lip + (d - self.d2)
        if d < self.d5:                       # chamber to the ceiling
            return self.r_ch
        return None                           # above the ceiling: solid

    # ---- spigot surface radius at height z (None = knob, above the cone) --
    def spig_r(self, z):
        R = self.R_P
        if z < 0.0:
            return R
        if z < 0.6:                           # 45 deg tip chamfer
            return max(3.9, R - (0.6 - z))
        if z < self.zg0:                      # cylinder
            return R
        if z < self.zg0 + (R - self.r_gr):    # 45 deg groove ramp down
            return R - (z - self.zg0)
        if z < self.zg1:                      # groove band
            return self.r_gr
        if z < self.z_ramp_up:                # 45 deg ramp back up
            return self.r_gr + (z - self.zg1)
        if z < self.z_cone:                   # cylinder to the knob
            return R
        if z < self.z_cone + (self.GRIP_R - R):   # 45 deg cone
            return R + (z - self.z_cone)
        return None                           # knob


def _stamp_base_notes(fit):
    return ['R168-STAMP FIT: %s' % x for x in fit]


def _cell_contours(mask, ox, oy, cell):
    """R168: closed contours of a boolean cell mask - OUTER boundaries AND
    hole boundaries (the user's ring: the contour runs around the ring AND
    around its open center). Loops follow the CELL EDGES (the same
    convention the R167 region walls use), collinear points merged.
    (ox, oy) = bed position of the mask origin, cell = edge length in mm.
    Returns a list of [(x, y), ...] loops in bed coordinates.

    Edge chaining with the filled cell kept on one consistent side; at
    checkerboard corners (two diagonal filled cells touching) the turn
    that hugs the incoming region wins - loops may touch at a point but
    never cross. Unclassified corner cases stay closed loops.
    """
    rows = len(mask)
    cols = len(mask[0]) if rows else 0
    out_edges = {}    # start vertex -> [end vertices]
    inc = {}

    def _add(p, q):
        out_edges.setdefault(p, []).append(q)
        inc.setdefault(q, []).append(p)

    for r in range(rows):
        mr = mask[r]
        up = mask[r - 1] if r > 0 else None
        for c in range(cols):
            if not mr[c]:
                continue
            if up is None or not up[c]:        # empty above: edge ->
                _add((c, r), (c + 1, r))
            if r + 1 >= rows or not mask[r + 1][c]:   # empty below: <-
                _add((c + 1, r + 1), (c, r + 1))
            if c == 0 or not mr[c - 1]:        # empty left: ^ (upwards)
                _add((c, r + 1), (c, r))
            if c + 1 >= cols or not mr[c + 1]:  # empty right: v (downwards)
                _add((c + 1, r), (c + 1, r + 1))
    loops = []
    # pick starts deterministically; every edge is used exactly once
    starts = sorted(out_edges.keys())
    used = {}
    for p0 in starts:
        for i, q in enumerate(out_edges.get(p0, [])):
            if used.get((p0, q)):
                continue
            loop = [p0]
            p, nxt = p0, q
            used[(p, nxt)] = True
            loop.append(nxt)
            prev_dir = (nxt[0] - p[0], nxt[1] - p[1])
            p = nxt
            while p != p0:
                outs = [e for e in out_edges.get(p, []) if not used.get((p, e))]
                if not outs:
                    break
                if len(outs) == 1:
                    nxt = outs[0]
                else:
                    # checkerboard corner: sharpest right turn keeps the
                    # loop on its own region
                    def _turn(e):
                        d = (e[0] - p[0], e[1] - p[1])
                        cross = prev_dir[0] * d[1] - prev_dir[1] * d[0]
                        return -cross      # right turns first
                    outs.sort(key=_turn)
                    nxt = outs[0]
                used[(p, nxt)] = True
                prev_dir = (nxt[0] - p[0], nxt[1] - p[1])
                loop.append(nxt)
                p = nxt
            # drop the duplicated closing point, merge collinear runs
            if len(loop) > 2 and loop[0] == loop[-1]:
                loop = loop[:-1]
            simp = [loop[0]]
            for k in range(1, len(loop) - 1):
                ax, ay = simp[-1]
                bx, by = loop[k]
                cx, cy = loop[k + 1]
                if (bx - ax) * (cy - by) == (by - ay) * (cx - bx):
                    continue          # b lies on the a->c line: not a corner
                simp.append((bx, by))
            simp.append(loop[-1])
            # wrap-around: a 'corner' that sits on the closing line is none
            if len(simp) >= 2:
                ax, ay = simp[-2]
                bx, by = simp[-1]
                cx, cy = simp[0]
                if (bx - ax) * (cy - by) == (by - ay) * (cx - bx):
                    simp.pop()          # the tail point is mid-edge
            while len(simp) > 3:
                ax, ay = simp[-1]
                bx, by = simp[0]
                cx, cy = simp[1]
                if (bx - ax) * (cy - by) == (by - ay) * (cx - bx):
                    simp.pop(0)
                else:
                    break
            if len(simp) >= 4:
                loops.append([(ox + x * cell, oy + y * cell)
                              for (x, y) in simp])
    return loops


def _make_stamp_handle(fit, out_dir='.', material='PLA', nozzle=0.6,
                       wid=0.65, layer_h=0.12, src_stem='IMG', cx=122.0,
                       cy=117.5):
    """R168: the stamp handle - snap spigot + knob, ONE standalone file
    (printed separately: 'optional' means it never wastes filament with
    the stamp). Tip down: the hollow tip (bore) makes the snap compliant,
    the groove locks under the socket lip, a 45deg cone widens to the
    knob. All slopes <= 45deg, the bore ceiling is a declared bridge.
    The fit comments mirror the stamp body's (same _StampFit168 truth) -
    tools/r168_stampcheck.py re-measures BOTH files and verifies."""
    total = max(6, int(math.ceil(fit.total_grip / layer_h)))
    z_knob = fit.z_cone + (fit.GRIP_R - fit.R_P)   # knob cylinder start
    bore_end = fit.z_ramp_up + 0.6                 # bore ceiling height
    stem = _gen_stem(src_stem, 'IMG')
    fname = 'V%02d_Griff%s.gcode' % (_next_gen_version(out_dir), stem)
    fname = _dedupe_gen_fname(out_dir, fname)
    out = os.path.join(out_dir, fname)
    fil = FIL_AREA
    e_wall = layer_h * wid / fil

    def _r_out(z):
        r = fit.spig_r(z)
        if r is not None:
            return r
        # knob cylinder + 45deg top chamfer (last 1.2mm)
        _zk = z - z_knob
        if _zk <= fit.GRIP_H:
            return fit.GRIP_R
        return max(fit.GRIP_R - 1.2, fit.GRIP_R - (_zk - fit.GRIP_H))

    with open(out, 'w') as f:
        sk = _Sink(f)
        a = sk.append
        a('; R2-LITHO stamp handle (R168) - snaps into the stamp socket,')
        a('; holds firm for stamping. Prints TIP DOWN, %.1fmm tall,'
          ' ~%.0f%% infill knob' % (total * layer_h, 12.0))
        a(TAG)
        a('; source %s - socket partner: the stamp file of the same run'
          % src_stem)
        for _n in _stamp_base_notes(fit.fit):
            a('; %s' % _n)
        a('; filament_type = %s' % material)
        a('; layer_height = %.2g' % layer_h)
        a('; nozzle_diameter = %.1f' % nozzle)
        a('; line_width = %.2g' % wid)
        a('; inner_wall_speed = 18')
        a('; initial_layer_speed = 10')
        a('; travel_speed = 120')
        types = ['BRIM', 'WALL-OUTER', 'WALL-INNER', 'INFILL-SPARSE',
                 'INFILL-SOLID', 'SURFACE-BOTTOM', 'SURFACE-TOP', 'BRIDGE',
                 'INTERNAL-BRIDGE']
        a('_FILE_INFO MATERIAL=%s LAYER_HEIGHT=%.2g TOTAL_LAYERS=%d '
          'LINE_WIDTH=%.2g LINE_WIDTH_FIRST=%.2g LINE_WIDTH_WALL=%.2g '
          'FLOW_RATIO=1 NOZZLE=%.1f WALL_LOOPS=2 SPEED_INNER=18 '
          'SPEED_FIRST=10 SPEED_TRAVEL=120 TYPES=%s BY_OBJECT=0'
          % (material, layer_h, total, wid, layer_h, wid, nozzle,
             ','.join(types)))
        a('EXCLUDE_OBJECT_DEFINE NAME=GRIFF CENTER=%.1f,%.1f '
          'POLYGON=[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]'
          % (cx, cy, cx - fit.GRIP_R - 2.0, cy - fit.GRIP_R - 2.0,
             cx + fit.GRIP_R + 2.0, cy - fit.GRIP_R - 2.0,
             cx + fit.GRIP_R + 2.0, cy + fit.GRIP_R + 2.0,
             cx - fit.GRIP_R - 2.0, cy + fit.GRIP_R + 2.0))
        a('PRINT_START MATERIAL=%s LAYER_HEIGHT=%.2g TOTAL_LAYERS=%d '
          'OUTER_WALL_SPEED=18' % (material, layer_h, total))
        a('G90')
        a('M83')
        a('M107   ; R2-GRIFF: first layer = fan off')
        pen = _Pen(sk, jump_d=6.0)
        _spc_k = wid * 100.0 / 12.0
        for li in range(1, total + 1):
            _job_tick()                    # R133b: yield to the host
            z = round(li * layer_h, 3)
            z_top = li * layer_h
            z_bot = (li - 1) * layer_h
            a(';LAYER_CHANGE')
            a(';Z:%.3f' % z)
            a('LAYER_MARK')
            pen.set_z(z)
            if li == 2:
                a('M106 S178   ; R2-GRIFF: part fan from layer 2')
            a('EXCLUDE_OBJECT_START NAME=GRIFF')
            if li == 1:
                a(_apply_type_lines('BRIM'))
                for off in (_brim_gap(wid) + wid, _brim_gap(wid)):
                    _emit_loop(pen, _circle(cx, cy, _r_out(z_top) + off),
                               e_wall, 900)
            _tyb = ('SURFACE-BOTTOM' if li == 1 else
                    'SURFACE-TOP' if li == total else None)
            a(';TYPE:Outer wall')
            a('APPLY_TYPE TYPE=%s   ; R168 spigot/knob wall'
              % (_tyb or 'WALL-OUTER'))
            _emit_loop(pen, _circle(cx, cy, _r_out(z_top) - wid / 2.0),
                       e_wall, 900 if li == 1 else 1800)
            _bore168 = z_bot < bore_end
            if _bore168:
                a(_apply_type_lines('WALL-INNER', '   ; R168 hollow tip'))
                _emit_loop(pen, _circle(cx, cy, fit.BORE + wid / 2.0),
                           e_wall, 900 if li == 1 else 1800)
                if z_bot < bore_end <= z_top:
                    # R168 bore ceiling: parallel bridge lines across the
                    # full bore, anchored on the spigot walls - closed by
                    # the disc rings above
                    a(_apply_type_lines('BRIDGE', '   ; R168 bore ceiling'))
                    _rb = fit.BORE + wid * 0.5
                    _nb = max(6, int((2.0 * _rb) / max(wid, 0.4)))
                    for _k in range(_nb + 1):
                        _off = -_rb + (2.0 * _rb) * _k / _nb
                        _hh = math.sqrt(max(0.0, _rb * _rb - _off * _off))
                        pen.travel(cx - _hh, cy + _off, 4800)
                        pen.extrude(cx + _hh, cy + _off,
                                    2.0 * _hh * e_wall, 1300)
                    a(_apply_type_lines('INTERNAL-BRIDGE'))
                    _emit_loop(pen, _circle(cx, cy, fit.BORE + wid / 2.0),
                               e_wall, 1200)
            if z_top > fit.z_cone:
                # knob + the 45deg cone below it: walls + FIXED rim rings
                # (the same radii every layer = stacked) + LINE HATCH in
                # the core. Rings cannot bridge (they never cross the
                # layer below), lines CAN - they weld at every crossing,
                # exactly like a slicer fills a top surface over sparse
                # infill. The last 4 layers switch the hatch to solid.
                a(_apply_type_lines('WALL-INNER'))
                _emit_loop(pen, _circle(cx, cy,
                                        _r_out(z_top) - 1.5 * wid),
                           e_wall, 1800)
                _rb168k = min(_r_out(z_top),
                              _r_out(max(0.0, z_top - layer_h)))
                _rr = _rb168k - 2.0 * wid
                while _rr > _rb168k - 5.0 * wid and _rr > wid:
                    _emit_loop(pen, _circle(cx, cy, _rr), e_wall, 2400)
                    _rr -= wid
                _cap_k = (li > total - 4)
                a(';TYPE:%s' % ('Top surface' if _cap_k else
                                'Sparse infill'))
                a('APPLY_TYPE TYPE=%s' % ('SURFACE-TOP' if _cap_k
                                          else 'INFILL-SPARSE'))
                _sq168 = max(wid, (_rb168k - 5.0 * wid) / math.sqrt(2.0))
                _sp168 = wid if _cap_k else _spc_k
                _sg168 = _hatch(cx - _sq168, cy - _sq168, cx + _sq168,
                                cy + _sq168, None, _sp168,
                                45.0 if li % 2 else 135.0)
                _emit_fill(pen, _sg168, e_wall, 2400, _sp168)
            elif z_top > bore_end + layer_h:
                # spigot above the bore: solid disc (small - rings fill it)
                a(_apply_type_lines('INFILL-SOLID'))
                _rr = _r_out(z_top) - 1.5 * wid
                while _rr > wid * 0.6:
                    _emit_loop(pen, _circle(cx, cy, _rr), e_wall, 2400)
                    _rr -= wid
            a('EXCLUDE_OBJECT_END NAME=GRIFF')
        a('M107')
        a('PRINT_END')
        sk.flush()
    _gen_normalize_speeds(out)   # R159: uniform 60/1500 + travel 180/8000
    info = {'file': fname, 'kind': 'stamp-handle',
            'height': round(total * layer_h, 1), 'layers': total,
            'fit': fit.fit, 'notes': []}
    return out, info


def make_labels(texts, w=60.0, h=30.0, font='SMOOTH', base_layers=4, text_layers=2,
                layer_h=0.2, first_h=0.28, ironing=True, hole_side=0, hole_d=5.0,
                brim=True, gap=12.0, color2=True, material='PLA', bed=None,
                bed_margin=6.0, nozzle=0.6, stroke=0.0, font_size=0.0, spacing=0.0,
                out_dir='.', version=1, mode='grow', job_cfgs=None,
                height=0.0, shape='RECT', corner=0.0, border_walls=0,
                border_gap=0.0, sparse_pct=8.0, ring=False, ring_d=6.0,
                ring_h=0.0, mirror_x=0, mirror_y=0, stamp=0,
                stamp_base=5.0, stamp_tol=0.25, handle=0,
                stamp_infill=10.0, walls=0, flip=0):
    """Generate printable label plate file(s). Returns (path, info).

    R170 (field report .128): an overflow no longer ERRORS - the job splits
    into several files (part 1, part 2, ... - every part a complete plate
    with its own purge tower, reading order preserved). The wrapper peels
    the largest fitting prefix via a dry layout run and calls the
    single-plate builder per batch. info gains 'files' + 'parts'.

    Handle modes (R170, user choice): 0 = none. 1 = ON THE PLATE with the
    stamp, positioned last (printed after the labels every layer - nothing
    gets ripped off). 2 = separate handle file (as before). 3 = handle
    file ONLY (reprint a lost one)."""
    stamp_b = str(stamp).strip().lower() in ('1', 'true', 'on', 'yes')
    try:
        handle_i = max(0, min(int(handle or 0), 3))
    except (TypeError, ValueError):
        handle_i = 0
    if stamp_b and handle_i == 3:
        # handle ONLY - no label plate, bed center (reprint a lost handle)
        _lh170h = max(0.06, min(float(layer_h or 0.2), 0.34))
        _fit170h = _StampFit168(
            tol=max(0.10, min(float(stamp_tol or 0.25), 0.50)),
            layer_h=_lh170h)
        return _make_stamp_handle(
            _fit170h, out_dir=out_dir, material=material, nozzle=nozzle,
            wid=max(0.4, nozzle * 1.08), layer_h=_lh170h,
            src_stem=_safe_label_name(str(texts[0]) if texts else 'IMG'))

    def _one170(txts, cfgs, part=0, dry=False):
        return _make_labels_one(
            txts, w=w, h=h, font=font, base_layers=base_layers,
            text_layers=text_layers, layer_h=layer_h, first_h=first_h,
            ironing=ironing, hole_side=hole_side, hole_d=hole_d, brim=brim,
            gap=gap, color2=color2, material=material, bed=bed,
            bed_margin=bed_margin, nozzle=nozzle, stroke=stroke,
            font_size=font_size, spacing=spacing, out_dir=out_dir,
            version=version, mode=mode, job_cfgs=cfgs, height=height,
            shape=shape, corner=corner, border_walls=border_walls,
            border_gap=border_gap, sparse_pct=sparse_pct, ring=ring,
            ring_d=ring_d, ring_h=ring_h, mirror_x=mirror_x,
            mirror_y=mirror_y, stamp=stamp, stamp_base=stamp_base,
            stamp_tol=stamp_tol, handle=handle, stamp_infill=stamp_infill,
            part=part, dry_layout=dry, walls=walls, flip=flip)

    _fiterr170 = 'labels do not fit the bed'      # R221: except-names are unbound
    try:                                          # after the block - 'raise e170'
        return _one170(texts, job_cfgs)           # below was a NameError
    except ValueError as e170:
        if 'do not fit the bed' not in str(e170):
            raise
        _fiterr170 = str(e170)
    # ---- R170: split into parts (largest fitting prefix, reading order) ----
    _rest170 = list(texts)
    _cfgs170 = list(job_cfgs) if job_cfgs else None
    _outs170, _infos170 = [], []
    _part170 = 0
    while _rest170:
        _k170 = len(_rest170)
        while _k170 > 1:
            try:
                _one170(_rest170[:_k170],
                        (_cfgs170[:_k170] if _cfgs170 else None), dry=True)
                break
            except ValueError:
                _k170 -= 1
        if _k170 <= 0:
            raise ValueError('label too large for the bed even alone')
        _part170 += 1
        _outp170, _infop170 = _one170(
            _rest170[:_k170], (_cfgs170[:_k170] if _cfgs170 else None),
            part=_part170)
        _outs170.append(_outp170)
        _infos170.append(_infop170)
        _rest170 = _rest170[_k170:]
        if _cfgs170:
            _cfgs170 = _cfgs170[_k170:]
    if not _infos170:
        raise ValueError(_fiterr170)
    _info170 = dict(_infos170[0])
    _info170['files'] = [i['file'] for i in _infos170]
    _info170['parts'] = len(_infos170)
    return _outs170[0], _info170


def _make_labels_one(texts, w=60.0, h=30.0, font='SMOOTH', base_layers=4, text_layers=2,
                     layer_h=0.2, first_h=0.28, ironing=True, hole_side=0, hole_d=5.0,
                     brim=True, gap=12.0, color2=True, material='PLA', bed=None,
                     bed_margin=6.0, nozzle=0.6, stroke=0.0, font_size=0.0, spacing=0.0,
                     out_dir='.', version=1, mode='grow', job_cfgs=None,
                     height=0.0, shape='RECT', corner=0.0, border_walls=0,
                     border_gap=0.0, sparse_pct=8.0, ring=False, ring_d=6.0,
                ring_h=0.0, mirror_x=0, mirror_y=0, stamp=0,
                stamp_base=5.0, stamp_tol=0.25, handle=0,
                stamp_infill=10.0, part=0, dry_layout=False, walls=0, flip=0):
    """Generate ONE printable label plate file. Returns (path, info).

    R74: every entry may carry up to 3 lines separated by '~' (LCD: Labels >
    Text > Line). font_size = cap height in mm (0 = auto), spacing = extra
    millimeters between characters. The text block is one UNIFORM scale -
    letters never stretch; lines that do not fit raise an error that names
    the character maximum for this label size.
    R99 (field log .75): mode - 'grow' (default): the LABEL adapts to the
    text (grows until the font size fits; W/H are minimums) - 'fixed': the
    label stays at W/H and the FONT scales into it (font_size is the upper
    bound then; 0 = as large as the label allows).
    R170: part>0 appends '_T<part>' to the file name (split jobs); a
    dry_layout run stops after the packing stage and writes nothing."""
    texts = [t.strip() for t in texts if t and t.strip()]
    if not texts:
        raise ValueError('no label text - add one first (LCD: Labels > Text)')
    if len(texts) > 24:
        raise ValueError('at most 24 labels per job (got %d)' % len(texts))
    font = str(font).upper()
    # R80: PIXEL is gone (field log .63: unreadable) - MONO + SMOOTH stay;
    # a saved 'PIXEL' selection falls back to SMOOTH (R80); R82 adds
    # COND / NARROW / CAPS - the small-text fonts
    if font not in _LABEL_STROKE_FONTS:
        font = 'SMOOTH'
    font_size = max(0.0, min(float(font_size or 0.0), 40.0))
    spacing = max(0.0, min(float(spacing or 0.0), 10.0))
    # R74: '~' separates the lines of ONE label (the charset has no '~' - the
    # LCD can never type it into a line by accident)
    all_lines = []
    for t in texts:
        ls = [x.strip() for x in t.split('~') if x.strip()]
        # R286 (Befund: kyrillische / nicht-unterstuetzte Zeichen im Label):
        # Zeichen ausserhalb LABEL_CHARSET werden SICHER zu '?' ersetzt, damit
        # sie nicht ungestuerd in die Render-Geometrie gelangen (ein kyrill-
        #isches 'T' U+0422 sah wie ein lateinisches 'T' aus und landete im
        # G-Code). Konsistent mit der Datei-Lese-Sanitisierung.
        _lc_allowed = set(LABEL_CHARSET)
        ls = [''.join(ch if ch in _lc_allowed else '?' for ch in x) for x in ls]
        if not ls:
            raise ValueError('label "%s" has no text' % t[:16])
        if len(ls) > 5:
            raise ValueError('label "%s" has %d lines - at most 5 per label' % (t[:16], len(ls)))
        all_lines.append(ls)
    w = float(w)
    h = float(h)
    if not (12.0 <= w <= 320.0) or not (10.0 <= h <= 320.0):
        raise ValueError('label size %.1fx%.1fmm out of range (12..320 / 10..320)' % (w, h))
    # ---- R119: shape / border / height (mm) ---------------------------------
    # shape: RECT (classic, byte-identical default), OVAL, ROUND (corner
    # radius in mm). The border is a raised ring ON THE TEXT LAYERS - same
    # start, same color as the text (the M600 swap sits right before them).
    _sh119 = str(shape or 'RECT').strip().upper()
    if _sh119 in ('OVAL', 'ELLIPSE', 'O', '1'):
        shape = 'OVAL'
    elif _sh119 in ('ROUND', 'ROUNDED', 'RUND', 'R', '2'):
        shape = 'ROUND'
    else:
        shape = 'RECT'
    corner = max(0.0, min(float(corner or 0.0), 12.0))
    if shape != 'ROUND':
        corner = 0.0
    border_walls = max(0, min(int(border_walls), 4))
    border_gap = max(0.0, min(float(border_gap or 0.0), 10.0))
    # R120: external hanging ring instead of the in-label hole (position =
    # hole_side). Prints from LAYER 1 flush against the label edge; its
    # height never exceeds the label's total height.
    ring = bool(ring) and hole_side in (1, 2, 3, 4)
    ring_d = max(3.0, min(float(ring_d or 6.0), 20.0))
    ring_wt = 3.0 * max(0.4, nozzle * 1.08)   # ring band = three wall lines
    ring_ri = ring_d / 2.0
    ring_ro = ring_ri + ring_wt
    # height in mm (0 = the classic base_layers count rules). Up to 20mm:
    # >6 base layers print as 4 bottom + 4 top solid with sparse infill
    # between (like the frames) - solid bases that tall waste filament and
    # print stop-and-go.
    height = float(height or 0.0)
    if height > 0.0:
        height = max(0.4, min(height, 20.0))
        base_layers = max(2, min(int(math.ceil((height - first_h) / layer_h)) + 1, 110))
    base_layers = max(2, min(int(base_layers), 110))
    if base_layers > 6:
        bot_solid = 4
        top_solid = min(4, base_layers - 4)
        sparse_mid = base_layers - bot_solid - top_solid
    else:
        bot_solid, top_solid, sparse_mid = base_layers, 0, 0
    text_layers = max(1, min(int(text_layers), 50))   # R149: up to 10mm raised text
    layer_h = max(0.06, min(float(layer_h), 0.34))
    first_h = max(0.08, min(float(first_h), 0.42))
    hole_side = int(hole_side) % 5
    # R170 (field report .128): at least 10mm between labels in every
    # direction - the user explicitely asked for 1cm clearance
    gap = max(10.0, min(float(gap), 30.0))
    wid = max(0.4, nozzle * 1.08)          # perimeter / infill line width
    # the text box must clear the raised border (gap + walls + 1.2mm air)
    border_m = (border_gap + border_walls * wid + 1.2) if border_walls > 0 else 0.0
    # R120: with a border the hole sits INSIDE the border ring (the border
    # never breaks); with a ring there is no in-label hole at all
    if ring:
        _eff_hole_side = 0
        hole_edge120 = 2.0
    else:
        _eff_hole_side = hole_side
        hole_edge120 = (wid / 2.0 + border_gap + border_walls * wid + 1.2 \
                        if border_walls > 0 else 2.0)
    # ---- stroke width - 'Stroke' IS the extrusion line width (R80 field Q) ---
    # R224 (.136s field log): 'walls' is the PRIMARY knob now - the LCD sets
    # 'Text: N walls' (N extrusion lines through every glyph stroke, exactly
    # the count the 3D viewer shows). Explicit stroke in mm (console) still
    # works; walls wins when both are given.
    # 0 = auto: 3 extrusion lines (solid, chunky letters). Explicit value =
    # line width in mm - set it to your NOZZLE diameter (0.6 -> single-line
    # letters). The old clamp forced >= 2 lines; a user 0.6 became 1.22.
    twid = max(0.4, nozzle * 1.02)         # one text extrusion line
    stroke_w = float(stroke or 0.0)
    try:
        _walls224 = max(0, min(int(walls or 0), 4))
    except (TypeError, ValueError):
        _walls224 = 0
    if _walls224 > 0:
        stroke_w = _walls224 * twid
    if stroke_w <= 0:
        stroke_w = 3.0 * twid
    stroke_w = max(twid, min(stroke_w, 4.0))
    if bed is None:
        bed = (0.0, -3.0, 244.0, 238.0)
    bx0, by0, bx1, by1 = bed
    ux0, uy0 = bx0 + bed_margin, by0 + bed_margin
    ux1, uy1 = bx1 - bed_margin, by1 - bed_margin
    uw, uh = ux1 - ux0, uy1 - uy0

    # ---- R116 per-job settings (.88 field log: the queue stored ONLY the
    #      text - font/size were read globally at Create time, so a mixed
    #      queue of 10 labels x 5 fonts all printed with the LAST font).
    #      LABEL_ADD now snapshots the label settings per job; job_cfgs keys
    #      used per job: font, w, h, size, spacing, stroke, mode, hole_side,
    #      hole_d. Layers/layer heights/ironing/brim/gap/color2 stay ONE
    #      setting for the whole batch (print tech, not label look).
    #      None/empty -> the classic uniform path, byte-identical.
    jobs = None
    if job_cfgs:
        jobs = []
        for _ji, _t in enumerate(texts):
            _jc = job_cfgs[_ji] if _ji < len(job_cfgs) and job_cfgs[_ji] else {}
            if not isinstance(_jc, dict):
                _jc = {}
            _f116 = str(_jc.get('font', font) or font).upper()
            if _f116 not in _LABEL_STROKE_FONTS:
                _f116 = font if font in _LABEL_STROKE_FONTS else 'SMOOTH'

            def _cf116(key, dflt, lo, hi):
                _v = _jc.get(key, None)
                if _v is None or _v == '':
                    _v = dflt
                try:
                    _v = float(_v)
                except (TypeError, ValueError):
                    _v = float(dflt)
                return max(lo, min(_v, hi))
            _st116 = _jc.get('stroke', None)
            if _st116 is None or _st116 == '':
                _st116 = stroke_w
            try:
                _st116 = float(_st116)
            except (TypeError, ValueError):
                _st116 = stroke_w
            if _st116 <= 0:
                _st116 = 3.0 * twid
            _st116 = max(twid, min(_st116, 4.0))
            jobs.append({
                'font': _f116,
                'w': _cf116('w', w, 12.0, 320.0),
                'h': _cf116('h', h, 10.0, 320.0),
                'size': _cf116('size', font_size, 0.0, 40.0),
                'spacing': _cf116('spacing', spacing, 0.0, 10.0),
                'stroke': _st116,
                'mode': (str(_jc.get('mode', mode)).strip().lower()
                         in ('fixed', 'fix', '1', 'true')),
                'hole_side': int(_cf116('hole_side', hole_side, 0, 4)) % 5,
                'hole_d': _cf116('hole_d', hole_d, 0.0, 12.0),
            })

    # ---- R80 AUTO-FIT + AUTO-GROW (field log .63: endless 'needs X mm but
    #      only Y usable' errors; a 6cm tag that holds 3 characters is useless):
    #      the FONT adapts to the label (94% fill, only filled lines count) -
    #      and if the letters would get unreadable (<2.8mm caps) or an explicit
    #      font size does not fit, the LABEL GROWS (width first, then height,
    #      +75% max) instead of erroring. The text is never shortened.
    #      R99 (field log .75): mode='fixed' turns the growth OFF - the label
    #      stays at W/H, the font scales into it (user spec: either the label
    #      fits the text or the text fits the label).
    n = len(texts)
    if jobs:
        # R116 mixed sizes: fit + grow PER JOB, then shelf-pack in reading
        # order (rows wrap at the bed width, row height = tallest label)
        grown79 = False
        for _ji, _jb in enumerate(jobs):
            if _jb['mode']:
                # R133 (field log .93): FIXED jobs never grow - but they
                # still need the flag (the info line reads jb['grown'],
                # KeyError crashed every FIXED-mode creation)
                _jb['grown'] = False
                continue
            _hs120 = 0 if ring else _jb['hole_side']
            _w116, _h116, _g116, _mc116 = _label_grow_fit(
                [all_lines[_ji]], _jb['font'], _jb['w'], _jb['h'],
                _jb['size'], _jb['spacing'], _jb['stroke'],
                _hs120, _jb['hole_d'], shape=shape,
                corner=corner, margin_extra=border_m, hole_edge=hole_edge120)
            _jb['w'], _jb['h'] = _w116, _h116
            _jb['grown'] = _g116
            grown79 = grown79 or _g116
        _pos116 = []
        _x116, _y116 = ux0, uy0
        _rowh116 = 0.0
        for _jb in jobs:
            if ring:
                if hole_side in (1, 2):
                    _jb['w'] += 2.0 * ring_ro + 1.0
                else:
                    _jb['h'] += 2.0 * ring_ro + 1.0
            if _x116 > ux0 + 0.01 and _x116 + _jb['w'] > ux1:
                _x116 = ux0
                _y116 += _rowh116 + gap
                _rowh116 = 0.0
            if _y116 + _jb['h'] > uy1 + 0.01:
                raise ValueError('labels do not fit the bed (%.0fx%.0fmm usable) - '
                                 'fewer/smaller labels or a smaller gap'
                                 % (uw, uh))
            _pos116.append((_x116, _y116))
            _x116 += _jb['w'] + gap
            _rowh116 = max(_rowh116, _jb['h'])
        _bx0 = min(_p[0] for _p in _pos116)
        _by0 = min(_p[1] for _p in _pos116)
        _bx1 = max(_p[0] + _j['w'] for _p, _j in zip(_pos116, jobs))
        _by1 = max(_p[1] + _j['h'] for _p, _j in zip(_pos116, jobs))
        gw, gh = _bx1 - _bx0, _by1 - _by0
        _dx116 = ux0 + (uw - gw) / 2.0 - _bx0
        _dy116 = uy0 + (uh - gh) / 2.0 - _by0
        positions = [(_p[0] + _dx116, _p[1] + _dy116) for _p in _pos116]
        _rws116 = 1 + sum(1 for _i in range(1, len(_pos116))
                          if _pos116[_i][1] > _pos116[_i - 1][1] + 0.01)
        cols, rows = n if _rws116 == 1 else -(-n // _rws116), _rws116
        # R170 (field report .128 - the layout chaos): the shelf positions
        # STAY. The old shared grid loop overwrote them with UNIFORM cells
        # built from the global w/h - grown or per-job labels then printed
        # ON TOP of their neighbors (repro: a 94mm label ended up 21.6mm
        # inside the next 60mm cell). The uniform grid below is
        # non-jobs-mode ONLY now.
        gx0 = ux0 + (uw - gw) / 2.0
        gy0 = uy0 + (uh - gh) / 2.0
    else:
        if str(mode).strip().lower() in ('fixed', 'fix', '1'):
            grown79 = False
            mcache = [_label_metrics(ls, font, spacing) for ls in all_lines]
        else:
            w, h, grown79, mcache = _label_grow_fit(
                all_lines, font, w, h, font_size, spacing, stroke_w,
                _eff_hole_side, hole_d, shape=shape, corner=corner,
                margin_extra=border_m, hole_edge=hole_edge120)

        # R120: the external ring reserves its side of the cell
        _w_g120 = _h_g120 = 0.0
        if ring:
            if hole_side in (1, 2):
                _w_g120 = 2.0 * ring_ro + 1.0
                w += _w_g120
            else:
                _h_g120 = 2.0 * ring_ro + 1.0
                h += _h_g120

        # ---- fit the grid: labels read left->right, so use the MOST columns that
        #      still fit the bed (rows fill naturally); max = cols*rows per batch ----
        best = None
        for cols in range(n, 0, -1):
            rows = -(-n // cols)
            gw = cols * w + (cols - 1) * gap
            gh = rows * h + (rows - 1) * gap
            if gw <= uw and gh <= uh:
                best = (cols, rows, gw, gh)
                break
        if best is None:
            # nothing fits - report how many WOULD fit for a helpful error message
            raise ValueError('%d label(s) of %.0fx%.0fmm (+%.0fmm gap) do not fit the bed '
                             '(%.0fx%.0fmm usable) - fewer/smaller labels or a smaller gap'
                             % (n, w, h, gap, uw, uh))
        cols, rows, gw, gh = best
        gx0 = ux0 + (uw - gw) / 2.0
        gy0 = uy0 + (uh - gh) / 2.0
        positions = []
        _sh120x = (2.0 * ring_ro + 1.0) if (ring and hole_side == 1) else 0.0
        _sh120y = (2.0 * ring_ro + 1.0) if (ring and hole_side == 3) else 0.0
        for i in range(n):
            r, c = divmod(i, cols)
            positions.append((gx0 + c * (w + gap) + _sh120x,
                              gy0 + r * (h + gap) + _sh120y))

    # ---- purge tower (only for 2-color jobs): beside / in front of the grid
    tw = 12.0
    tower = None
    if color2:
        # R83: 15mm clearance (field log .65: the probe could catch on the
        # tower's purge corner -> layer shift) and RIGHT of the grid first -
        # the probe hangs ~43mm LEFT of the nozzle, so a left tower sits in
        # its sweep while the label prints
        tg = 15.0
        cands = [(gx0 + gw + tg, gy0), (gx0, gy0 + gh + tg),
                 (gx0, gy0 - tw - tg), (gx0 - tw - tg, gy0)]
        for (tx, ty) in cands:
            if tx >= ux0 and ty >= uy0 and tx + tw <= ux1 and ty + tw <= uy1:
                tower = (tx, ty)
                break

    # (stroke_w was computed before the auto-grow pass - R80; the fit below
    # RESERVES it: the printed stroke is skeleton + stroke_w wide)

    # ---- per-label geometry (R74 line typography + edge hole) -----------------
    labels = []
    for i, ls in enumerate(all_lines):
        lx, ly = positions[i]
        _rw120 = _rh120 = 0.0     # R120 ring reservation on this label's cell
        if jobs:
            jb = jobs[i]
            lw, lh, lfont = jb['w'], jb['h'], jb['font']
            lsize, lspacing, lstroke = jb['size'], jb['spacing'], jb['stroke']
            lhs, lhd = jb['hole_side'], jb['hole_d']
            if ring:
                if hole_side in (1, 2):
                    _rw120 = 2.0 * ring_ro + 1.0
                else:
                    _rh120 = 2.0 * ring_ro + 1.0
        else:
            lw, lh, lfont = w, h, font
            lsize, lspacing, lstroke = font_size, spacing, stroke_w
            lhs, lhd = hole_side, hole_d
            _rw120, _rh120 = _w_g120, _h_g120
        if ring:
            # the ring replaces the in-label hole; the cell carries the
            # reservation - the LABEL itself keeps its true size
            lw -= _rw120
            lh -= _rh120
            if hole_side == 1:
                lx += _rw120
            elif hole_side == 3:
                ly += _rh120
            lhs = 0
        circ, box, hd = _label_layout(lw, lh, lhs, lhd, shape, corner,
                                   border_m, hole_edge120)
        paths, geo = _label_text_lines(ls, lfont, box, lw, lh, lsize, lspacing,
                                       stroke_w=lstroke)
        _rc120 = None
        if ring:
            _ov120 = wid * 1.2   # weld: ring outer line reaches between
                                   # the label's outer and inner wall
            if hole_side == 1:
                _rc120 = (lx - ring_ro + _ov120, ly + lh / 2.0)
            elif hole_side == 2:
                _rc120 = (lx + lw + ring_ro - _ov120, ly + lh / 2.0)
            elif hole_side == 3:
                _rc120 = (lx + lw / 2.0, ly + lh + ring_ro - _ov120)
            else:
                _rc120 = (lx + lw / 2.0, ly - ring_ro + _ov120)
        labels.append({'name': 'LABEL_%d' % (i + 1), 'text': ' / '.join(ls),
                       'lines': ls, 'x': lx, 'y': ly, 'w': lw, 'h': lh,
                       'font': lfont,
                       'stroke_eff': round(min(lstroke, max(twid, 0.34 * geo['cap_h'])), 2),
                       'circ': circ, 'box': box, 'paths': paths, 'hole_d': hd,
                       'cap_h': geo['cap_h'], 's': geo['s'], 'sx': geo['s'],
                       'ring_c': _rc120, 'ring_ro': ring_ro, 'ring_ri': ring_ri})

    # ---- R168: mirror + stamp (user request) --------------------------
    # R224 (.136s field log): the standalone mirror switches are GONE from
    # the LCD - normal text is never mirrored, and a STAMP mirrors itself
    # automatically (the pressed imprint must read correct). One decision
    # per job: label or stamp.
    stamp = 1 if str(stamp).strip().lower() in ('1', 'true', 'on', 'yes') else 0
    mirror_x = 1 if (stamp or str(mirror_x).strip().lower()
                     in ('1', 'true', 'on', 'yes')) else 0
    mirror_y = 1 if str(mirror_y).strip().lower() in ('1', 'true', 'on', 'yes') else 0
    # ---- R231 (.136ab field log): FLIP mode + the INLaid text model -------
    # flip prints the label text-face DOWN: the buildplate finish lands on
    # the letter surface. The text MIRRORS in the file so it reads CORRECT
    # after the part comes off the bed (a stamp is the only case where a
    # mirrored result is wanted - flip and stamp exclude each other).
    flip = 1 if str(flip).strip().lower() in ('1', 'true', 'on', 'yes') else 0
    if flip:
        if stamp:
            raise ValueError('Flip and Stamp exclude each other: Flip prints '
                             'text-face-down for a READABLE surface, a Stamp '
                             'mirrors for the imprint - pick one')
        if ring and color2:
            raise ValueError('Flip + Ring + 2 colors: the ring prints in the '
                             'text-color block - print single color or drop '
                             'the ring')
        for lb in labels:
            lb['paths'] = [[(lb['w'] - px, py) for (px, py) in path]
                           for path in lb['paths']]
    # text_layers = the TOTAL text depth in the label: 2 = flush with the
    # surface (layer 1 burned into the solid-infill layer, layer 2 in the
    # top layer), 3/4 add raised layers ON TOP of the flush inlay
    # ('Schichten 3+4 addieren auf Hoehe'). Old meaning (raise above the
    # base) = text_layers - 2 now.
    try:
        text_layers = max(2, min(int(text_layers or 2), 4))
    except (TypeError, ValueError):
        text_layers = 2
    if base_layers < 2:
        base_layers = 2     # the inlay needs the infill layer under the top
    raised_t231 = max(0, text_layers - 2)
    if flip and ironing:
        # the ironing pass would run on the label's BACK (the face that
        # prints last in flip) - pointless, and the text face is on the bed
        ironing = False
    if mirror_x or mirror_y:
        for lb in labels:
            if mirror_x:
                lb['paths'] = [[(lb['w'] - px, py) for (px, py) in path]
                               for path in lb['paths']]
            if mirror_y:
                lb['paths'] = [[(px, lb['h'] - py) for (px, py) in path]
                               for path in lb['paths']]
    # R170 handle modes (user choice): 0 = none. 1 = ON THE PLATE with the
    # stamp, printed LAST every layer. 2 = separate handle file (as .127).
    # 3 = handle file ONLY (short-circuited in the make_labels wrapper).
    try:
        handle = max(0, min(int(handle or 0), 3))
    except (TypeError, ValueError):
        handle = 0
    if handle and not stamp:
        raise ValueError('Handle needs Stamp ON - it snaps into the stamp '
                         'socket (Labels > Settings > Stamp)')
    stamp_base = max(3.5, min(float(stamp_base or 5.0), 15.0))
    stamp_tol = max(0.10, min(float(stamp_tol or 0.25), 0.50))
    fit168 = None
    if stamp:
        # R286 (Befund 4c): MULTIPLE stamp labels per job are allowed -
        # every stamp label carries its own snap socket under its text and
        # its own handle on the plate (the old 'exactly ONE label per job'
        # rule dropped the handles when the job had more than one stamp).
        if any(lb['circ'] for lb in labels):
            raise ValueError('stamp labels print without the label hole '
                             '(Hole=0) - the snap socket IS the mount')
        fit168 = _StampFit168(tol=stamp_tol, layer_h=layer_h)
        _need168 = max(stamp_base, fit168.d5 + 2.0 * layer_h + 0.4)
        while first_h + (base_layers - 1) * layer_h < _need168:
            base_layers += 1
        for lb0 in labels:
            if min(lb0['w'], lb0['h']) < 2.0 * fit168.r_e + 6.0:
                raise ValueError('stamp label too small: the socket '
                                 '(d%.1fmm) needs a label of at least '
                                 '%.0fx%.0fmm'
                                 % (2.0 * fit168.r_e,
                                    2.0 * fit168.r_e + 6.0,
                                    2.0 * fit168.r_e + 6.0))
        if handle == 1 and not mirror_x:
            pass    # noted in the job message; no hidden flips

    # ---- R170: the handle ON THE PLATE (mode 1) ------------------------------
    # Printed LAST on every layer (the nozzle never finishes on a label it
    # could rip off), placed with 12mm clearance from every label, the
    # purge tower and the bed edge. Same _StampFit168 truth as the socket -
    # the on-plate handle snaps exactly like the standalone file's.
    _hplate170 = bool(fit168 is not None and handle == 1)
    _hl170 = 0
    _hpos170 = []
    if _hplate170:
        _hl170 = max(6, int(math.ceil(fit168.total_grip / layer_h)))
        _hr170 = fit168.GRIP_R + 2.5
        _rects170 = [(lb['x'], lb['y'], lb['x'] + lb['w'], lb['y'] + lb['h'])
                     for lb in labels]
        if tower:
            _rects170.append((tower[0], tower[1],
                              tower[0] + tw, tower[1] + tw))
        _cl170 = 12.0
        _bx0h = min(r[0] for r in _rects170)
        _bx1h = max(r[2] for r in _rects170)
        _by0h = min(r[1] for r in _rects170)
        _by1h = max(r[3] for r in _rects170)
        _cxh = (_bx0h + _bx1h) / 2.0
        _cyh = (_by0h + _by1h) / 2.0
        # R286 (Befund 4c): ONE handle PER stamp label - the candidates are
        # the four sides of the label cluster; each placed handle keeps its
        # clearance from every label, the tower and the handles already
        # placed. The handles MUST land on the plate (the user's complaint:
        # the handles were missing when the job had more than one stamp).
        _ncand170 = len(labels)
        if _ncand170 > 4:
            raise ValueError('%d stamp handles do not fit the plate - at '
                             'most 4 handles (one per cluster side), use '
                             'Handle=2 (separate files) for more'
                             % _ncand170)
        for _hx, _hy in ((_bx1h + _cl170 + _hr170, _cyh),
                         (_bx0h - _cl170 - _hr170, _cyh),
                         (_cxh, _by0h - _cl170 - _hr170),
                         (_cxh, _by1h + _cl170 + _hr170)):
            if len(_hpos170) >= _ncand170:
                break
            if not (ux0 <= _hx - _hr170 and _hx + _hr170 <= ux1
                    and uy0 <= _hy - _hr170 and _hy + _hr170 <= uy1):
                continue
            _ok170 = True
            for (_rx0, _ry0, _rx1, _ry1) in _rects170:
                if (min(_hx + _hr170, _rx1 + _cl170)
                        - max(_hx - _hr170, _rx0 - _cl170) > 0.0
                        and min(_hy + _hr170, _ry1 + _cl170)
                        - max(_hy - _hr170, _ry0 - _cl170) > 0.0):
                    _ok170 = False
                    break
            for (_hpx, _hpy) in _hpos170:
                if (min(_hx + _hr170, _hpx + _hr170)
                        - max(_hx - _hr170, _hpx - _hr170) > 0.0
                        and min(_hy + _hr170, _hpy + _hr170)
                        - max(_hy - _hr170, _hpy - _hr170) > 0.0):
                    _ok170 = False
                    break
            if _ok170:
                _hpos170.append((_hx, _hy))
        if len(_hpos170) < _ncand170:
            raise ValueError('no room for %d handle(s) on the plate - '
                             'fewer/smaller labels, a smaller gap, or '
                             'Handle=2 (separate file)' % _ncand170)
    if dry_layout:
        # R170: layout probe only - packing + handle placement decided,
        # NOTHING is written (the split loop fires dozens of these per job;
        # the .128-era dry runs left V0x residue files behind)
        return None, None

    def _handle_r170(z):
        """R170: outer radius of the handle at height z (spigot -> cone ->
        knob -> top chamfer) - the standalone file's _r_out, one truth."""
        r = fit168.spig_r(z)
        if r is not None:
            return r
        _zk = z - (fit168.z_cone + (fit168.GRIP_R - fit168.R_P))
        if _zk <= fit168.GRIP_H:
            return fit168.GRIP_R
        return max(fit168.GRIP_R - 1.2,
                   fit168.GRIP_R - (_zk - fit168.GRIP_H))

    def handle_block(z, li):
        """R170: one handle layer - LAST object of the layer, z-hop
        approach (never skims a finished label), bore ceiling bridged.
        R286 (Befund 4c): one block PER handle - a job with several
        stamps carries one handle per stamp, all on the plate."""
        _ew170 = layer_h_eff(li) * wid / fil
        _zbot170 = (first_h + (li - 2) * layer_h) if li > 1 else 0.0
        _bore_end170 = fit168.z_ramp_up + 0.6
        for _hx, _hy in _hpos170:
            L.append('G0 Z%.3f F600   ; R170: hop over to the handle'
                     % (z + 3.0))
            pen.travel(_hx - _handle_r170(z) - wid, _hy, 4800)
            L.append('G0 Z%.3f F600' % z)
            L.append('EXCLUDE_OBJECT_START NAME=GRIFF')
            if li == 1 and brim:
                L.append(';TYPE:Brim')
                # R183: same air-gap fix as the label base brim - the
                # handle wall ink reaches its radius, the first brim line
                # keeps clear
                _bgap183 = wid + 0.35
                for off in (_bgap183 + wid, _bgap183):
                    _emit_loop(pen, _circle(_hx, _hy,
                                            _handle_r170(z) + off),
                               _ew170, 900)
            L.append(';TYPE:Outer wall')
            _emit_loop(pen, _circle(_hx, _hy, _handle_r170(z) - wid / 2.0),
                       _ew170, 900 if li == 1 else 1800)
            if _zbot170 < _bore_end170:
                L.append(';TYPE:Inner wall')
                _emit_loop(pen, _circle(_hx, _hy, fit168.BORE + wid / 2.0),
                           _ew170, 900 if li == 1 else 1800)
                if _zbot170 < _bore_end170 <= z:
                    L.append(';TYPE:Bridge')
                    _rb = fit168.BORE + wid * 0.5
                    _nb = max(6, int((2.0 * _rb) / max(wid, 0.4)))
                    for _k in range(_nb + 1):
                        _off = -_rb + (2.0 * _rb) * _k / _nb
                        _hh = math.sqrt(max(0.0, _rb * _rb
                                             - _off * _off))
                        pen.travel(_hx - _hh, _hy + _off, 4800)
                        pen.extrude(_hx + _hh, _hy + _off,
                                    2.0 * _hh * _ew170, 1300)
                    L.append(';TYPE:Internal bridge')
                    _emit_loop(pen, _circle(_hx, _hy,
                                            fit168.BORE + wid / 2.0),
                               _ew170, 1200)
            if z > fit168.z_cone:
                L.append(';TYPE:Inner wall')
                _emit_loop(pen, _circle(_hx, _hy,
                                        _handle_r170(z) - 1.5 * wid),
                           _ew170, 1800)
                _rbk = min(_handle_r170(z),
                           _handle_r170(max(0.0, z - layer_h)))
                _rr = _rbk - 2.0 * wid
                while _rr > _rbk - 5.0 * wid and _rr > wid:
                    _emit_loop(pen, _circle(_hx, _hy, _rr), _ew170, 2400)
                    _rr -= wid
                # R286 (Befund 1): the cap is solid hatch on every layer,
                # but only the TOP layer carries 'Top surface' - no stacked
                # top on top, and the top never sits directly on the sparse
                # cone body (the layers below are solid infill).
                _capk = (li == _hl170)
                L.append(';TYPE:%s' % ('Top surface' if _capk
                                       else 'Internal solid infill'))
                _sq = max(wid, (_rbk - 5.0 * wid) / math.sqrt(2.0))
                _sp = wid
                _sg = _hatch(_hx - _sq, _hy - _sq, _hx + _sq, _hy + _sq,
                             None, _sp, 45.0 if li % 2 else 135.0)
                _emit_fill(pen, _sg, _ew170, 2400, _sp)
            elif z > _bore_end170 + layer_h:
                L.append(';TYPE:Internal solid infill')
                _rr = _handle_r170(z) - 1.5 * wid
                while _rr > wid * 0.6:
                    _emit_loop(pen, _circle(_hx, _hy, _rr), _ew170, 2400)
                    _rr -= wid
            pen.holes = []
            L.append('EXCLUDE_OBJECT_END NAME=GRIFF')

    def _lb_contour(lb, inset):
        """R119: this label's wall contour in ABSOLUTE coords, the path
        centerline `inset` mm inside the label edge. RECT -> None: the
        classic rect loops stay (byte-identical default output)."""
        pts = _label_outline(lb['w'], lb['h'], shape, corner, inset)
        if pts is None:
            return None
        # the outline helpers center on (0,0) - shift to the LABEL CENTER
        return [(lb['x'] + lb['w'] / 2.0 + px, lb['y'] + lb['h'] / 2.0 + py)
                for (px, py) in pts]

    # ---- R231: keep-out geometry for the inlaid top layer -----------------
    # The top layer's plate fill (and ironing) must print AROUND the text
    # bands and the border ring - the color-B letter fills own those
    # regions. One computation per label, reused by every clipped layer.
    for lb in labels:
        _half231 = min(lb['stroke_eff'],
                       max(2.0 * twid, 2.1 * lb['sx'])) / 2.0
        lb['ko231'] = [(
            _decimate([(lb['x'] + px, lb['y'] + py)
                       for (px, py) in path], 0.10),
            _half231 + wid * 0.55) for path in lb['paths']]
        if border_walls > 0:
            for _k231 in range(border_walls):
                _in231 = wid / 2.0 + border_gap + _k231 * wid
                _bp231 = _lb_contour(lb, _in231)
                if _bp231 is None:
                    _bp231 = _rect_loop(lb['x'] + _in231, lb['y'] + _in231,
                                        lb['x'] + lb['w'] - _in231,
                                        lb['y'] + lb['h'] - _in231)
                lb['ko231'].append((_bp231, wid * 0.85))

    # ---- extrusion constants ---------------------------------------------------------------------------------------------
    twid = max(0.4, nozzle * 1.02)         # one text extrusion line
    # R83 anti-merge: the effective stroke never exceeds cap/5 (>= 1 line)
    _capmax79 = max(lb['cap_h'] for lb in labels)
    if not jobs:
        for lb in labels:
            lb['stroke_eff'] = round(min(stroke_w, max(twid, 0.34 * _capmax79)), 2)
    stroke_eff = max(lb['stroke_eff'] for lb in labels)
    fil = FIL_AREA
    # R214 (.136m, field wish): the FIRST text layer prints INSIDE the last
    # base layer - the letter contours are embedded in the base plastic
    # (they stay readable even if the raised layers above chip off). The
    # overall height is the naive sum MINUS one layer; the settings
    # (base/text layer counts) stay exactly as they are.
    # R231: text_layers is the TOTAL text depth now (2 = flush inlay:
    # contour layer inside the base + top layer), so the file height is
    # base + RAISED layers (text_layers - 2), not base + text_layers - 1.
    total_layers = base_layers + raised_t231
    # R170: with the handle ON THE PLATE the file grows to the handle's
    # height - the labels finish earlier, the layers above hold only the
    # handle (printed last, nothing to rip off)
    _total170 = max(total_layers, _hl170) if _hplate170 else total_layers
    ztop = first_h + (base_layers - 1) * layer_h
    # R120 ring layers: height capped at the label's TOTAL height (never
    # above it); default = flush with the base top (never touches the text)
    # R214: the overlap shortens the total height by one layer - the ring
    # cap follows (still ends one layer below the label's top)
    _ztot120 = ztop + (text_layers - 1) * layer_h
    _rhm120 = (ztop if ring_h <= 0
               else min(float(ring_h), _ztot120 - layer_h))
    _rl120 = max(1, int(math.floor((_rhm120 - first_h) / layer_h)) + 1) \
        if _rhm120 >= first_h else 1
    _rl120 = min(_rl120, base_layers + text_layers - 1)

    L = []
    a = L.append
    a('; R2-LABELS generated label plate (R63/R73) - start it like any other file')
    a('; R73 typography: caps 66% of the label height, small signs 66% of that,')
    a(';           text ~75% of the label width, one cell per character, baseline aligned')
    a(TAG)
    a('; labels: %d (%s)' % (n, ' | '.join(t['text'] for t in labels)))
    if jobs:
        a('; R116 per-job settings (snapshot at Add time): %s'
          % ' | '.join('%s %.0fx%.0fmm%s' % (jb['font'], jb['w'], jb['h'],
                                              ' (grown)' if jb['grown'] else '')
                      for jb in jobs))
        a('; %d layers @ %.2gmm (first %.2gmm), text %d layer(s), font + size PER JOB'
          % (base_layers, layer_h, first_h, text_layers))
    else:
        a('; base %.0fx%.0fmm, %d layers @ %.2gmm (first %.2gmm), text %d layer(s), font %s'
          % (w, h, base_layers, layer_h, first_h, text_layers, font))
    a('; R231 text inlay: contours burned into the %s layer, flush fills'
      ' in the top layer%s - total height = %d layers'
      % ('bottom' if base_layers == 2 else 'solid-infill',
         (', +%d raised layer(s)' % raised_t231) if raised_t231 else '',
         total_layers))
    a('; R74 text: font size %s, letter spacing +%.1fmm, up to 5 lines per label, uniform scale'
      % ('auto' if not font_size else '%.1fmm caps' % font_size, spacing))
    if stroke_eff < stroke_w - 0.01:
        a('; R83 stroke %.2fmm (capped from %.2fmm: cap/5 anti-merge limit)'
          % (stroke_eff, stroke_w))
    hs = ('NONE', 'LEFT', 'RIGHT', 'TOP', 'BOTTOM')[hole_side]
    if ring:
        a('; hole: external RING on the %s side (no in-label hole), ironing %s,'
          ' brim %s, purge tower %s, 2nd color (M600) %s'
          % (hs, 'ON' if ironing else 'OFF', 'ON' if brim else 'OFF',
             'ON' if tower else 'OFF', 'ON' if color2 else 'OFF'))
    else:
        a('; hole: %s%s at 2mm from the edge%s, ironing %s, brim %s, purge tower %s, 2nd color (M600) %s'
          % (hs, (' d=%.1fmm' % labels[0]['hole_d']) if labels[0]['hole_d'] else '',
             '' if not border_walls else ' - INSIDE the border (the border stays closed)',
             'ON' if ironing else 'OFF', 'ON' if brim else 'OFF',
             'ON' if tower else 'OFF', 'ON' if color2 else 'OFF'))
    if ring:
        a('; R120: external hanging RING on the %s side - d=%.1fmm hole, %.1fmm'
          ' band, %d layer(s) (%.1fmm, capped below the label height), from'
          ' layer 1 in the BASE color'
          % (('NONE', 'LEFT', 'RIGHT', 'TOP', 'BOTTOM')[hole_side],
             2.0 * ring_ri, ring_wt, _rl120, _rhm120))
    if shape != 'RECT' or border_walls > 0 or sparse_mid > 0 or height > 0:
        # R119: shape / height / border summary (one line, only when used)
        a('; R119: shape %s%s, base %d layers (%.1fmm)%s, border %d wall(s)%s'
          % (shape, (' corner %.1fmm' % corner) if shape == 'ROUND' else '',
             base_layers, first_h + (base_layers - 1) * layer_h,
             (' = 4 bottom + 4 top solid + %d sparse (%.0f%%)'
              % (sparse_mid, min(max(float(sparse_pct or 8.0), 5.0), 15.0)))
             if sparse_mid else '',
             border_walls, (', %.1fmm off the edge' % border_gap)
             if border_gap else ''))
    if jobs:
        a('; layout: %d labels shelf-packed %0.0fx%0.0fmm (mixed sizes, reading order)'
          % (n, gw, gh))
    else:
        a('; layout: %dx%d grid %0.0fx%0.0fmm, %d of max %d labels fit the bed'
          % (cols, rows, gw, gh, n, cols * rows))
    # R231: the text model line - what 'text layers' means in THIS file
    if flip:
        a('; R231 FLIP: printed text-face-down - the buildplate finish '
          'lands on the letter surface, the text reads correct off the bed')
        if color2:
            a('; R231 FLIP + 2 colors: LOAD THE TEXT COLOR FIRST - the '
              'file starts with the text, one M600 to the plate color '
              'right after the text face')
    else:
        a('; R231 inlay: text %d layer(s) deep in the label - glyph '
          'contours in the solid-infill layer, flush letter fills in the '
          'top layer%s'
          % (text_layers,
             (' + %d raised layer(s) on top' % raised_t231)
             if raised_t231 else ''))
    # slicer-style config comments -> _FILE_INFO (Pre-Print shows these)
    a('; filament_type = %s' % material)
    a('; layer_height = %.2g' % layer_h)
    a('; nozzle_diameter = %.1f' % nozzle)
    a('; line_width = %.2g' % wid)
    a('; outer_wall_line_width = %.2g' % wid)
    a('; outer_wall_speed = 40')
    a('; inner_wall_speed = 45')
    a('; top_surface_speed = 40')
    a('; internal_solid_infill_speed = 55')
    a('; initial_layer_speed = 25')
    a('; travel_speed = 150')
    if ironing:
        a('; ironing_speed = 30')
        a('; ironing_flow = 0.15')
        a('; ironing_spacing = 0.45')
    a('; wall_loops = 2')
    # R73: the file info line goes in DIRECTLY (no re-parse through process()
    # - half the generation time on slow hosts; the TAG above makes the scan skip)
    # R197 (.135): TYPES= stays HONEST under clamping - base_layers < 3
    # has no mid layers, so no INFILL-SOLID is ever printed (the sweep
    # caught the clamped base_layers=-3 claiming a feature that never
    # appears; same class as the .134 brim gap: a TYPES= entry with no
    # material enables LCD rows that can do nothing)
    types = ['WALL-OUTER', 'WALL-INNER']
    # R231: the glyph contours carry the Internal-solid tag in EVERY
    # inlay now (base_layers 2 = contours in the bottom layer), so
    # INFILL-SOLID is always an honest TYPES entry
    types.append('INFILL-SOLID')
    if sparse_mid > 0:
        # R119: the tall-base sparse band is its own feature
        types.append('SPARSE-INFILL')
    if fit168 is not None:
        # R168: the stamp socket ceiling is a declared bridge
        types += ['BRIDGE', 'INTERNAL-BRIDGE']
    if tower:
        # R194 (.135): the purge tower is tagged PRIME-TOWER now
        types.append('PRIME-TOWER')
    # R287: Layer 1 is the BOTTOM surface (standard slicer first layer).
    # The rule is the SEQUENCE: after this one bottom layer come solid
    # infill layers - never a SECOND bottom. Top surface closes the print.
    types.append('SURFACE-BOTTOM')
    if brim:
        types.insert(0, 'BRIM')
    if ironing:
        types += ['SURFACE-TOP', 'IRONING']
    else:
        types += ['SURFACE-TOP']
    if _hplate170:
        _hpos_txt = ', '.join('(%.0f,%.0f)' % h for h in _hpos170)
        a('; R170: handle(s) ON THE PLATE at %s - printed LAST on'
          ' every layer (%d layers, the file tops out at the handle)'
          % (_hpos_txt, _hl170))
    a('_FILE_INFO MATERIAL=%s LAYER_HEIGHT=%.2g TOTAL_LAYERS=%d LINE_WIDTH=%.2g '
      'LINE_WIDTH_FIRST=%.2g LINE_WIDTH_WALL=%.2g FLOW_RATIO=1 NOZZLE=%.1f '
      'WALL_LOOPS=2 SPEED_OUTER=40 SPEED_FIRST=25 SPEED_TRAVEL=150%s TYPES=%s BY_OBJECT=0'
      % (material, layer_h, _total170, wid, first_h, wid,
         nozzle, ' IRONING_SPEED=30' if ironing else '', ','.join(types)))

    # object definitions (polygons without whitespace - Klipper requirement)
    for lb in labels:
        if lb.get('ring_c'):
            # R120: rect bbox over label + ring (exclude keeps working)
            _ex0 = min(lb['x'], lb['ring_c'][0] - lb['ring_ro'])
            _ey0 = min(lb['y'], lb['ring_c'][1] - lb['ring_ro'])
            _ex1 = max(lb['x'] + lb['w'], lb['ring_c'][0] + lb['ring_ro'])
            _ey1 = max(lb['y'] + lb['h'], lb['ring_c'][1] + lb['ring_ro'])
            poly = ('[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]'
                    % (_ex0, _ey0, _ex1, _ey0, _ex1, _ey1, _ex0, _ey1))
            a('EXCLUDE_OBJECT_DEFINE NAME=%s CENTER=%.1f,%.1f POLYGON=%s'
              % (lb['name'], (_ex0 + _ex1) / 2.0, (_ey0 + _ey1) / 2.0, poly))
            continue
        _oc119 = _lb_contour(lb, 0.0)
        if _oc119 is not None:
            # R119: OVAL/ROUND - the exclude polygon IS the outline
            poly = '[' + ','.join('[%.1f,%.1f]' % (px, py)
                                  for (px, py) in _oc119) + ']'
        else:
            poly = '[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]' % (
                lb['x'], lb['y'], lb['x'] + lb['w'], lb['y'],
                lb['x'] + lb['w'], lb['y'] + lb['h'], lb['x'], lb['y'] + lb['h'])
        a('EXCLUDE_OBJECT_DEFINE NAME=%s CENTER=%.1f,%.1f POLYGON=%s'
          % (lb['name'], lb['x'] + lb['w'] / 2.0, lb['y'] + lb['h'] / 2.0, poly))
    if tower:
        poly = '[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]' % (
            tower[0], tower[1], tower[0] + tw, tower[1],
            tower[0] + tw, tower[1] + tw, tower[0], tower[1] + tw)
        a('EXCLUDE_OBJECT_DEFINE NAME=PURGE_TOWER CENTER=%.1f,%.1f POLYGON=%s'
          % (tower[0] + tw / 2.0, tower[1] + tw / 2.0, poly))
    if _hplate170:
        _hr170 = fit168.GRIP_R + 2.5
        # R286: one GRIFF object covering ALL handles (a bounding rect
        # around every placed handle - the LCD shows the whole group).
        _gx0 = min(h[0] for h in _hpos170) - _hr170
        _gy0 = min(h[1] for h in _hpos170) - _hr170
        _gx1 = max(h[0] for h in _hpos170) + _hr170
        _gy1 = max(h[1] for h in _hpos170) + _hr170
        poly = '[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]' % (
            _gx0, _gy0, _gx1, _gy0, _gx1, _gy1, _gx0, _gy1)
        a('EXCLUDE_OBJECT_DEFINE NAME=GRIFF CENTER=%.1f,%.1f POLYGON=%s'
          % ((_gx0 + _gx1) / 2.0, (_gy0 + _gy1) / 2.0, poly))
    ps = 'PRINT_START MATERIAL=%s LAYER_HEIGHT=%.2g TOTAL_LAYERS=%d OUTER_WALL_SPEED=40' % (
        material, layer_h, _total170)
    if ironing:
        ps += ' IRONING_SPEED=30'
    a(ps)
    a('G90')
    a('M83')
    a('M107   ; R2-LABELS: first layer = fan off')

    pen = _Pen(L, jump_d=6.0)   # R77: no retracts between neighboring hatch lines
    # R95 (field log .74, rule dd): the label holes stay OPEN through every
    # layer - travels across them retract at ANY length now
    pen.holes = [(lb['circ'][0] + lb['x'], lb['circ'][1] + lb['y'], lb['circ'][2])
                 for lb in labels if lb['circ']]
    # R120: the ring hole is a travel keep-out too (retract when crossed)
    pen.holes += [(lb['ring_c'][0], lb['ring_c'][1], lb['ring_ri'])
                  for lb in labels if lb.get('ring_c')]
    # R119 sparse band spacing (frames style, 8% default)
    _spc_lab = wid * 100.0 / max(5.0, min(float(sparse_pct or 8.0), 15.0))

    def base_block(lb, z, layer_idx, first, top, lo=None, clip231=False):
        """one label's base layer: brim + perimeters + hole + fill (+ironing).
        R119: OVAL/ROUND contours replace the rect loops (brim via polygon
        offset, fills via convex-contour hatch); bases thicker than 6 layers
        print 4 bottom + 4 top SOLID with sparse infill between (frames).
        R231: lo = the LOGICAL layer (differs from the print index in FLIP
        mode); clip231 keeps the fill/ironing clear of the inlaid text
        bands + border (the top layer prints AROUND them)."""
        lx, ly, w, h = lb['x'], lb['y'], lb['w'], lb['h']
        x0, y0 = lx + wid / 2.0, ly + wid / 2.0
        x1, y1 = lx + w - wid / 2.0, ly + h - wid / 2.0
        e_wall = layer_h_eff(layer_idx) * wid / fil
        sparse_l = (sparse_mid > 0 and bot_solid < layer_idx
                    <= base_layers - top_solid)
        L.append('EXCLUDE_OBJECT_START NAME=%s' % lb['name'])
        if first and brim:
            L.append(';TYPE:Brim')
            # R183 (.131b field log): the old innermost loop sat at
            # wid*0.35 from the label edge - the wall centerline runs at
            # wid/2 and its ink reaches right TO the edge, so the brim
            # printed fused with the object (the user had to fight it off
            # even at 92% flow). The first brim line now keeps a real AIR
            # GAP to the wall ink - the brim grips, but breaks off clean.
            _bgap183 = wid + 0.35
            edge_c = _lb_contour(lb, 0.0)
            for off in (_bgap183 + 2 * wid, _bgap183 + wid, _bgap183):
                if edge_c is None:
                    b = (lx - off, ly - off, lx + w + off, ly + h + off)
                    _emit_loop(pen, _rect_loop(*b), e_wall, 1500 if first else 2400)
                else:
                    _emit_loop(pen, _poly_offset(edge_c, off), e_wall,
                               1500 if first else 2400)
        L.append(';TYPE:Outer wall')
        oc = _lb_contour(lb, wid / 2.0)
        if oc is None:
            _emit_loop(pen, _rect_loop(x0, y0, x1, y1), e_wall, 1500 if first else 2400)
        else:
            _emit_loop(pen, oc, e_wall, 1500 if first else 2400)
        L.append(';TYPE:Inner wall')
        ic = _lb_contour(lb, 1.5 * wid)
        if ic is None:
            _emit_loop(pen, _rect_loop(x0 + wid, y0 + wid, x1 - wid, y1 - wid), e_wall,
                       1500 if first else 2700)
        else:
            _emit_loop(pen, ic, e_wall, 1500 if first else 2700)
        if lb['circ']:
            cx, cy, r = lb['circ']
            cx += lx
            cy += ly
            L.append(';TYPE:Outer wall')
            _emit_loop(pen, _circle(cx, cy, r + wid / 2.0), e_wall, 1500 if first else 2400)
            _emit_loop(pen, _circle(cx, cy, r + 1.5 * wid), e_wall, 1500 if first else 2700)
        ix0, iy0 = lx + 2.0 * wid + 0.1, ly + 2.0 * wid + 0.1
        ix1, iy1 = lx + w - 2.0 * wid - 0.1, ly + h - 2.0 * wid - 0.1
        keep = None
        if lb['circ']:
            keep = (lb['circ'][0] + lx, lb['circ'][1] + ly, lb['circ'][2] + 2.0 * wid)
        # ---- R168: the stamp socket under this label ------------------
        # R286: the socket sits under THIS label's text (per-label center,
        # not one global center) - every stamp label in the job gets its
        # own socket.
        if fit168 is not None:
            _sx168 = lb['x'] + lb['w'] / 2.0
            _sy168 = lb['y'] + lb['h'] / 2.0
            _zb168 = z - layer_h_eff(layer_idx)
            _r168 = (fit168.sock_r(min(z, fit168.d5 - 1e-9))
                     if _zb168 < fit168.d5 else None)
            _ceil168 = _zb168 < fit168.d5 <= z
            if _r168 is not None:
                L.append(';TYPE:Outer wall')
                L.append('APPLY_TYPE TYPE=WALL-OUTER   ; R168 socket ring')
                _emit_loop(pen, _circle(_sx168, _sy168,
                                        _r168 + wid / 2.0),
                           e_wall, 1500 if first else 2400)
                keep = (_sx168, _sy168, _r168 + wid + 0.2)
            if _ceil168:
                L.append(';TYPE:Bridge')
                L.append('APPLY_TYPE TYPE=BRIDGE   ; R168 socket ceiling')
                _rb168 = fit168.r_ce + wid * 0.5
                _n168 = max(6, int((2.0 * _rb168) / max(wid, 0.4)))
                for _k168 in range(_n168 + 1):
                    _off168 = -_rb168 + (2.0 * _rb168) * _k168 / _n168
                    _hh168 = math.sqrt(max(0.0, _rb168 * _rb168
                                           - _off168 * _off168))
                    pen.travel(_sx168 - _hh168, _sy168 + _off168, 4800)
                    pen.extrude(_sx168 + _hh168, _sy168 + _off168,
                                2.0 * _hh168 * e_wall, 1300)
                L.append(';TYPE:Internal bridge')
                L.append('APPLY_TYPE TYPE=INTERNAL-BRIDGE')
                _emit_loop(pen, _circle(_sx168, _sy168,
                                        fit168.r_ce + wid / 2.0),
                           e_wall, 1200)
            if _zb168 >= fit168.d5:
                sparse_l = False     # solid above the closed ceiling
            if _r168 is not None:
                pen.holes = [(_sx168, _sy168, _r168)]
            else:
                pen.holes = []
        # R106 (user TYPE map): first fill on the bed = Bottom surface,
        # the visible top = Top surface, between = Internal solid;
        # R119: the sparse band between the solid skins = Sparse infill
        # R231: in FLIP mode lo (the logical layer) drives the surface
        # names - the label's own top stays 'Top surface' wherever it
        # physically prints (the flip is explicit, the user tunes the face)
        if lo is not None:
            sparse_l = (sparse_mid > 0 and bot_solid < lo
                        <= base_layers - top_solid)
            if lo == 1:
                ftype = 'Bottom surface'
            elif lo == base_layers:
                ftype = 'Top surface'
            elif sparse_l:
                ftype = 'Sparse infill'
            else:
                ftype = 'Internal solid infill'
        elif first:
            ftype = 'Bottom surface'
        elif top:
            ftype = 'Top surface'
        elif sparse_l:
            ftype = 'Sparse infill'
        else:
            ftype = 'Internal solid infill'
        L.append(';TYPE:%s' % ftype)
        fspc = _spc_lab if sparse_l else wid
        fc = _lb_contour(lb, 2.0 * wid + 0.1)
        if fc is None:
            segs = _hatch(ix0, iy0, ix1, iy1, keep, fspc,
                          45.0 if layer_idx % 2 else 135.0)
        else:
            segs = _shape_hatch(fc, fspc, 45.0 if layer_idx % 2 else 135.0, keep)
        if clip231:
            segs = _segs_clear_of(segs, lb['ko231'])
        _emit_fill(pen, segs, e_wall, 1500 if first else 2700, fspc)
        if fit168 is not None:
            pen.holes = []
        if top and ironing:
            L.append(';TYPE:Ironing')
            ikeep = None
            if lb['circ']:
                ikeep = (lb['circ'][0] + lx, lb['circ'][1] + ly, lb['circ'][2] + 0.4)
            # R117: ironing follows the TOP fill angle (same direction =
            # flattens the same ridges it just printed) and chains its lines
            ic2 = _lb_contour(lb, 1.0)
            if ic2 is None:
                isegs = _hatch(lx + 1.0, ly + 1.0, lx + w - 1.0, ly + h - 1.0, ikeep,
                               0.45, 45.0 if layer_idx % 2 else 135.0, min_len=0.3)
            else:
                isegs = _shape_hatch(ic2, 0.45, 45.0 if layer_idx % 2 else 135.0,
                                     ikeep, min_len=0.3)
            if clip231:
                isegs = _segs_clear_of(isegs, lb['ko231'])
            ei = layer_h_eff(layer_idx) * wid * 0.15 / fil
            _emit_fill(pen, isegs, ei, 1800, 0.45)
        L.append('EXCLUDE_OBJECT_END NAME=%s' % lb['name'])

    def layer_h_eff(layer_idx):
        return first_h if layer_idx == 1 else layer_h

    def tower_block(z, layer_idx, first, prime=False):
        x0, y0 = tower[0] + wid / 2.0, tower[1] + wid / 2.0
        x1, y1 = tower[0] + tw - wid / 2.0, tower[1] + tw - wid / 2.0
        e_wall = layer_h_eff(layer_idx) * wid / fil
        L.append('EXCLUDE_OBJECT_START NAME=PURGE_TOWER')
        # R194 (.135, user request): the purge tower is TAGGED as what it
        # is - PRIME-TOWER, one feature for the whole body (R73 lesson:
        # few APPLY_TYPE boundaries, and per-feature speed tuning of a
        # disposable tower is meaningless). The brim keeps its own BRIM
        # tag (it IS a brim), so TYPES= gains PRIME-TOWER and the LCD
        # prime-tower row enables. No manual APPLY_TYPE here - the R73
        # pass below derives it from every ;TYPE: line (doubling it up
        # would push two live markers per boundary).
        L.append(';TYPE:Prime tower')
        if prime:
            # after the filament change: push the new color and wipe on the tower
            pen.travel(tower[0] + 1.5, tower[1] + tw - 1.5)
            pen.push(4.0, 180)
            pen.extrude(tower[0] + tw - 1.5, tower[1] + tw - 1.5, 3.0 * 0.1, 1320)
            pen.extrude(tower[0] + 1.5, tower[1] + tw - 1.5, (tw - 3.0) * 0.1, 1320)
        if first and brim:
            L.append(';TYPE:Brim')
            L.append('APPLY_TYPE TYPE=BRIM')
            for off in (_brim_gap(wid) + wid, _brim_gap(wid)):
                b = (tower[0] - off, tower[1] - off, tower[0] + tw + off, tower[1] + tw + off)
                _emit_loop(pen, _rect_loop(*b), e_wall, 1500)
            L.append(';TYPE:Prime tower')
        _emit_loop(pen, _rect_loop(x0, y0, x1, y1), e_wall, 1500 if first else 2400)
        _emit_loop(pen, _rect_loop(x0 + wid, y0 + wid, x1 - wid, y1 - wid), e_wall,
                   1500 if first else 2700)
        segs = _hatch(x0 + wid + 0.1, y0 + wid + 0.1, x1 - wid - 0.1, y1 - wid - 0.1,
                      None, wid, 45.0 if layer_idx % 2 else 135.0)
        _emit_fill(pen, segs, e_wall, 1500 if first else 2700, wid)
        L.append('EXCLUDE_OBJECT_END NAME=PURGE_TOWER')

    def text_block(lb, z, layer_idx, tag='Outer wall'):
        """the label's text (R74 line typography) - SOLID double-walled
        strokes (R72: single lines broke off when scratched). Each skeleton
        becomes a bundle of parallel lines +half..-half: the outermost two
        are the walls, the lines between them the fill, printed serpentine.
        R73: ONE feature for the whole text (the .56 file switched
        wall/fill per stroke line -> hundreds of APPLY_TYPE calls -> host/MCU
        overload), decimated vertices, calmer feeds.
        R74: the stroke bundles print NEAREST-FIRST - reading order added a
        travel across the whole word before every glyph.
        R231: tag - 'Internal solid infill' for the contour layer burned
        into the solid-infill layer (plate color), 'Top surface' for the
        flush inlay in the top layer, 'Outer wall' for raised text."""
        e_txt = layer_h_eff(layer_idx) * twid / fil
        # stroke width: user value (LCD 'Stroke'), auto = 3 extrusion lines;
        # capped by the letter pitch so condensed glyphs keep open counters,
        # and R83 by the cap height (stroke <= cap/5) - 0.8mm strokes on
        # 3.4mm caps printed letters grown together (field log .65)
        half = min(lb['stroke_eff'], max(2.0 * twid, 2.1 * lb['sx'])) / 2.0
        L.append('EXCLUDE_OBJECT_START NAME=%s' % lb['name'])
        # R106 (user TYPE map): the raised text IS the visible surface -
        # its strokes print as Outer wall (outer-wall speed/overrides apply)
        L.append(';TYPE:%s' % tag)
        bundles = []
        for pts in lb['paths']:
            pts = _decimate([(lb['x'] + px, lb['y'] + py) for (px, py) in pts], 0.10)
            if len(pts) >= 2:
                bundles.append(pts)
        while bundles:
            if pen.x is None:
                k = 0
            else:
                k = min(range(len(bundles)),
                        key=lambda i: (bundles[i][0][0] - pen.x) ** 2
                        + (bundles[i][0][1] - pen.y) ** 2)
            pts = bundles.pop(k)
            offs = _stroke_offsets(pts, half, twid)
            for k2, path in enumerate(offs):
                if k2 % 2:
                    path = list(reversed(path))
                # R83: glyph-to-glyph travel (k2 == 0) retracts + hops from
                # 1.2mm - letters must stay discrete, no ooze ghost lines
                pen.travel(path[0][0], path[0][1], feed=4500, hop=(k2 == 0),
                           force_d=(1.2 if k2 == 0 else None))
                px, py = path[0]
                for (x, y) in path[1:]:
                    d = math.hypot(x - px, y - py)
                    if d < 0.05:
                        continue
                    pen.extrude(x, y, d * e_txt, 1200)
                    px, py = x, y
        L.append('EXCLUDE_OBJECT_END NAME=%s' % lb['name'])

    def border_block(lb, layer_idx):
        """R119: the raised border ring - prints ON THE TEXT LAYERS (same
        start as the text, same color: the M600 swap sits right before the
        first text layer). Flush with the base edge by default (loop 0 runs
        exactly on the base outer wall); border_gap moves the whole ring
        inward. The loops BREAK at the label hole - nothing bridges over the
        open hole, the hole rings wall it in the raised layer too."""
        if border_walls <= 0:
            return
        e_wall = layer_h_eff(layer_idx) * wid / fil
        L.append('EXCLUDE_OBJECT_START NAME=%s' % lb['name'])
        hole = None
        if lb['circ']:
            hole = (lb['circ'][0] + lb['x'], lb['circ'][1] + lb['y'], lb['circ'][2])
        for k in range(border_walls):
            inset = wid / 2.0 + border_gap + k * wid
            L.append(';TYPE:%s' % ('Outer wall' if k == 0 else 'Inner wall'))
            pts = _lb_contour(lb, inset)
            if pts is None:
                pts = _rect_loop(lb['x'] + inset, lb['y'] + inset,
                                 lb['x'] + lb['w'] - inset,
                                 lb['y'] + lb['h'] - inset)
            if hole:
                rk = hole[2] + wid / 2.0
                pieces = []
                for i in range(len(pts)):
                    pieces.extend(_seg_outside_circle(
                        pts[i], pts[(i + 1) % len(pts)], hole[0], hole[1], rk))
                runs = []
                for (a, b) in pieces:
                    if runs and abs(runs[-1][-1][0] - a[0]) < 0.02 \
                            and abs(runs[-1][-1][1] - a[1]) < 0.02:
                        runs[-1].append(b)
                    else:
                        runs.append([a, b])
                for run in runs:
                    pen.travel(run[0][0], run[0][1], hop=False)
                    px, py = run[0]
                    for (x, y) in run[1:]:
                        d = math.hypot(x - px, y - py)
                        if d < 0.05:
                            continue
                        pen.extrude(x, y, d * e_wall, 1200)
                        px, py = x, y
            else:
                _emit_loop(pen, pts, e_wall, 1200)
        if hole:
            L.append(';TYPE:Outer wall')
            _emit_loop(pen, _circle(hole[0], hole[1], hole[2] + wid / 2.0),
                       e_wall, 1200)
            _emit_loop(pen, _circle(hole[0], hole[1], hole[2] + 1.5 * wid),
                       e_wall, 1200)
        L.append('EXCLUDE_OBJECT_END NAME=%s' % lb['name'])

    def ring_block(lb, layer_idx, first):
        """R120: the external hanging ring - an annulus flush against the
        label edge, from LAYER 1 (printed with the base color), height capped
        below the label's total height. Three adjacent wall lines = a solid
        3-perimeter band; brim on layer 1 like the label itself."""
        if not lb.get('ring_c'):
            return
        cx, cy = lb['ring_c']
        e_wall = layer_h_eff(layer_idx) * wid / fil
        L.append('EXCLUDE_OBJECT_START NAME=%s' % lb['name'])
        if first and brim:
            L.append(';TYPE:Brim')
            for off in (_brim_gap(wid) + wid, _brim_gap(wid)):
                _emit_loop(pen, _circle(cx, cy, lb['ring_ro'] + off), e_wall, 1500)
        L.append(';TYPE:Outer wall')
        _emit_loop(pen, _circle(cx, cy, lb['ring_ro'] - wid / 2.0), e_wall,
                   1500 if first else 2400)
        L.append(';TYPE:Inner wall')
        _emit_loop(pen, _circle(cx, cy, lb['ring_ro'] - 1.5 * wid), e_wall,
                   1500 if first else 2700)
        _emit_loop(pen, _circle(cx, cy, lb['ring_ri'] + wid / 2.0), e_wall,
                   1500 if first else 2700)
        L.append('EXCLUDE_OBJECT_END NAME=%s' % lb['name'])

    # ---- R231 layer plan ----------------------------------------------------
    # NORMAL: base layers 1..B (the B-1 layer burns the glyph CONTOURS into
    # the solid infill - plate color, R214 spirit; the B layer prints the
    # top fill AROUND the text bands, then ONE M600, then the flush text
    # fills + border in color B), then the raised layers B+1.. on top.
    # FLIP: the same logical stack printed upside down (B+R first, 1 last):
    # the text face lies on the buildplate and carries its finish, the
    # file STARTS in the text color and swaps to the plate color once.
    # R74: label order alternates per layer (serpentine) - layer N ends at
    # the last label, layer N+1 starts right there instead of travelling back.
    _NT231 = base_layers + raised_t231

    def _layer_head(p):
        z = round(first_h + (p - 1) * layer_h, 3)
        L.append(';LAYER_CHANGE')
        L.append(';Z:%.3f' % z)
        pen.set_z(z)
        if p == 2:
            L.append('M106 S178   ; R2-LABELS: part fan from layer 2')
        return z, (labels if p % 2 else list(reversed(labels)))

    if not flip:
        for li in range(1, base_layers + 1):
            z, order = _layer_head(li)
            top = (li == base_layers)
            for lb in order:
                base_block(lb, z, li, li == 1, top, lo=li, clip231=top)
                if li <= _rl120:
                    ring_block(lb, li, li == 1)
            if tower:
                tower_block(z, li, li == 1)
            if _hplate170 and li <= _hl170:
                handle_block(z, li)      # R170: the handle prints LAST
            if li == base_layers - 1 and text_layers >= 2:
                # R231: the text's FIRST inlay layer - the glyph contours
                # burned into the solid-infill layer below the surface,
                # PLATE color, no swap: the letters stay readable even if
                # the flush layer chips (R214 lesson, one layer deeper)
                for lb in order:
                    text_block(lb, z, li, tag='Internal solid infill')
            if li == base_layers and text_layers >= 2:
                # R231: 'zuerst Label-Flaeche, DANN Buchstaben + Rand' -
                # the top fill ran clipped AROUND the bands (base_block),
                # one M600, then the letter fills + border (color B).
                if color2:
                    a('; R2-LABELS: top layer done - PAUSE for the '
                      'filament change (text color)')
                    a('; swap filament, then RESUME - the purge tower '
                      'primes the new color')
                    a('M600')
                if tower:
                    tower_block(z, li, False, prime=True)
                for lb in order:
                    text_block(lb, z, li, tag='Top surface')
                    border_block(lb, li)
        # ---- raised text layers (text_layers 3/4: 'addieren auf Hoehe') ----
        for li in range(base_layers + 1, _NT231 + 1):
            z, order = _layer_head(li)
            if tower:
                tower_block(z, li, False, prime=False)
            for lb in order:
                text_block(lb, z, li, tag='Outer wall')
                border_block(lb, li)
            if _hplate170 and li <= _hl170:
                handle_block(z, li)      # R170: the handle prints LAST
    else:
        # FLIP: logical layer lo = _NT231+1-p (the model stands on its
        # text face); every block keeps its LOGICAL surface type
        for p in range(1, _NT231 + 1):
            lo = _NT231 + 1 - p
            z, order = _layer_head(p)
            first = (p == 1)
            if lo >= base_layers + 1:
                # raised text islands on the bed - TEXT color (flip starts
                # in the text color, the swap comes after the whole face)
                for lb in order:
                    text_block(lb, z, p, tag='Outer wall')
                    border_block(lb, p)
            elif lo == base_layers:
                # the label's TOP FACE: letters + border first (text
                # color), then ONE M600, then walls + the clipped fill
                # around them (plate color)
                for lb in order:
                    text_block(lb, z, p, tag='Top surface')
                    border_block(lb, p)
                if color2:
                    a('; R2-LABELS: text face done - PAUSE for the '
                      'filament change (plate color)')
                    a('; swap filament, then RESUME - the purge tower '
                      'primes the new color')
                    a('M600')
                if tower:
                    tower_block(z, p, False, prime=True)
                for lb in order:
                    base_block(lb, z, p, first, False, lo=lo, clip231=True)
            elif lo == base_layers - 1:
                # the contour layer right behind the face
                for lb in order:
                    base_block(lb, z, p, first, False, lo=lo, clip231=False)
                    text_block(lb, z, p, tag='Internal solid infill')
                if tower:
                    tower_block(z, p, first)
            else:
                for lb in order:
                    base_block(lb, z, p, first, lo == 1, lo=lo)
                    if lo <= _rl120:
                        ring_block(lb, p, first)
                if tower:
                    tower_block(z, p, first)
            if _hplate170 and p <= _hl170:
                handle_block(z, p)      # unreachable in flip (stamp-only)

    # R170: handle-only layers above the label tops (nothing else lives up
    # here - the travels are safely above the finished labels)
    if _hplate170 and _hl170 > total_layers:
        for li in range(total_layers + 1, _hl170 + 1):
            z = round(first_h + (li - 1) * layer_h, 3)
            L.append(';LAYER_CHANGE')
            L.append(';Z:%.3f' % z)
            pen.set_z(z)
            handle_block(z, li)

    a('M107')
    a('PRINT_END')

    # R73: inject the R2 markers directly (LAYER_MARK after every layer change,
    # APPLY_TYPE after every ;TYPE:) - no re-parse through process()
    outl = []
    for l in L:
        outl.append(l)
        ls = l.strip()
        if ls.startswith(';TYPE:'):
            key = ls[6:].strip().lower()
            outl.append('APPLY_TYPE TYPE=%s' % (_lookup_type(key) or 'CUSTOM'))
        elif LAYER_COMMENT.match(ls):
            outl.append('LAYER_MARK')

    # R133f (field log .98): running version, NEVER overwrite - the old
    # 'same text overwrites its file' spec and the gen_version LCD option
    # are gone. Size stays out of the name on purpose (near-duplicates
    # still group); every regeneration gets the next free number.
    # R158 (.118): version FIRST - the LCD cuts file names at ~15
    # characters, a tail version made regenerations look identical.
    first_name = _safe_label_name(texts[0])
    extra = '+%d' % (n - 1) if n > 1 else ''
    if part > 0:
        extra = (extra or '') + '_T%d' % part      # R170: split job part
    fname = 'V%02d_%s%s%s.gcode' % (
        _next_gen_version(out_dir),
        'StempelL_' if fit168 is not None else '', first_name, extra)
    fname = _dedupe_gen_fname(out_dir, fname)
    out = os.path.join(out_dir, fname)
    with open(out, 'w') as f:
        f.write('\n'.join(outl) + '\n')

    _gen_normalize_speeds(out)   # R159: uniform 60/1500 + travel 180/8000
    out_handle168 = None
    if fit168 is not None and handle == 2:      # R170: 2 = own file
        # R286: the standalone handle file prints at the BED CENTER (its
        # own file, no labels on the plate) - _make_stamp_handle defaults.
        out_handle168, _hi168 = _make_stamp_handle(
            fit168, out_dir=out_dir, material=material, nozzle=nozzle,
            wid=wid, layer_h=layer_h, src_stem=first_name)
    info = {'file': fname, 'count': n, 'cols': cols, 'rows': rows,
            'mirror_x': mirror_x, 'mirror_y': mirror_y,
            'flip': bool(flip), 'raised': raised_t231,
            'stamp': bool(fit168 is not None),
            'handle_file': (os.path.basename(out_handle168)
                            if out_handle168 else None),
            'handle_plate': _hplate170,      # R170: handle on the plate
            'handle_pos': ([(round(h[0], 1), round(h[1], 1))
                            for h in _hpos170] if _hpos170 else None),
            'file_layers': _total170,
            'jobs': ([{'font': jb['font'], 'w': round(jb['w'], 1),
                       'h': round(jb['h'], 1), 'grown': jb.get('grown', False)}
                      for jb in jobs] if jobs else None),
            'stroke_eff': stroke_eff, 'stroke_capped': stroke_eff < stroke_w - 0.01,
            'fit': cols * rows, 'grid': '%.0fx%.0f' % (gw, gh),
            'tower': bool(tower), 'layers': total_layers,
            'max_lines': max(len(t['lines']) for t in labels),
            'cap_mm': round(max(lb['cap_h'] for lb in labels), 1),
            'grown': grown79, 'w': round(w, 1), 'h': round(h, 1),
            'height': round(ztop + text_layers * layer_h, 2),
            # R119
            'shape': shape, 'corner': round(corner, 1) if shape == 'ROUND' else 0.0,
            'border': border_walls, 'border_gap': round(border_gap, 1),
            'base_layers': base_layers, 'sparse_mid': sparse_mid,
            'ring': bool(ring), 'ring_h': round(_rhm120, 2),
            'ring_layers': _rl120}
    return out, info


# ======================================================================================
#  R64 INPUT SHAPER MATH - a faithful port of Klipper's shaper_defs.py +
#  shaper_calibrate.py (pure python, no numpy) so the R64 resonance diagram
#  can fit the shapers EXACTLY like Klipper does, even when the CSV comes from
#  TEST_RESONANCES (no shaper table in the file).
# ======================================================================================

SHAPER_VIBRATION_REDUCTION = 20.0
SHAPER_DEFAULT_DAMPING = 0.1
SHAPER_TEST_DAMPINGS = (0.075, 0.1, 0.15)
AUTOTUNE_SHAPERS = ('zv', 'mzv', 'ei', '2hump_ei', '3hump_ei')
SHAPER_MIN_FREQ = {'zv': 21.0, 'mzv': 23.0, 'zvd': 29.0, 'ei': 29.0,
                   '2hump_ei': 39.0, '3hump_ei': 48.0}
SHAPER_MAX_FREQ = 150.0


def _solve_lsq(M, F):
    """least squares A ~= M^-1 F via normal equations (tiny, well conditioned)."""
    n = len(M[0])
    mtm = [[sum(M[r][i] * M[r][j] for r in range(len(M))) for j in range(n)] for i in range(n)]
    mtf = [sum(M[r][i] * F[r] for r in range(len(M))) for i in range(n)]
    aug = [mtm[i][:] + [mtf[i]] for i in range(n)]
    for col in range(n):
        p = max(range(col, n), key=lambda r: abs(aug[r][col]))
        aug[col], aug[p] = aug[p], aug[col]
        pv = aug[col][col]
        for j in range(col, n + 1):
            aug[col][j] /= pv
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                for j in range(col, n + 1):
                    aug[r][j] -= f * aug[col][j]
    return [aug[i][n] for i in range(n)]


_MZV_BASE = None


def _mzv_base_coeffs():
    """Klipper's get_mzv_coeffs(n=3, t=0.75) - solved once (freq independent)."""
    n, t = 3, 0.75
    tau = t * (n - 2.0) / (n - 2.0 * t - 1.0)
    T = [i * t / (n - 1.0) for i in range(n)]
    M = [[1.0] * n]
    F = [1.0]
    for i in range(n - 1):
        W = [2.0 * math.pi * (1.0 + i / tau) * tj for tj in T]
        M.append([math.cos(w) for w in W])
        F.append(0.0)
        M.append([math.sin(w) for w in W])
        F.append(0.0)
    return _solve_lsq(M, F), T


def _shaper_zv(freq, damping):
    df = math.sqrt(1.0 - damping * damping)
    K = math.exp(-damping * math.pi / df)
    t_d = 1.0 / (freq * df)
    return ([1.0, K], [0.0, 0.5 * t_d])


def _shaper_zvd(freq, damping):
    df = math.sqrt(1.0 - damping * damping)
    K = math.exp(-damping * math.pi / df)
    t_d = 1.0 / (freq * df)
    return ([1.0, 2.0 * K, K * K], [0.0, 0.5 * t_d, t_d])


def _shaper_mzv(freq, damping):
    global _MZV_BASE
    if _MZV_BASE is None:
        _MZV_BASE = _mzv_base_coeffs()
    A, T = list(_MZV_BASE[0]), list(_MZV_BASE[1])
    n, t = 3, 0.75
    df = math.sqrt(1.0 - damping * damping)
    K = math.exp(-2.0 * t * damping * math.pi / ((n - 1.0) * df))
    t_d = 1.0 / (freq * df)
    Kp = K
    for i in range(1, n):
        T[i] *= t_d
        A[i] *= Kp
        Kp *= K
    return (A, T)


def _shaper_ei(freq, damping, v_tol=1.0 / SHAPER_VIBRATION_REDUCTION):
    df = math.sqrt(1.0 - damping * damping)
    t_d = 1.0 / (freq * df)
    dr = damping
    a1 = (0.24968 + 0.24961 * v_tol) + ((0.80008 + 1.23328 * v_tol) +
                                         (0.49599 + 3.17316 * v_tol) * dr) * dr
    a3 = (0.25149 + 0.21474 * v_tol) + ((-0.83249 + 1.41498 * v_tol) +
                                         (0.85181 - 4.90094 * v_tol) * dr) * dr
    a2 = 1.0 - a1 - a3
    t2 = 0.4999 + (((0.46159 + 8.57843 * v_tol) * v_tol) +
                   (((4.26169 - 108.644 * v_tol) * v_tol) +
                    ((1.75601 + 336.989 * v_tol) * v_tol) * dr) * dr) * dr
    return ([a1, a2, a3], [0.0, t2 * t_d, t_d])


def _shaper_expansion(freq, damping, t, a):
    tau = 1.0 / freq
    T, A = [], []
    n, k = len(a), len(a[0])
    for i in range(n):
        u, v = t[i][k - 1], a[i][k - 1]
        for j in range(k - 1):
            u = u * damping + t[i][k - j - 2]
            v = v * damping + a[i][k - j - 2]
        T.append(u * tau)
        A.append(v)
    return (A, T)


def _shaper_2hump(freq, damping):
    t = [[0., 0., 0., 0.],
         [0.49890, 0.16270, -0.54262, 6.16180],
         [0.99748, 0.18382, -1.58270, 8.17120],
         [1.49920, -0.09297, -0.28338, 1.85710]]
    a = [[0.16054, 0.76699, 2.26560, -1.22750],
         [0.33911, 0.45081, -2.58080, 1.73650],
         [0.34089, -0.61533, -0.68765, 0.42261],
         [0.15997, -0.60246, 1.00280, -0.93145]]
    return _shaper_expansion(freq, damping, t, a)


def _shaper_3hump(freq, damping):
    t = [[0., 0., 0., 0.],
         [0.49974, 0.23834, 0.44559, 12.4720],
         [0.99849, 0.29808, -2.36460, 23.3990],
         [1.49870, 0.10306, -2.01390, 17.0320],
         [1.99960, -0.28231, 0.61536, 5.40450]]
    a = [[0.11275, 0.76632, 3.29160, -1.44380],
         [0.23698, 0.61164, -2.57850, 4.85220],
         [0.30008, -0.19062, -2.14560, 0.13744],
         [0.23775, -0.73297, 0.46885, -2.08650],
         [0.11244, -0.45439, 0.96382, -1.46000]]
    return _shaper_expansion(freq, damping, t, a)


def _shaper_get(name, freq, damping=SHAPER_DEFAULT_DAMPING):
    name = str(name).lower()
    if name == 'zv':
        return _shaper_zv(freq, damping)
    if name == 'zvd':
        return _shaper_zvd(freq, damping)
    if name == 'mzv':
        return _shaper_mzv(freq, damping)
    if name == 'ei':
        return _shaper_ei(freq, damping)
    if name == '2hump_ei':
        return _shaper_2hump(freq, damping)
    if name == '3hump_ei':
        return _shaper_3hump(freq, damping)
    raise ValueError('unknown shaper %r' % name)


def _shaper_response(A, T, damping, freqs):
    """Klipper's _estimate_shaper: response amplitude per test frequency."""
    inv_D = 1.0 / sum(A)
    t_end = T[-1]
    out = []
    for f in freqs:
        omega = 2.0 * math.pi * f
        damp = damping * omega
        omega_d = omega * math.sqrt(1.0 - damping * damping)
        S = C = 0.0
        for a_i, t_i in zip(A, T):
            w = a_i * math.exp(-damp * (t_end - t_i))
            S += w * math.sin(omega_d * t_i)
            C += w * math.cos(omega_d * t_i)
        out.append(math.sqrt(S * S + C * C) * inv_D)
    return out


def _remaining_vibrations(A, T, damping, freqs, psd):
    vals = _shaper_response(A, T, damping, freqs)
    pmax = max(psd) if psd else 0.0
    thr = pmax / SHAPER_VIBRATION_REDUCTION
    rem = sum(max(v * p - thr, 0.0) for v, p in zip(vals, psd))
    allv = sum(max(p - thr, 0.0) for p in psd)
    return (rem / allv if allv > 0 else 0.0), vals


def _shaper_smoothing(A, T, accel=5000.0, scv=5.0):
    half = accel * 0.5
    inv_D = 1.0 / sum(A)
    ts = sum(a * t for a, t in zip(A, T)) * inv_D
    off90 = off180 = 0.0
    for a_i, t_i in zip(A, T):
        if t_i >= ts:
            off90 += a_i * (scv + half * (t_i - ts)) * (t_i - ts)
        off180 += a_i * half * (t_i - ts) ** 2
    return max(off90 * inv_D * math.sqrt(2.0), off180 * inv_D)


def _shaper_max_accel(A, T, scv):
    """Klipper's find_shaper_max_accel (TARGET_SMOOTHING = 0.12, bisect)."""
    def ok(accel):
        return _shaper_smoothing(A, T, accel, scv) <= 0.12
    left = right = 1.0
    if not ok(1e-9):
        return 0.0
    while not ok(left):
        right = left
        left *= 0.5
    if right == left:
        while ok(right):
            right *= 2.0
    while right - left > 1e-8:
        middle = (left + right) * 0.5
        if ok(middle):
            left = middle
        else:
            right = middle
    return left


def _fit_one_shaper(name, freqs, psd, scv):
    """Klipper's fit_shaper (no max_smoothing limit - the diagram shows all)."""
    freq_start = min(SHAPER_MIN_FREQ[name], SHAPER_MAX_FREQ - 1e-7)
    tf = []
    f = freq_start
    while f < SHAPER_MAX_FREQ:
        tf.append(round(f, 6))
        f += 0.2
    best_res = None
    results = []
    for test_freq in reversed(tf):
        A, T = _shaper_get(name, test_freq)
        smoothing = _shaper_smoothing(A, T, 5000.0, scv)
        max_accel = _shaper_max_accel(A, T, scv)
        vibrs = 0.0
        for dr in SHAPER_TEST_DAMPINGS:
            v, _vals = _remaining_vibrations(A, T, dr, freqs, psd)
            if v > vibrs:
                vibrs = v
        score = smoothing * (vibrs ** 1.5 + vibrs * 0.2 + 0.01)
        res = {'name': name, 'freq': test_freq, 'vibrs': vibrs,
               'smoothing': smoothing, 'score': score, 'max_accel': max_accel}
        results.append(res)
        if best_res is None or best_res['vibrs'] > res['vibrs']:
            best_res = res
    selected = best_res
    for res in reversed(results):
        if res['vibrs'] < best_res['vibrs'] * 1.1 + 0.0005 and res['score'] < selected['score']:
            selected = res
    return selected, results


def _pick_best(table):
    """Klipper's find_best_shaper selection over an already fitted table."""
    best = None
    for s in table:
        if (best is None or s['score'] * 1.2 < best['score']
                or (s['score'] * 1.05 < best['score'] and s['smoothing'] * 1.1 < best['smoothing'])):
            best = s
    if best['name'] == 'zv':
        for s in table:
            if s['name'] != 'zv' and s['vibrs'] * 1.1 < best['vibrs']:
                best = s
                break
    return best


def _fit_shapers(freqs, psd, scv=5.0):
    best = None
    table = []
    for name in AUTOTUNE_SHAPERS:
        sel, _results = _fit_one_shaper(name, freqs, psd, scv)
        if (best is None or sel['score'] * 1.2 < best['score']
                or (sel['score'] * 1.05 < best['score'] and sel['smoothing'] * 1.1 < best['smoothing'])):
            best = sel
        table.append(sel)
    if best['name'] == 'zv':
        for s in table:
            if s['name'] != 'zv' and s['vibrs'] * 1.1 < best['vibrs']:
                best = s
                break
    return best, table


def _normalize_psd(freqs, psd):
    """Klipper's CalibrationData.normalize_to_frequencies (in place copy)."""
    out = []
    for f, p in zip(freqs, psd):
        val = p / (f + 0.1)
        if f < 10.0:                      # 2 * MIN_FREQ low-frequency rolloff
            val *= math.exp(-((10.0 / (f + 0.1)) ** 2) + 1.0)
        out.append(val)
    return out


# ---- resonance CSV discovery + parsing ----------------------------------------

_RESONANCE_RE = re.compile(r'^(calibration_data|calibrated|resonances)[_\-]([xyz])[_\-]', re.I)


def _cfg_val(cfg_path, section, key, default):
    """read one value from a Klipper config ('=' or ':' separated, comments ok)."""
    try:
        with open(cfg_path) as f:
            text = f.read()
    except OSError:
        return default
    sec = None
    for raw in text.split('\n'):
        l = raw.split('#')[0].split(';')[0].strip()
        if not l:
            continue
        if l.startswith('[') and l.endswith(']'):
            sec = l[1:-1].strip().lower()
            continue
        if sec == section:
            m = re.match(r'([^:=]+)[:=](.*)$', l)
            if m and m.group(1).strip().lower() == key:
                return m.group(2).strip()
    return default


def _resonance_csv_dirs(base_dir):
    """candidate dirs holding the resonance CSVs (save_path first)."""
    cfg_dir = os.path.join(base_dir, 'config')
    sp = _cfg_val(os.path.join(cfg_dir, 'printer.cfg'), 'resonance_tester', 'save_path', '')
    dirs = []
    for c in (sp, '/tmp', os.path.join(base_dir, 'compressor'), cfg_dir):
        if not c:
            continue
        c = os.path.expanduser(c)
        if not os.path.isabs(c):
            c = os.path.abspath(c)
        if c not in dirs and os.path.isdir(c):
            dirs.append(c)
    return dirs or ['/tmp']


def _find_resonance_csv(axis, dirs):
    """newest CSV for AXIS; prefers files that already carry a shaper table."""
    axis = axis.lower()
    cands = []
    for d in dirs:
        try:
            names = os.listdir(d)
        except OSError:
            continue
        for fn in names:
            if not fn.lower().endswith('.csv'):
                continue
            m = _RESONANCE_RE.match(fn)
            if m and m.group(2).lower() == axis:
                p = os.path.join(d, fn)
                try:
                    cands.append((os.path.getmtime(p), p))
                except OSError:
                    pass
    if not cands:
        return None
    cands.sort()
    fallback = None
    for _mt, p in reversed(cands):
        try:
            with open(p) as f:
                head = f.readline()
        except OSError:
            continue
        if 'shapers:' in head:
            return p
        if fallback is None:
            fallback = p
    return fallback


def _parse_resonance_csv(path):
    """Klipper resonance CSV -> dict(freqs, psd, shapers, normalized)."""
    with open(path) as f:
        lines = [l.rstrip('\n') for l in f]
    if not lines:
        raise ValueError('%s: empty CSV' % os.path.basename(path))
    cols = [c.strip() for c in lines[0].split(',')]
    if not cols or cols[0].lower() != 'freq':
        raise ValueError('%s: not a Klipper resonance CSV (first column %r)'
                         % (os.path.basename(path), cols[:1]))
    psd_idx = None
    if 'psd_xyz' in cols:
        psd_idx = cols.index('psd_xyz')
    else:
        for i, c in enumerate(cols[1:], 1):
            if 'psd' in c.lower():
                psd_idx = i
                break
        if psd_idx is None and len(cols) > 1:
            psd_idx = 1                        # multi-dataset: first data column
    if psd_idx is None:
        raise ValueError('%s: no PSD column' % os.path.basename(path))
    shapers = []                                # [(name, freq, col_index)]
    if 'shapers:' in cols:
        for i, c in enumerate(cols):
            m = re.match(r'^(\w+)\(([\d.]+)\)$', c.strip())
            if m and i > psd_idx:
                shapers.append((m.group(1).lower(), float(m.group(2)), i))
    freqs, psd = [], []
    for l in lines[1:]:
        if not l.strip():
            continue
        parts = l.split(',')
        try:
            fr = float(parts[0])
            pv = float(parts[psd_idx])
        except (IndexError, ValueError):
            continue
        freqs.append(fr)
        psd.append(pv)
    if len(freqs) < 8:
        raise ValueError('%s: only %d data rows - not a usable resonance CSV'
                         % (os.path.basename(path), len(freqs)))
    base = os.path.basename(path).lower()
    return {'freqs': freqs, 'psd': psd, 'shapers': shapers,
            'normalized': base.startswith(('calibrated', 'calibration_data'))}


def _resonance_axis_data(axis, dirs, scv=5.0):
    """CSV for one axis -> {'file', 'freqs', 'psd', 'table', 'best'}."""
    p = _find_resonance_csv(axis, dirs)
    if not p:
        raise ValueError('no resonance CSV for axis %s (looked in %s) - run '
                         'CALIBRATE_SHAPER or DUMP_RESONANCES first'
                         % (axis.upper(), ', '.join(dirs)))
    d = _parse_resonance_csv(p)
    freqs, psd = d['freqs'], d['psd']
    if not d['normalized']:
        psd = _normalize_psd(freqs, psd)
    keep = [i for i, f in enumerate(freqs) if f < 200.0]
    freqs = [freqs[i] for i in keep]
    psd = [psd[i] for i in keep]
    table = []
    if d['shapers']:
        # SHAPER_CALIBRATE already fitted these - keep ITS frequencies
        for name, freq, _ci in d['shapers']:
            if name not in SHAPER_MIN_FREQ:
                continue
            A, T = _shaper_get(name, freq)
            vibrs = 0.0
            for dr in SHAPER_TEST_DAMPINGS:
                v, _vals = _remaining_vibrations(A, T, dr, freqs, psd)
                if v > vibrs:
                    vibrs = v
            table.append({'name': name, 'freq': freq, 'vibrs': vibrs,
                          'smoothing': _shaper_smoothing(A, T, 5000.0, scv),
                          'score': None, 'max_accel': _shaper_max_accel(A, T, scv)})
    else:
        _best, table = _fit_shapers(freqs, psd, scv)
    for s in table:
        if s['score'] is None:
            s['score'] = s['smoothing'] * (s['vibrs'] ** 1.5 + s['vibrs'] * 0.2 + 0.01)
    best = _pick_best(table)
    return {'file': os.path.basename(p), 'freqs': freqs, 'psd': psd,
            'table': table, 'best': best}


# ======================================================================================
#  R64 RESONANCE DIAGRAM RENDERER - one portrait plate per axis (PSD curve,
#  all 5 shaper response curves, tick labels, and the SHAPER TABLE with the
#  recommendation boxed). MODE=print -> thin plate via the normal print flow
#  (mesh + purge line + babystepping, like every R2 file); MODE=plot -> the
#  same diagram as a pen-plotter file (R2-PLOT header).
# ======================================================================================

RESO_PLATE_W, RESO_PLATE_H = 112.0, 150.0


def _reso_plate_content(axis, data, measure):
    """one diagram plate -> (strokes, texts) in local mm (origin bottom-left).

    measure(text, height_mm) -> width in mm (font specific, set by the backend)
    """
    strokes = []
    texts = []          # (text, x, y_bottom, height_mm, align 'l'|'c')
    W, H = RESO_PLATE_W, RESO_PLATE_H
    table = data['table']
    best = data['best']
    freqs, psd = data['freqs'], data['psd']

    def _loop(pts):
        return list(pts) + [pts[0]]

    # R73: all heights are CAP heights now (was: box height ~0.53x that) and
    # y values are BASELINES - the plate text is finally as big as it reads
    def _fit_h(text, h, max_w):
        # shrink a text's cap height until it fits max_w (font-proportional:
        # the PIXEL print font is ~1.6x wider per cap than the stroke fonts)
        while h > 2.5 and measure(text, h) > max_w:
            h -= 0.25
        return h

    _title = '%s RESONANCES' % axis.upper()
    texts.append((_title, 4.0, H - 11.0, _fit_h(_title, 8.5, W - 8.0), 'l'))
    src = data['file']
    if len(src) > 26:
        src = src[:25] + '~'
    texts.append((src, 4.0, H - 16.0, _fit_h(src, 4.2, 56.0), 'l'))
    _dt = time.strftime('%Y-%m-%d')
    texts.append((_dt, W - 4.0, H - 16.0, _fit_h(_dt, 4.2, 38.0), 'r'))

    # ---- chart frame -------------------------------------------------------
    x0, x1 = 7.0, W - 7.0
    y0, y1 = 56.0, H - 24.0
    fmax = max(freqs)
    fmax = min(200.0, math.ceil(fmax / 10.0) * 10.0)
    fmax = max(50.0, fmax)

    def fx(f):
        return x0 + (f / fmax) * (x1 - x0)

    # ---- PSD curve (log scale like Klipper's graph) - FIRST = bold stroke --
    logs = [math.log10(max(p, 1e-12)) for p in psd]
    lmin, lmax = min(logs), max(logs)
    if lmax - lmin < 1e-6:
        lmax = lmin + 1.0
    pad = (lmax - lmin) * 0.06
    lmin, lmax = lmin - pad, lmax + pad

    def ly(v):
        return y0 + 1.5 + (v - lmin) / (lmax - lmin) * (y1 - y0 - 3.0)

    step = max(1, len(freqs) // 170)
    curve = [(fx(fr), ly(lv)) for fr, lv in zip(freqs[::step], logs)]
    if freqs[-1] != freqs[::step][-1]:
        curve.append((fx(freqs[-1]), ly(logs[-1])))
    strokes.append(curve)                    # index 0 - drawn double-weight

    strokes.append(_loop(_rect_loop(x0, y0, x1, y1)))
    # x ticks + labels
    tstep = 10.0 if fmax <= 110.0 else 20.0
    f = tstep
    while f < fmax:
        strokes.append([(fx(f), y0), (fx(f), y0 - 1.8)])
        _tk = '%d' % int(f)
        texts.append((_tk, fx(f), y0 - 7.0, _fit_h(_tk, 4.2, 11.0), 'c'))
        f += tstep
    texts.append(('Hz', x1, y0 - 7.0, _fit_h('Hz', 4.2, 10.0), 'r'))
    texts.append(('PSD', x0 + 1.0, y1 + 1.0, _fit_h('PSD', 3.5, 12.0), 'l'))

    # ---- shaper response curves (thin, ride high, dip at the notch) --------
    for s in table:
        try:
            A, T = _shaper_get(s['name'], s['freq'])
            resp = _shaper_response(A, T, SHAPER_DEFAULT_DAMPING, freqs[::step])
        except ValueError:
            continue
        strokes.append([(fx(fr), y1 - v * (y1 - y0) * 0.62)
                        for fr, v in zip(freqs[::step], resp)])

    # ---- peak marker --------------------------------------------------------
    pk = max(range(len(psd)), key=lambda i: psd[i])
    px, py = fx(freqs[pk]), ly(logs[pk])
    strokes.append(_loop(_circle(px, py, 1.1, 14)))
    _pk = '%dHz' % round(freqs[pk])
    _pkh = _fit_h(_pk, 4.2, 24.0)
    _pkw = measure(_pk, _pkh)
    # keep the centered label INSIDE the plate (a peak near the right edge
    # used to push the text past the plate border)
    _pkx = max(2.0 + _pkw / 2.0, min(W - 2.0 - _pkw / 2.0, px))
    texts.append((_pk, _pkx, py + 2.2 if py < y1 - 8 else py - 7.2, _pkh, 'c'))

    # ---- shaper table (R73: cap-height text ~1.8x the old visual size;
    #      columns + adaptive VIBR format keep everything clear of the 112mm) --
    hdr = [('NR', 3.5, 'l', 6.0), ('SHAPER', 9.5, 'l', 24.0), ('FREQ', 52.0, 'r', 15.0),
           ('VIBR', 73.0, 'r', 18.0), ('SMOOTH', 97.0, 'r', 17.0)]
    for t, x, al, mw in hdr:
        texts.append((t, x, 46.0, _fit_h(t, 4.0, mw), al))
    strokes.append([(4.0, 51.5), (W - 4.0, 51.5)])
    names = {'zv': 'ZV', 'mzv': 'MZV', 'zvd': 'ZVD', 'ei': 'EI',
             '2hump_ei': '2HUMP', '3hump_ei': '3HUMP'}
    for i, s in enumerate(table):
        y = 39.0 - i * 7.0
        texts.append(('%d' % (i + 1), 3.5, y, _fit_h('%d' % (i + 1), 4.5, 6.0), 'l'))
        _nm = names.get(s['name'], s['name'].upper())
        texts.append((_nm, 9.5, y, _fit_h(_nm, 4.5, 24.0), 'l'))
        _fr = '%.1f' % s['freq']
        texts.append((_fr, 52.0, y, _fit_h(_fr, 4.5, 15.0), 'r'))
        vib = s['vibrs'] * 100.0
        _vb = ('%.1f%%' % vib) if vib < 9.95 else ('%d%%' % round(vib))
        texts.append((_vb, 73.0, y, _fit_h(_vb, 4.5, 18.0), 'r'))
        _sm = '%.3f' % s['smoothing']
        texts.append((_sm, 97.0, y, _fit_h(_sm, 4.5, 17.0), 'r'))
        if s is best:
            strokes.append(_loop(_rect_loop(2.0, y - 2.0, 74.0, y + 6.5)))
            texts.append(('OK', W - 4.5, y, _fit_h('OK', 4.5, 9.0), 'r'))
    _pick = 'PICK: VIBRATION CAL > APPLY %s' % axis.upper()
    _ph = _fit_h(_pick, 4.2, W - 8.0)
    if measure(_pick, _ph) > W - 8.0:
        # very wide font: shorter wording instead of overflowing the plate
        # border (R286: the resonance plate prints SMOOTH now - PIXEL is
        # retired, R80 + the MCU-Shutdown risk)
        _pick = 'PICK: APPLY %s' % axis.upper()
        _ph = _fit_h(_pick, 4.2, W - 8.0)
    texts.append((_pick, 4.0, 2.5, _ph, 'l'))
    return strokes, texts


def _measure_text(text, h, font):
    """width of text at CAP height h mm (R73: sizes mean cap height now)."""
    g = _label_glyphs(font)
    scale = h / g['cap_units']
    return sum(g.get(ch, g.get(ch.upper(), (4.0, [])))[0] for ch in text) * scale


def _render_texts(texts, font):
    """backend text -> stroke polylines via the label font machinery.

    R73: (text, x, y_BASELINE, cap_height_mm, align) - y is the BASELINE the
    glyphs sit on (cap height above it, descenders below), so uppercase,
    lowercase and punctuation finally share one line.
    """
    g = _label_glyphs(font)
    out = []
    for text, x, y, h, align in texts:
        if not text:
            continue
        w = _measure_text(text, h, font)
        if align == 'c':
            x = x - w / 2.0
        elif align == 'r':
            x = x - w
        scale = h / g['cap_units']
        _w, _h, sts = _label_text(text, font)
        base = g['baseline']
        for st in sts:
            pts = [(x + px * scale, y + (base - py) * scale) for (px, py) in st]
            if len(pts) > 1:
                out.append(pts)
    return out


def make_resonance(axes=('x', 'y'), mode='print', out_dir='.', bed=None, version=1,
                   material='PLA', var_path=None, csv_dirs=None, scv=5.0,
                   layer_h=0.2, first_h=0.28, base_layers=3, feat_layers=2,
                   nozzle=0.6):
    """R64: render the resonance diagram plate(s). Returns (files, info)."""
    mode = str(mode).lower()
    if mode not in ('print', 'plot'):
        mode = 'print'
    axes = [str(a).lower() for a in axes if str(a).lower() in ('x', 'y')]
    if not axes:
        raise ValueError('AXIS must be X, Y or BOTH')
    if csv_dirs is None:
        csv_dirs = ['/tmp']
    data = {ax: _resonance_axis_data(ax, csv_dirs, scv=scv) for ax in axes}

    if bed is None:
        bed = (0.0, -1.0, 244.0, 238.0)
    bx0, by0, bx1, by1 = bed
    ux0, uy0 = bx0 + 6.0, by0 + 6.0
    ux1, uy1 = bx1 - 6.0, by1 - 6.0
    uw, uh = ux1 - ux0, uy1 - uy0

    files = []
    info = {'axes': {}, 'mode': mode}
    suffix = ''.join(a.upper() for a in axes)
    # both axes side by side if that fits, otherwise one file per axis
    grouped = len(axes) == 2 and (2 * RESO_PLATE_W + 6.0) <= uw and RESO_PLATE_H <= uh
    if grouped:
        plates = []
        gx0 = ux0 + (uw - (2 * RESO_PLATE_W + 6.0)) / 2.0
        gy0 = uy0 + (uh - RESO_PLATE_H) / 2.0
        for i, ax in enumerate(axes):
            plates.append((ax, gx0 + i * (RESO_PLATE_W + 6.0), gy0))
    else:
        plates = []
        for i, ax in enumerate(axes):
            if RESO_PLATE_W > uw or RESO_PLATE_H > uh:
                raise ValueError('diagram plate %dx%dmm does not fit the bed '
                                 '(%.0fx%.0fmm usable)' % (RESO_PLATE_W, RESO_PLATE_H, uw, uh))
            plates.append((ax, ux0 + (uw - RESO_PLATE_W) / 2.0, uy0 + (uh - RESO_PLATE_H) / 2.0))

    for ax, d in data.items():
        b = d['best']
        info['axes'][ax] = {
            'file': d['file'], 'best': b,
            'best_txt': '%s@%.1fHz %.1f%%' % (b['name'], b['freq'], b['vibrs'] * 100.0),
            'table': [(s['name'], round(s['freq'], 1), round(s['vibrs'] * 100.0, 1),
                       round(s['smoothing'], 3)) for s in d['table']]}

    if mode == 'plot':
        # ---- pen plotter variant ------------------------------------------------
        v = _read_vars(var_path) if var_path else {}

        def _vf(key, dflt):
            try:
                return float(v.get(key, dflt))
            except (TypeError, ValueError):
                return float(dflt)
        bmin_x, bmin_y = _vf('plot_bed_min_x', 5), _vf('plot_bed_min_y', 5)
        bmax_x, bmax_y = _vf('plot_bed_max_x', 239), _vf('plot_bed_max_y', 233)
        pw = max(20.0, min(RESO_PLATE_W, (bmax_x - bmin_x) - 4))
        ph = max(20.0, min(RESO_PLATE_H, (bmax_y - bmin_y) - 4))
        font = str(v.get('plot_text_font', 'SMOOTH') or 'SMOOTH').upper()
        if font not in ('SMOOTH', 'MONO', 'COND', 'NARROW', 'CAPS', 'SCRIPT', 'HAND', 'PLATE'):
            font = 'SMOOTH'
        lays = []
        lay_w = sum(1 for _ in plates)
        total_w = lay_w * pw + (lay_w - 1) * 6.0
        sx = min(1.0, ((bmax_x - bmin_x) - 4) / max(total_w, 0.001))
        sy = min(1.0, ((bmax_y - bmin_y) - 4) / ph)
        ox = bmin_x + (((bmax_x - bmin_x) - total_w * sx) / 2.0)
        oy = bmin_y + (((bmax_y - bmin_y) - ph * sy) / 2.0)
        for i, (ax, _gx, _gy) in enumerate(plates):
            strokes, texts = _reso_plate_content(ax, data[ax],
                                                  lambda t, h: _measure_text(t, h, font))
            polys = list(strokes) + _render_texts(texts, font)
            bx = ox + i * (pw + 6.0) * sx
            for pl in polys:
                lays.append([(bx + (px / RESO_PLATE_W) * pw * sx,
                              oy + (py / RESO_PLATE_H) * ph * sy) for px, py in pl])
        fname = 'V%02d_Resonance%splot.gcode' % (
            _next_gen_version(out_dir), suffix)
        fname = _dedupe_gen_fname(out_dir, fname)
        out = os.path.join(out_dir, fname)
        notes = ['; R2-RESONANCE diagram (pen plot) from %s'
                 % ', '.join(data[ax]['file'] for ax in axes),
                 '; shaper table + response curves - pick one, then Vibration Cal > Apply %s'
                 % '/'.join(a.upper() for a in axes)]
        _plot_write(out, lays, notes, var_path,
                    extrude=int(_vf('plot_extrude', 0)) == 1)
        files.append(out)
        info['file'] = fname
        return files, info

    # ---- 3d print variant ------------------------------------------------------
    wid = max(0.4, nozzle * 1.08)
    twid = max(0.4, nozzle * 1.02)
    fil = FIL_AREA
    total_layers = base_layers + feat_layers
    L = []
    a = L.append
    a(_core_stamp())      # R186: the R166 stamp for the normalize-bypassers
    a('; R2-RESONANCE generated diagram (R64) - start it like any other file')
    a('; axes: %s | source: %s' % (', '.join(a2.upper() for a2 in axes),
                                   ', '.join(data[ax]['file'] for ax in axes)))
    a('; plate %gx%gmm, %d base + %d feature layers @ %.2gmm (first %.2gmm), single color'
      % (RESO_PLATE_W, RESO_PLATE_H, base_layers, feat_layers, layer_h, first_h))
    for ax in axes:
        b = data[ax]['best']
        a('; %s shaper table: %s | recommended: %s'
          % (ax.upper(), ' '.join('%s(%.1fHz,%.1f%%)' % (s['name'], s['freq'], s['vibrs'] * 100.0)
                                  for s in data[ax]['table']),
             '%s@%.1fHz' % (b['name'], b['freq'])))
    a('; filament_type = %s' % material)
    a('; layer_height = %.2g' % layer_h)
    a('; nozzle_diameter = %.1f' % nozzle)
    a('; line_width = %.2g' % wid)
    a('; outer_wall_line_width = %.2g' % wid)
    a('; outer_wall_speed = 40')
    a('; inner_wall_speed = 45')
    a('; top_surface_speed = 40')
    a('; internal_solid_infill_speed = 55')
    a('; initial_layer_speed = 25')
    a('; travel_speed = 150')
    a('; wall_loops = 2')
    contents = {}
    for ax, gx, gy in plates:
        # R286 (Befund 4b): PIXEL retired (R80 + the MCU-Shutdown risk) -
        # the resonance plate prints SMOOTH now.
        strokes, texts = _reso_plate_content(ax, data[ax],
                                             lambda t, h: _measure_text(t, h, 'SMOOTH'))
        txt_strokes = _render_texts(texts, 'SMOOTH')
        contents[ax] = (gx, gy, strokes, txt_strokes)
        poly = '[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]' % (
            gx, gy, gx + RESO_PLATE_W, gy, gx + RESO_PLATE_W, gy + RESO_PLATE_H, gx, gy + RESO_PLATE_H)
        a('EXCLUDE_OBJECT_DEFINE NAME=RESONANCE_%s CENTER=%.1f,%.1f POLYGON=%s'
          % (ax.upper(), gx + RESO_PLATE_W / 2.0, gy + RESO_PLATE_H / 2.0, poly))
    a('PRINT_START MATERIAL=%s LAYER_HEIGHT=%.2g TOTAL_LAYERS=%d OUTER_WALL_SPEED=40'
      % (material, layer_h, total_layers))
    a('G90')
    a('M83')
    a('M107   ; R2-RESONANCE: first layer = fan off')

    pen = _Pen(L, jump_d=6.0)   # R77: no retracts between neighboring hatch lines

    def layer_h_eff(li):
        return first_h if li == 1 else layer_h

    def base_block(ax, li):
        gx, gy = contents[ax][0], contents[ax][1]
        x0, y0 = gx + wid / 2.0, gy + wid / 2.0
        x1, y1 = gx + RESO_PLATE_W - wid / 2.0, gy + RESO_PLATE_H - wid / 2.0
        e_wall = layer_h_eff(li) * wid / fil
        L.append('EXCLUDE_OBJECT_START NAME=RESONANCE_%s' % ax.upper())
        if li == 1:
            L.append(';TYPE:Brim')
            for off in (_brim_gap(wid) + wid, _brim_gap(wid)):
                b = (gx - off, gy - off, gx + RESO_PLATE_W + off, gy + RESO_PLATE_H + off)
                _emit_loop(pen, _rect_loop(*b), e_wall, 1500)
        L.append(';TYPE:Outer wall')
        _emit_loop(pen, _rect_loop(x0, y0, x1, y1), e_wall, 1500 if li == 1 else 2400)
        L.append(';TYPE:Inner wall')
        _emit_loop(pen, _rect_loop(x0 + wid, y0 + wid, x1 - wid, y1 - wid), e_wall,
                   1500 if li == 1 else 2700)
        L.append(';TYPE:Internal solid infill')
        segs = _hatch(x0 + wid + 0.1, y0 + wid + 0.1, x1 - wid - 0.1, y1 - wid - 0.1,
                      None, wid, 45.0 if li % 2 else 135.0)
        _emit_fill(pen, segs, e_wall, 1500 if li == 1 else 3300, wid)
        L.append('EXCLUDE_OBJECT_END NAME=RESONANCE_%s' % ax.upper())

    def feature_block(ax, li):
        gx, gy, strokes, txt_strokes = contents[ax]
        e_line = layer_h_eff(li) * twid / fil
        L.append('EXCLUDE_OBJECT_START NAME=RESONANCE_%s' % ax.upper())
        L.append(';TYPE:Outer wall')
        for pl in strokes:
            pen.travel(pl[0][0] + gx, pl[0][1] + gy, feed=9000, hop=True)
            px, py = pl[0]
            for (x, y) in pl[1:]:
                if math.hypot(x - px, y - py) < 0.12:
                    continue
                pen.extrude(gx + x, gy + y, math.hypot(x - px, y - py) * e_line, 1320)
                px, py = x, y
            if pl is strokes[0]:                 # PSD curve: second pass = bolder
                pen.travel(pl[0][0] + gx + 0.08, pl[0][1] + gy, feed=9000, hop=True)
                px, py = pl[0]
                for (x, y) in pl[1:]:
                    pen.extrude(gx + x + 0.08, gy + y, math.hypot(x - px, y - py) * e_line, 1320)
                    px, py = x, y
        for pl in txt_strokes:
            pen.travel(pl[0][0] + gx, pl[0][1] + gy, feed=9000, hop=True)
            px, py = pl[0]
            for (x, y) in pl[1:]:
                if math.hypot(x - px, y - py) < 0.12:
                    continue
                pen.extrude(gx + x, gy + y, math.hypot(x - px, y - py) * e_line, 1320)
                px, py = x, y
        L.append('EXCLUDE_OBJECT_END NAME=RESONANCE_%s' % ax.upper())

    for li in range(1, base_layers + 1):
        z = round(first_h + (li - 1) * layer_h, 3)
        L.append(';LAYER_CHANGE')
        L.append(';Z:%.3f' % z)
        pen.set_z(z)
        if li == 2:
            L.append('M106 S178   ; R2-RESONANCE: part fan from layer 2')
        for ax in axes:
            base_block(ax, li)
    for fi in range(1, feat_layers + 1):
        z = round(first_h + (base_layers - 1) * layer_h + fi * layer_h, 3)
        L.append(';LAYER_CHANGE')
        L.append(';Z:%.3f' % z)
        pen.set_z(z)
        for ax in axes:
            feature_block(ax, fi)
    a('M107')
    a('PRINT_END')

    fname = 'V%02d_Resonance%s.gcode' % (
        _next_gen_version(out_dir), suffix)
    fname = _dedupe_gen_fname(out_dir, fname)
    out = os.path.join(out_dir, fname)
    with open(out, 'w') as f:
        f.write('\n'.join(L) + '\n')
    try:
        process(out)
    except Exception as e:                                  # noqa: BLE001
        print('[reso] WARNING: post-process failed for %s: %r' % (fname, e), flush=True)
    files.append(out)
    info['file'] = fname
    info['layers'] = total_layers
    return files, info


# ======================================================================================
#  R64 TEXT -> PLOTTER (PLOT_TEXT / name.txt.gcode) + STATUS PLOT (PLOT_STATUS)
#  Plain text files are rendered with the label stroke fonts, auto-wrapped and
#  auto-scaled so the WHOLE text fits one page (= one plot).
# ======================================================================================

def _wrap_text(raw_lines, page_w, size, font):
    # R73: 'size' = CAP height in mm (was the full glyph box - the letters
    # printed at ~53% of the set size)
    glyphs = _label_glyphs(font)
    scale = size / glyphs['cap_units']

    def wlen(s):
        return sum(glyphs.get(ch, glyphs.get(ch.upper(), (4.0, [])))[0] for ch in s) * scale

    out = []
    for raw in raw_lines:
        raw = raw.rstrip()
        if not raw:
            out.append('')
            continue
        out.append('')                      # every source line starts a new line
        for chunk in raw.split(' '):
            # hard-split single words wider than the page
            while wlen(chunk) > page_w and len(chunk) > 1:
                k = len(chunk)
                while k > 1 and wlen(chunk[:k]) > page_w:
                    k -= 1
                out[-1] = chunk[:k]
                out.append('')
                chunk = chunk[k:]
            cur = out[-1]
            cand = chunk if cur == '' else (cur + ' ' + chunk)
            if wlen(cand) <= page_w:
                out[-1] = cand
            else:
                out.append(chunk)
    while out and out[-1] == '':
        out.pop()
    return out


def _fit_text_page(raw_lines, page_w, page_h, size, font, min_size=6.0):
    """R73: letters never shrink below 6mm caps - the page grows COLUMNS
    instead (up to 3 side by side), and only a truly huge text gets truncated
    with a note. Returns (columns, size): columns = list of line-lists."""
    size = max(min_size, size)
    for ncols in (1, 2, 3):
        col_w = (page_w - (ncols - 1) * 6.0) / ncols
        lines = _wrap_text(raw_lines, col_w, size, font)
        per_col = max(1, int(page_h // (size * 1.5)))
        if len(lines) <= ncols * per_col:
            cols = [lines[i * per_col:(i + 1) * per_col]
                    for i in range(ncols)]
            return cols, size
    # still too long at 3 columns: truncate with a note line
    col_w = (page_w - 12.0) / 3.0
    lines = _wrap_text(raw_lines, col_w, size, font)
    per_col = max(1, int(page_h // (size * 1.5)))
    total = 3 * per_col
    if len(lines) > total:
        cut = len(lines) - total
        lines = lines[:total - 1] + ['(+%d more lines)' % cut]
    cols = [lines[i * per_col:(i + 1) * per_col] for i in range(3)]
    return cols, size


def _text_page_polys(cols, page_w, page_h, size, font, solid=False, line_w=0.65):
    """text columns -> polylines in page coords (origin bottom-left, y up).

    R73: baseline-aligned glyphs (shared baseline per line), 'size' = cap
    height. solid=True expands every stroke into a double-walled bundle
    (_stroke_offsets) so FILAMENT plots read solid instead of hairlines.
    """
    g = _label_glyphs(font)
    scale = size / g['cap_units']
    lh = size * 1.5
    ncols = max(1, len(cols))
    col_w = (page_w - (ncols - 1) * 6.0) / ncols
    polys = []
    for c, lines in enumerate(cols):
        col_x = c * (col_w + 6.0)
        for i, line in enumerate(lines):
            if not line:
                continue
            _w, _h, sts = _label_text(line, font)
            base_y = page_h - (i + 1) * lh
            # center the line block horizontally in its column
            lw = _w * scale
            x_off = col_x + (col_w - lw) / 2.0
            for st in sts:
                pts = [(x_off + px * scale,
                        base_y + (g['baseline'] - py) * scale) for (px, py) in st]
                if len(pts) < 2:
                    continue
                if solid:
                    half = min(3.0 * line_w, 0.34 * size) / 2.0
                    for path in _stroke_offsets(pts, half, line_w):
                        polys.append(path)
                else:
                    polys.append(pts)
    return polys


def _plot_write(path, polys, notes, var_path=None, extrude=False):
    """shared pen-plotter g-code writer (single pen).

    R73 FILAMENT mode: the old writer dragged the nozzle at the PEN z (0mm) -
    nothing could exit the nozzle, the plot came out as faint hairs. Filament
    plots now run at a real draw height (plot_fil_z, default 0.25mm) with the
    matching extrusion per mm, a small retract on far travels and SHORT flat
    travels between nearby strokes (no hop, no retract = far fewer 'hops').
    Pen mode keeps the classic up/down taps. Travel is capped at 80mm/s.
    """
    v = _read_vars(var_path) if var_path else {}

    def _vf(key, dflt):
        try:
            return float(v.get(key, dflt))
        except (TypeError, ValueError):
            return float(dflt)
    z_up = _vf('plot_z_up', 3.0)
    spd = _vf('plot_speed', 40) * 60
    trv = min(_vf('plot_travel', 120) * 60, 4800.0)
    e_per_mm = 0.0
    z_dn = _vf('plot_z_down', 0.0) + _vf('plot_off_z', 0.0)
    if extrude:
        fil_z = min(0.4, max(0.1, _vf('plot_fil_z', 0.20)))
        z_dn = _vf('plot_off_z', 0.0) + fil_z
        e_per_mm = fil_z * 0.65 / FIL_AREA
    L = ['; R2-PLOT v4 - %s' % (notes[0][2:] if notes and notes[0].startswith('; ') else 'pen plot')]
    L += notes[1:]
    if extrude:
        L.append('; R149: FILAMENT mode - the bed heats + a purge line runs '
                 'before the drawing (thin lines need a warm bed)')
    L += ['; mode: %s | draw Z %.2f | travel capped 80mm/s' % ('FILAMENT' if extrude else 'PEN', z_dn),
          '; pen Z/speeds/mode/offsets: Plotter menu | live: speed %, babystepping = pen pressure',
          '; start overrides (speed/Z/XY) apply at plot start: Plotter > Start',
          TAG,
          '_PLOT_START EXTRUDE=%d' % (1 if extrude else 0),
          'G21',
          'G90']
    # R75: register the plot area as an object - the mesh before the held file
    # runs then covers the plot area only (KAMP adaptive) instead of the full
    # bed (field log .58: full-bed mesh travels = 'Timer too close' shutdowns)
    if polys:
        _xs = [p[0] for pts in polys for p in pts]
        _ys = [p[1] for pts in polys for p in pts]
        _x0, _x1, _y0, _y1 = min(_xs), max(_xs), min(_ys), max(_ys)
        _poly = '[[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f],[%.1f,%.1f]]' % (
            _x0, _y0, _x1, _y0, _x1, _y1, _x0, _y1)
        L.append('EXCLUDE_OBJECT_DEFINE NAME=R2PLOT CENTER=%.1f,%.1f POLYGON=%s'
                 % ((_x0 + _x1) / 2.0, (_y0 + _y1) / 2.0, _poly))
        L.append('EXCLUDE_OBJECT_START NAME=R2PLOT')
    if extrude:
        L += ['M83', 'G92 E0']
    _emit_plot(L, polys, trv, spd, extrude, z_up, z_dn, e_per_mm)
    if polys:
        L.append('EXCLUDE_OBJECT_END NAME=R2PLOT')
    # R222 (.136t): _PLOT_END after the park (pen up, head aside) - heaters
    # off + speed back to 100. FILAMENT plots kept extruder AND bed at
    # temperature after the end; PEN plots kept the selection preheat; a
    # plot M220 override survived into the next job (no layer 2 in a plot
    # to release it). The plot parks itself - no PRINT_END (no layers, no
    # stats choreography); the state watcher's complete-branch is the
    # backstop for plot files written before this hook.
    L += ['G0 Z%.2f F600' % (z_up + 5), 'G0 X5 Y190 F4800',
          '_PLOT_END', 'M107', 'M84']
    with open(path, 'w') as f:
        f.write('\n'.join(L) + '\n')
    return len(L)


def _emit_plot(L, polys, trv, spd, extrude, z_up, z_dn, e_per_mm, connect_mm=2.2):
    """R73 plot move emitter - shared by _plot_write and plot_convert.

    Polylines are drawn pen-down; between strokes: far = retract (filament) +
    z-hop + travel, near (<= connect_mm) = short flat travel (filament) or a
    quick hop (pen). Single points = stipple dots.
    """
    cx = cy = None
    for pts in polys:
        if len(pts) < 2:
            if not pts:
                continue
            x0, y0 = pts[0]
            _travel(L, cx, cy, x0, y0, trv, extrude, z_up, z_dn)
            L.append('G1 Z%.2f F600' % z_dn)
            if extrude:
                L.append('G1 E%.3f F120' % max(0.06, e_per_mm * 1.4))
            L.append('G0 Z%.2f F600' % z_up)
            cx, cy = x0, y0
            continue
        x0, y0 = pts[0]
        _travel(L, cx, cy, x0, y0, trv, extrude, z_up, z_dn, connect_mm)
        L.append('G1 Z%.2f F600' % z_dn)
        px, py = x0, y0
        for x, y in pts[1:]:
            d = math.hypot(x - px, y - py)
            if d < 0.02:
                continue
            if extrude:
                L.append('G1 X%.2f Y%.2f E%.4f F%d' % (x, y, d * e_per_mm, spd))
            else:
                L.append('G1 X%.2f Y%.2f F%d' % (x, y, spd))
            px, py = x, y
        L.append('G0 Z%.2f F600' % z_up)
        cx, cy = px, py


def _travel(L, cx, cy, x, y, trv, extrude, z_up, z_dn, connect_mm=2.2):
    if cx is None:
        L.append('G0 X%.2f Y%.2f F%d' % (x, y, trv))
        return
    d = math.hypot(x - cx, y - cy)
    if extrude:
        if d <= connect_mm:
            L.append('G0 X%.2f Y%.2f F%d' % (x, y, trv))    # flat: keeps pressure
            return
        L.append('G10')
        L.append('G0 Z%.2f F600' % z_up)
        L.append('G0 X%.2f Y%.2f F%d' % (x, y, trv))
        L.append('G0 Z%.2f F600' % z_dn)
        L.append('G11')
    else:
        L.append('G0 Z%.2f F600' % z_up)
        L.append('G0 X%.2f Y%.2f F%d' % (x, y, trv))
        L.append('G0 Z%.2f F600' % z_dn)


def text_convert(path, out=None, var_path=None):
    """R64: convert a plain text file into a pen-plotter g-code page."""
    with open(path, 'rb') as f:
        data = f.read()
    text = data.decode('utf-8', errors='replace')
    text = text.replace('\r\n', '\n').replace('\r', '\n').replace('\t', '    ')
    allowed = set(LABEL_CHARSET) | {' '}
    raw = []
    for l in text.split('\n')[:400]:
        raw.append(''.join(ch if ch in allowed else '?' for ch in l.rstrip()))
    if not [l for l in raw if l.strip()]:
        raise ValueError('%s: no printable text' % os.path.basename(path))
    v = _read_vars(var_path) if var_path else {}

    def _vf(key, dflt):
        try:
            return float(v.get(key, dflt))
        except (TypeError, ValueError):
            return float(dflt)
    bmin_x, bmin_y = _vf('plot_bed_min_x', 5), _vf('plot_bed_min_y', 5)
    bmax_x, bmax_y = _vf('plot_bed_max_x', 239), _vf('plot_bed_max_y', 233)
    page_w = (bmax_x - bmin_x) - 8.0
    page_h = (bmax_y - bmin_y) - 8.0
    size = max(6.0, min(_vf('plot_text_size', 7.0), 20.0))    # R73: >=6mm caps
    font = str(v.get('plot_text_font', 'SMOOTH') or 'SMOOTH').upper()
    if font not in ('SMOOTH', 'MONO', 'COND', 'NARROW', 'CAPS', 'SCRIPT', 'HAND', 'PLATE'):
        font = 'SMOOTH'
    cols, size = _fit_text_page(raw, page_w, page_h, size, font)
    extrude = int(_vf('plot_extrude', 0)) == 1
    polys = _text_page_polys(cols, page_w, page_h, size, font,
                             solid=extrude, line_w=0.65)
    polys = [[(px + bmin_x + 4.0, py + bmin_y + 4.0) for (px, py) in pl] for pl in polys]
    out = out or (path if path.endswith('.gcode') else path + '.gcode')
    n_lines = sum(len(c) for c in cols)
    notes = ['; text plot: %d line(s) in %d column(s), font %s, %.1fmm CAP letters'
             % (n_lines, len(cols), font, size),
             '; source: %s' % os.path.basename(path)]
    _plot_write(out, polys, notes, var_path, extrude=extrude)
    return out, n_lines, size


def _printer_busy(host='127.0.0.1', port=7125):
    """R133c (field logs .95/.96): lean busy probe - start phase INCLUDED.

    print_stats only says 'printing' once the SD card job streams - but
    homing, heating, mesh and purge run BEFORE that, with the state still
    'standby' (the .96 field log: 'Missed scheduling of next digital out
    event' while the bed heated and a litho job churned). The R2 _STATE
    mode covers that window: waiting (start dialog + its homing),
    starting, printing, paused, filament. Unreachable moonraker = 'not
    busy' (never block the watcher).
    """
    def _probe162():
        import urllib.parse
        import urllib.request
        url = ('http://%s:%d/printer/objects/query?%s'
               % (host, port,
                  urllib.parse.quote(
                      'print_stats gcode_macro _STATE idle_timeout '
                      'toolhead')))
        with urllib.request.urlopen(url, timeout=1.5) as r:
            js = json.loads(r.read().decode())
        _st = ((js.get('result') or {}).get('status') or {})
        if (_st.get('print_stats') or {}).get('state', '') \
                in ('printing', 'paused'):
            return True
        # R246d: motion is busy too - a manual preheat + G28/homing runs
        # in mode 'idle' (the 04:04 blind spot). Same query, no extra
        # request; _motion_active246d compares print_time against the
        # last pass (idle_timeout alone lingers 'Printing' for the
        # configured 3600 s after the last move - see there).
        if _motion_active246d(_st, 'busy'):
            return True
        _mode = (_st.get('gcode_macro _STATE') or {}).get('mode', '')
        # R255: 'homing' is a mode the macros set BEFORE G28 - the start
        # dialog's homing ran with mode 'idle' and every gate was blind.
        return _mode in ('waiting', 'starting', 'homing', 'printing',
                         'paused', 'filament')
    # R162 (.121 field log): a probe TIMEOUT returned 'not busy' on the
    # memory-pressured Pi - a litho build started DURING the print and the
    # MCU died with 'Timer too close'. One retry closes the transient
    # hole; a truly unreachable moonraker still reads as not busy.
    for _try162 in (1, 2):

        try:
            return _probe162()
        except Exception:                               # noqa: BLE001
            if _try162 == 2:
                return False


# R255 (.142k, the 12.11. FIELD LOG that kept dying at the same place):
# every consumer now has its OWN print_time sample slot, and a detected move
# arms a HOLD. Two reasons, both from the log:
#  * the old code kept ONE shared sample ('pt'). _printer_busy() sampled it
#    at the top of a pass, the preview probe sampled again milliseconds
#    later - the delta was always ~0, so the preview probe answered "not
#    moving" and pushed its 4 KB script straight into the homing window
#    (log 597.375 s: two identical giant scripts while G28 ran).
#  * between the two probe contacts the head stands still for seconds, so a
#    single sample pair says "quiet" right in the worst moment. A move that
#    happened within _MOTION_HOLD255 seconds keeps the gate closed.
_MOTION_HOLD255 = 2.0
_MOTION246D = {}                  # R246d (R255: ONE SLOT PER CONSUMER)
_MOTION_SEEN255 = [0.0]           # last time real motion was observed


def _motion_seen255():
    """True while a move was seen less than _MOTION_HOLD255 s ago."""
    return (time.time() - _MOTION_SEEN255[0]) < _MOTION_HOLD255


def _motion_active246d(st, slot='busy'):
    """R246d: TRUE motion - toolhead.print_time advanced since the last
    call OF THIS SLOT. idle_timeout.state 'Printing' alone is NOT a live
    signal: with the configured timeout: 3600 it stays 'Printing' for up to
    an HOUR after the last move (found in review BEFORE release - gating on
    it alone would have silenced the watcher for an hour after any preheat
    wiggle). print_time only advances while the move queue actually runs;
    frozen between two samples of the same slot = drained queue.
    R255: plus the 2 s hold above (a probe dwell is still motion)."""
    _ito246d = st.get('idle_timeout') or {}
    _pt246d = (st.get('toolhead') or {}).get('print_time')
    if _pt246d is None:
        return _motion_seen255()
    _prev246d = _MOTION246D.get(slot)
    _MOTION246D[slot] = _pt246d
    if _ito246d.get('state', '') != 'Printing':
        return _motion_seen255()          # klippy says quiet - hold only
    if _prev246d is None:
        _MOTION_SEEN255[0] = time.time()  # first look, gcode is running
        return True
    if _pt246d > _prev246d + 1e-9:
        _MOTION_SEEN255[0] = time.time()
        return True
    return _motion_seen255()


def _printer_moving(host='127.0.0.1', port=7125):
    """R246d (.142b field log 04:04): MOTION probe for the preview push.

    A manual preheat + G28/homing runs with _STATE mode 'idle' AND
    print_stats 'idle' - both busy checks were blind exactly there while
    the 04:04 print start died with 'Timer too close' in a reactor window
    that carried our own status queries and a 2 KB preview script.
    Uses _motion_active246d (print_time delta vs the sample the pass
    already took - see there why idle_timeout alone would lie for up to
    an hour). Unreachable moonraker counts as moving (fail-safe: defer)."""
    import urllib.parse
    import urllib.request
    try:
        url = ('http://%s:%d/printer/objects/query?%s'
               % (host, port,
                  urllib.parse.quote('idle_timeout toolhead '
                                     'gcode_macro _STATE')))
        with urllib.request.urlopen(url, timeout=2.0) as r:
            js = json.loads(r.read().decode())
        _st = ((js.get('result') or {}).get('status') or {})
        # R255: the G28 guard wrapper marks EVERY homing as mode 'homing'.
        # That is the reliable signal for the whole probe sequence - a probe
        # dwell can be longer than the 2 s motion hold, and the two contacts
        # are exactly where the field log died. 'waiting' (the open start
        # dialog) is NOT motion: that is when the preview is wanted.
        _m255 = ((_st.get('gcode_macro _STATE') or {}).get('mode') or '')
        if str(_m255).strip().lower() in ('homing', 'starting'):
            _MOTION_SEEN255[0] = time.time()
            return True
        return _motion_active246d(_st, 'preview')
    except Exception:                                       # noqa: BLE001
        return True         # cannot say -> assume motion, defer


def _printer_idle_strict(host='127.0.0.1', port=7125):
    """R246c (.142 field log 00:08): the PUSH gate - confirmed idle ONLY.

    _printer_busy() must never block the watcher itself, so an unreachable
    moonraker reads as 'not busy' there. That is the right default for
    jobs and checks - and the wrong one for VARIABLE pushes: during the
    00:03-00:08 frame print the daemon kept flooding the console with the
    full _SDM mirror every cycle, its own load made the 1.5 s busy probe
    time out, 'not busy' opened the gate again and the spiral ended in
    'MCU shutdown: Timer too close' at 00:08:21. For pushes the fail-safe
    direction flips: an UNANSWERED probe counts as BUSY. A moonraker that
    cannot answer a 3 s query will not accept the push anyway, and a
    push into a struggling klippy is exactly what must never happen.
    One probe, no retry - the next cycle gets a fresh vote.
    """
    import urllib.parse
    import urllib.request
    try:
        url = ('http://%s:%d/printer/objects/query?%s'
               % (host, port,
                  urllib.parse.quote(
                      'print_stats gcode_macro _STATE idle_timeout '
                      'toolhead')))
        with urllib.request.urlopen(url, timeout=3.0) as r:
            js = json.loads(r.read().decode())
        _st = ((js.get('result') or {}).get('status') or {})
        if (_st.get('print_stats') or {}).get('state', '') \
                in ('printing', 'paused'):
            return False
        # R246d: motion blocks pushes too (mode 'idle' homing/preheat -
        # the 04:04 field crash). Same query, zero extra requests; the
        # print_time delta is the truth (idle_timeout lingers).
        if _motion_active246d(_st, 'strict'):     # R255: own sample slot
            return False
        _mode = (_st.get('gcode_macro _STATE') or {}).get('mode', '')
        # R255: 'homing' closes this gate too - the SD mirror push is the
        # biggest script the daemon sends, it must never land in a probe.
        return _mode not in ('waiting', 'starting', 'homing', 'printing',
                             'paused', 'filament')
    except Exception:                                       # noqa: BLE001
        return False        # probe failed -> treat as busy, do NOT push


# R133b (field log .95): generator jobs run ONE AT A TIME through a queue -
# the field Pi had ELEVEN litho threads at once (every Create press spawned
# another) and drowned in swap until klipper starved ('Timer too close'
# while homing). One worker, dedup on the job key, micro-pauses in the hot
# loops, klipper always wins the CPU (os.nice on the watcher).
_JOB_YIELD = {'on': False, 'n': 0}
import threading as _threading133
_JOB_STATE = {'queue': [], 'keys': set(), 'busy': False,
              'lock': _threading133.Lock(),
              # R224 (.136v field review): the CURRENT build thread (normal
              # or abandoned-stuck) + the zombie marker. gen_busy and the
              # queue stay HELD while it lives - .136u freed both on clear
              # and on the stuck timeout although the thread kept burning
              # RAM/CPU, so a print could start straight into the overload
              # the flag exists to prevent.
              'job_ids': {}, 'registry': None,
              'thread': None, 'zombie': None, 'zombie_notice': 0.0}


def _get_job_registry():
    reg = _JOB_STATE.get('registry')
    if reg is None:
        try:
            from r2_job_service import JobRegistry as _JR
            reg = _JR(max_history=64)
            _JOB_STATE['registry'] = reg
        except Exception:                                  # noqa: BLE001
            return None
    return reg

# R223 (.136s field log): a generator job that never returns (the photo
# string-art build ground the 512MB Pi into swap-thrash for 27+ minutes)
# used to wedge the single worker thread FOREVER - its key blocked every
# retry, gen_busy=1 stayed up and blocked print starts. The worker now runs
# each build in its own thread and abandons it after this timeout.
JOB_STUCK_S = 1200          # 20 min: every real build stays well under it

# R236 (.136af field log): the queue depth as a save_variable - the LCD
# main menu shows 'Gen queue: N' and the number DROPS with every finished
# job (the field log: 'when is my file's turn? I only hear beeps'). Pushed
# on every change (enqueue / dispatch / finish / clear); a failed push
# simply retries on the next change.
_GENQ_PUSHED = [None]


class _JobCancelled(Exception):
    """R238 (.136ai): raised inside generator hot loops by _job_tick when
    the user cancels from the queue menu - 'SKIP' kills the CURRENT job
    (the next one starts), 'STOP' also clears the waiting line. The job
    worker deletes the partial output and reports."""


def _job_drop_pending_locked(state):
    """Drop queued items and their dedup keys, preserving any running key.

    Caller must hold state['lock']. Never call external code under this lock.
    """
    pending = state['queue']
    count = len(pending)
    for item in pending:
        state['keys'].discard(item[1])
    pending.clear()
    return count


def _genq_push():
    """R236: keep save_variables.gen_queue_cnt == len(job queue)."""
    with _JOB_STATE['lock']:
        n = len(_JOB_STATE['queue'])
    if _GENQ_PUSHED[0] == n:
        return
    try:
        _moonraker_gcode('SAVE_VARIABLE VARIABLE=gen_queue_cnt VALUE=%d' % n)
        _GENQ_PUSHED[0] = n
    except Exception:                                       # noqa: BLE001
        pass


def _moonraker_filelist_notify(relpath, host='127.0.0.1', port=7125):
    """R236: tell moonraker a file appeared that its file manager missed
    (field log .136af: the web UI folder did not show the new g-code).
    POST /server/files/notify_filelist_changed?path=<rel> makes moonraker
    re-check the path and push the list to every connected client. Best
    effort - an old moonraker answers 404, the caller logs and moves on."""
    import urllib.request
    import urllib.parse
    url = ('http://%s:%d/server/files/notify_filelist_changed?path=%s'
           % (host, port, urllib.parse.quote(relpath)))
    req = urllib.request.Request(url, method='POST', data=b'')
    with urllib.request.urlopen(req, timeout=3.0) as r:
        return 200 <= r.status < 300


def _copy_picked_image(directory, relative):
    """Copy a selected image into the root without replacing existing files.

    Return (root basename, copied). A root image is validated but not copied.
    A nested path is opened component by component without following symlinks;
    the output is first written under a private temporary name, then published
    by an atomic no-replace hard link. Unsupported filesystems fail closed.
    This validates path and regular-file status, not the image's pixel data.
    """
    import secrets
    import stat

    name = str(relative or '').strip().lstrip('/')
    parts = name.split('/')
    if (not name or any(p in ('', '.', '..') for p in parts)
            or '\\' in name or any(ord(c) < 32 or ord(c) == 127 for c in name)
            or any(c in name for c in ('"', "'", ';'))
            or os.path.splitext(name)[1].lower() not in ('.png', '.jpg', '.jpeg')):
        raise ValueError('not a safe image path')
    if not all(hasattr(os, flag) for flag in ('O_DIRECTORY', 'O_NOFOLLOW', 'O_NONBLOCK')):
        raise OSError('safe image copy is not supported on this platform')

    root_fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY)
    opened_dirs = []
    temp_name = None
    try:
        parent_fd = root_fd
        for part in parts[:-1]:
            parent_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                                dir_fd=parent_fd)
            opened_dirs.append(parent_fd)
        src_fd = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                         dir_fd=parent_fd)
        try:
            before = os.fstat(src_fd)
            if not stat.S_ISREG(before.st_mode):
                raise ValueError('image source is not a regular file')
        except Exception:
            os.close(src_fd)
            raise
        with os.fdopen(src_fd, 'rb') as src:
            if len(parts) == 1:
                return parts[0], False

            # The temporary file is exclusively created in the root and is
            # invisible to the image list until all bytes have been copied.
            for _ in range(100):
                candidate = '.r2-img-' + secrets.token_hex(12) + '.tmp'
                try:
                    temp_fd = os.open(candidate, os.O_WRONLY | os.O_CREAT | os.O_EXCL
                                      | os.O_NOFOLLOW, 0o600, dir_fd=root_fd)
                    temp_name = candidate
                    break
                except FileExistsError:
                    continue
            else:
                raise OSError('cannot create an exclusive image staging file')
            with os.fdopen(temp_fd, 'wb') as out:
                shutil.copyfileobj(src, out, length=1024 * 1024)
                out.flush()
                after = os.fstat(src.fileno())
                if ((before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
                        != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)):
                    raise OSError('image changed while being copied')
                os.fchmod(out.fileno(), stat.S_IMODE(before.st_mode))
                os.utime(out.fileno(), ns=(before.st_atime_ns, before.st_mtime_ns))
                os.fsync(out.fileno())

        stem, ext = os.path.splitext(parts[-1])
        for number in range(10000):
            target = parts[-1] if number == 0 else '%s_%d%s' % (stem, number, ext)
            try:
                os.link(temp_name, target, src_dir_fd=root_fd, dst_dir_fd=root_fd,
                        follow_symlinks=False)
                return target, True
            except FileExistsError:
                continue
        raise OSError('no free image name found')
    finally:
        if temp_name is not None:
            try:
                os.unlink(temp_name, dir_fd=root_fd)
            except FileNotFoundError:
                pass
        for fd in reversed(opened_dirs):
            os.close(fd)
        os.close(root_fd)


def _job_tick(step=1, every=25, pause=0.02):
    """Micro-pause inside generator hot loops - only while a job worker
    owns the call (tests call the generators directly and stay fast).

    R133c: when the printer turns busy MID-JOB (start dialog, homing,
    heating), the tick switches to a 2s hold - a running job freezes
    cooperatively instead of starving the start phase, and resumes on
    its own when the machine idles."""
    if not _JOB_YIELD['on']:
        return
    # R238: the cancel door - checked in every generator hot loop
    _k238 = _JOB_STATE.get('kill')
    if _k238:
        raise _JobCancelled(_k238)
    _JOB_YIELD['n'] += step
    if _JOB_YIELD['n'] >= every:
        _JOB_YIELD['n'] = 0
        if _JOB_YIELD.get('busy_aware', True) and _printer_busy():
            # hold (not abort): the print start has absolute priority
            while _printer_busy():
                time.sleep(2.0)
        time.sleep(pause)


def _moonraker_status(host='127.0.0.1', port=7125, objs=None):
    """query the live printer status via moonraker (best effort).
    R246: objs parameter - callers can query their own object set
    (the LCD mirror reads 'gcode_macro _SDM'); the default keeps the
    dashboard list unchanged."""
    import urllib.request
    import urllib.parse
    if objs is None:
        objs = ['gcode_move', 'extruder', 'heater_bed', 'toolhead',
                'input_shaper', 'bed_mesh', 'print_stats',
                'gcode_macro _STATE', 'exclude_object']
    url = 'http://%s:%d/printer/objects/query?%s' % (
        host, port, '&'.join(urllib.parse.quote(o) for o in objs))
    with urllib.request.urlopen(url, timeout=3) as r:
        js = json.loads(r.read().decode())
    return (js.get('result') or {}).get('status') or {}


def _r2_version():
    try:
        p = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                         '..', 'macros', '01_state.cfg')
        with open(p) as f:
            for l in f:
                m = re.match(r'\s*variable_version\s*[:=]\s*[\'"]?([^\'"\s#]+)', l)
                if m:
                    return m.group(1)
    except OSError:
        pass
    return '?'


